INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b2d0720-2df4-4a4a-96ec-e126e219563c', '十二時歌 十', '十二时歌 十', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["黃昏戌，獨坐一間空暗室。","陽燄燈光永不逢，眼前純是金州漆。","鐘不聞，虛度日，唯聞老鼠鬧啾唧。","憑何更得有心情，思量念箇波羅蜜。"]', '["黄昏戌，独坐一间空暗室。","陽燄灯光永不逢，眼前純是金州漆。","鐘不闻，虛度日，唯闻老鼠鬧啾唧。","憑何更得有心情，思量念箇波羅蜜。"]', '诗', 'shi', '', NULL, '十二時歌 十 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca337a3-f0a7-45c6-9cb5-43bc7fc3a9de', '十二時歌 十一', '十二时歌 十一', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["人定亥，門前明月誰人愛。","向裏唯愁臥去時，勿箇衣裳着甚蓋。","劉維那，趙五戒，口頭說善甚奇怪。","任你山僧囊罄空，問着都緣總不會。"]', '["人定亥，门前明月誰人愛。","向裏唯愁臥去时，勿箇衣裳着甚蓋。","劉維那，趙五戒，口头说善甚奇怪。","任你山僧囊罄空，问着都緣總不會。"]', '诗', 'shi', '', NULL, '十二時歌 十一 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0691f85b-36df-4bcc-b5be-6183f2992879', '十二時歌 十二', '十二时歌 十二', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["半夜子，心境何曾得暫止。","思量天下出家人，似我住持能有幾？","土榻牀，破蘆蕟{下爲廢}，老榆木枕全無被。","尊香不燒安息香，灰裏唯聞牛糞氣。","（此組詩又見《禪門諸祖師偈頌》卷上之下）。"]', '["半夜子，心境何曾得暫止。","思量天下出家人，似我住持能有幾？","土榻牀，破蘆蕟{下爲廢}，老榆木枕全無被。","尊香不燒安息香，灰裏唯闻牛糞氣。","（此組诗又见《禪门諸祖師偈頌》卷上之下）。"]', '诗', 'shi', '', NULL, '十二時歌 十二 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dcd7ee9-6c93-42f9-bb90-b2bb5f17b52c', '因見諸書見解異途乃有頌', '因见諸书见解異途乃有頌', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["石橋南，趙州北，中有觀音有彌勒。","祖師留下一隻履，直到如今覓不得。","（此首又見《祖堂集》卷十八）。"]', '["石橋南，趙州北，中有观音有彌勒。","祖師留下一隻履，直到如今覓不得。","（此首又见《祖堂集》卷十八）。"]', '诗', 'shi', '', NULL, '因見諸書見解異途乃有頌 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d00fb5d-d5e8-474f-9c7d-e5d9d058d047', '因魚鼓有頌', '因鱼鼓有頌', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["四大猶（《五燈會元》卷四作「由」）來造化功，有聲全貴裏頭空。","莫怪不與凡夫說，祇爲宮商調不同。"]', '["四大猶（《五灯會元》卷四作「由」）来造化功，有声全貴裏头空。","莫怪不與凡夫说，祇爲宮商調不同。"]', '诗', 'shi', '', NULL, '因魚鼓有頌 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab352eb-46af-48ae-88a9-046b7fb129dd', '因蓮花有頌', '因蓮花有頌', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["奇異根苗帶雪鮮，不知何代別西天。","淤泥深淺人不識，出水方知是白蓮。"]', '["奇異根苗带雪鲜，不知何代別西天。","淤泥深淺人不識，出水方知是白蓮。"]', '诗', 'shi', '', NULL, '因蓮花有頌 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42b81f8-6746-4972-bd27-459123f6a206', '頌', '頌', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["渠說佛有難，我說渠有災。","但看我避難，何處有相隨？","有無不是說，去來非去來。","爲你說難法，對面識得來。","（以上十六首均見宋渭頤藏主《古尊宿語錄》卷十四《趙州真際禪師語錄》卷下）。"]', '["渠说佛有难，我说渠有災。","但看我避难，何处有相隨？","有無不是说，去来非去来。","爲你说难法，对面識得来。","（以上十六首均见宋渭頤藏主《古尊宿語錄》卷十四《趙州真際禪師語錄》卷下）。"]', '诗', 'shi', '', NULL, '頌 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9bc5e24-9908-40d8-976f-eea033a0a363', '送淩行婆頌', '送淩行婆頌', 'ef589837-967d-4d89-b306-a00de00b29e6', '唐', '["當機直面提，直面當機疾（《五燈會元》錄二「直」字皆作「覿」）。","報爾淩行婆，哭聲何得失。","（見《景德傳燈錄》卷八、《五燈會元》卷三）。"]', '["當機直面提，直面當機疾（《五灯會元》錄二「直」字皆作「覿」）。","報爾淩行婆，哭声何得失。","（见《景德傳灯錄》卷八、《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '送淩行婆頌 從諗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b10e7785-264b-4260-a525-49a00838635a', '答趙州和尚頌', '答趙州和尚頌', 'aa214616-ba38-43f5-8edf-3f31675924cc', '唐', '["哭聲師已曉，已曉復誰知。","當時魔（《五燈會元》作「摩」）竭國，幾喪目前機。","（同前）。"]', '["哭声師已晓，已晓复誰知。","當时魔（《五灯會元》作「摩」）竭国，幾喪目前機。","（同前）。"]', '诗', 'shi', '', NULL, '答趙州和尚頌 淩行婆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f051feb2-a251-4e58-9fc1-a7a5e1284374', '傷淘者', '傷淘者', 'f18010c8-1f8a-46b9-990a-bfed8b08d4d0', '唐', '["披沙辛苦見傷懷，往往分毫望亦乖。","力盡半年深水裏，難全爲一鳳凰釵。","（《太平御覽》卷八一一引《嶺表錄異》，又見四庫本《嶺表錄異》卷上）。"]', '["披沙辛苦见傷懷，往往分毫望亦乖。","力尽半年深水裏，难全爲一鳳凰釵。","（《太平御覽》卷八一一引《嶺表錄異》，又见四庫本《嶺表錄異》卷上）。"]', '诗', 'shi', '', NULL, '傷淘者 鄭玘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee6f859-1e4d-402e-a201-967566b4244d', '大隱賦附歌 一', '大隐賦附歌 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["茫茫大块兮奫淪逶迤，生我至德兮其心孔殷，茫茫兮孰知其施？道之虛，維吾之廬；闤之隘，維吾之賓矣；道之謐，維吾之室；闤之囂，維吾之黨矣！杳乎徐乎，遼乎冥乎，維吾之娛矣！剛龍之蟠長雲兮夭矯蜿蜒，修鱗之喜橫海兮紛潾漩沿，遊神於六合之外兮希夷自然。"]', '["茫茫大块兮奫淪逶迤，生我至德兮其心孔殷，茫茫兮孰知其施？道之虛，維吾之廬；闤之隘，維吾之賓矣；道之謐，維吾之室；闤之囂，維吾之黨矣！杳乎徐乎，遼乎冥乎，維吾之娛矣！剛龙之蟠长云兮夭矯蜿蜒，修鱗之喜橫海兮紛潾漩沿，游神於六合之外兮希夷自然。"]', '诗', 'shi', '', NULL, '大隱賦附歌 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef39b33c-f4a0-48d6-ac19-9bdb515fd2e1', '大隱賦附歌 二', '大隐賦附歌 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["曾瀾起兮風自飄，雲溶溶兮連[泬]（沉）寥，微風息兮波以平，雲霏霏兮開杳冥。","重巖邈兮脩已遠，洄潭渺兮深復淺，羽余觴兮空余罍，玉顏酡兮山已頹，羲皇何以不復回？","捐形棄世兮如我何哉！金踴躍兮求莫耶，爲不祥兮將奈何！（以上二首檀欒子歌）。"]', '["曾瀾起兮风自飄，云溶溶兮連[泬]（沉）寥，微风息兮波以平，云霏霏兮开杳冥。","重巖邈兮脩已远，洄潭渺兮深复淺，羽余觴兮空余罍，玉顏酡兮山已頹，羲皇何以不复回？","捐形棄世兮如我何哉！金踴躍兮求莫耶，爲不祥兮將奈何！（以上二首檀欒子歌）。"]', '诗', 'shi', '', NULL, '大隱賦附歌 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ffbc65-3bc0-4139-966c-82b7e0457f5e', '大隱賦附歌 三', '大隐賦附歌 三', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["大道由由（一作「悠悠」）而熙熙，吾莫知施誰宗，欒子吾其嗣之。","至化蕩蕩而一一，吾莫知專誰師，欒子吾其與焉。","（此首招隱者歌。","均見《文苑英華》卷九九）（按：檀欒子爲皇甫松自號。","）。"]', '["大道由由（一作「悠悠」）而熙熙，吾莫知施誰宗，欒子吾其嗣之。","至化蕩蕩而一一，吾莫知專誰師，欒子吾其與焉。","（此首招隐者歌。","均见《文苑英华》卷九九）（按：檀欒子爲皇甫松自號。","）。"]', '诗', 'shi', '', NULL, '大隱賦附歌 三 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f96c823-2fe3-4d75-83b9-025b24fddd6a', '絕句寄步非煙（題擬）', '絕句寄步非煙（題擬）', '9e50859b-999a-4805-afbd-1bd3af69f773', '唐', '["一覩傾城貌，塵心只自猜。","不隨蕭史去，擬學阿蘭來。"]', '["一覩傾城貌，塵心只自猜。","不隨蕭史去，擬学阿蘭来。"]', '诗', 'shi', '', NULL, '絕句寄步非煙（題擬） 趙象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64493030-ad27-4f45-ae7b-857fc900c202', '賦詩以謝步非煙', '賦诗以謝步非煙', '9e50859b-999a-4805-afbd-1bd3af69f773', '唐', '["珍重佳人贈好音，綵牋芳翰兩情深。","薄於蟬翼難供恨，密似蠅頭未寫心。","疑是落花迷碧洞，只思輕雨灑幽襟。","百回消息千回夢，裁作長謠寄綠琴。"]', '["珍重佳人贈好音，綵牋芳翰兩情深。","薄於蟬翼难供恨，密似蠅头未寫心。","疑是落花迷碧洞，只思轻雨灑幽襟。","百回消息千回梦，裁作长謠寄綠琴。"]', '诗', 'shi', '', NULL, '賦詩以謝步非煙 趙象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec0269db-2d2a-4c5d-8b1c-3699906a7e27', '於前庭獨坐賦詩', '於前庭独坐賦诗', '9e50859b-999a-4805-afbd-1bd3af69f773', '唐', '["綠暗紅藏起暝煙，獨將幽恨小庭前。","沉沉良夜與誰語，星隔銀河月半天。"]', '["綠暗紅藏起暝煙，独將幽恨小庭前。","沉沉良夜與誰語，星隔銀河月半天。"]', '诗', 'shi', '', NULL, '於前庭獨坐賦詩 趙象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3cbcc72-976e-4393-bfe6-f5b55e46777c', '寄步非煙（題擬）', '寄步非煙（題擬）', '9e50859b-999a-4805-afbd-1bd3af69f773', '唐', '["見說傷情爲見春，想封蟬錦綠蛾顰。","叩頭爲報煙卿道，第一風流最損人。"]', '["见说傷情爲见春，想封蟬錦綠蛾顰。","叩头爲報煙卿道，第一风流最損人。"]', '诗', 'shi', '', NULL, '寄步非煙（題擬） 趙象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49a2376-1ae8-49f3-83a3-7c82646c31c9', '託門媼贈步非煙詩（題擬）', '託门媼贈步非煙诗（題擬）', '9e50859b-999a-4805-afbd-1bd3af69f773', '唐', '["十洞三清雖路阻，有心還得傍瑤臺。","瑞香風引思深夜，知是蕊宮仙馭來。","（均見《太平廣記》卷四九一引《三水小牘》）。"]', '["十洞三清雖路阻，有心還得傍瑤台。","瑞香风引思深夜，知是蕊宮仙馭来。","（均见《太平廣記》卷四九一引《三水小牘》）。"]', '诗', 'shi', '', NULL, '託門媼贈步非煙詩（題擬） 趙象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85781370-fa5c-4dd0-9704-6b924fb0d2cc', '新豐吟', '新豐吟', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["古路坦然誰措足？無人解唱還鄉曲。","清風月下守株人，涼兔漸遙春草綠。","天香襲兮絕芳馥，月色凝兮非照燭。","行玄猶是涉崎嶇，體妙因茲背延促，殊不然兮何展縮，縱得然兮混泥玉。","獬豸同欄辨者嗤，薰蕕共處須分郁。","長天月兮遍豁谷，不斷風兮偃松竹。","我今到此得從容，吾師叱我相隨逐。","新豐路兮峻仍皾，新豐洞兮湛然沃。","登者登兮不動搖，遊者遊兮莫勿速。","絕荆榛兮罷釿斸，飲馨香兮味清肅。","負重登臨脫屣迴，看他早是空擔鞠。","來駕肩兮履芳躅，至澂心兮去凝目。","亭堂雖有到人稀，林泉不長尋常木。","道不鐫雕非曲𩔂，郢人進步何瞻矚。","工夫不到不方圓，言語不通非眷屬。","事不然兮詎冥旭，我不然兮何斷續。","慇懃爲報道中人，若戀玄關即拘束。"]', '["古路坦然誰措足？無人解唱還乡曲。","清风月下守株人，涼兔漸遙春草綠。","天香襲兮絕芳馥，月色凝兮非照燭。","行玄猶是涉崎嶇，體妙因茲背延促，殊不然兮何展縮，縱得然兮混泥玉。","獬豸同欄辨者嗤，薰蕕共处須分郁。","长天月兮遍豁谷，不斷风兮偃松竹。","我今到此得從容，吾師叱我相隨逐。","新豐路兮峻仍皾，新豐洞兮湛然沃。","登者登兮不动搖，游者游兮莫勿速。","絕荆榛兮罷釿斸，饮馨香兮味清肅。","負重登臨脫屣迴，看他早是空擔鞠。","来駕肩兮履芳躅，至澂心兮去凝目。","亭堂雖有到人稀，林泉不长尋常木。","道不鐫雕非曲𩔂，郢人進步何瞻矚。","工夫不到不方圓，言語不通非眷屬。","事不然兮詎冥旭，我不然兮何斷續。","慇懃爲報道中人，若戀玄关即拘束。"]', '诗', 'shi', '', NULL, '新豐吟 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78064f7a-16c2-4385-95f9-42cc33175fe9', '寶鏡三昧歌', '寶镜三昧歌', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["如是之法，佛祖密付。","汝今得之，宜善保護。","銀盌盛雪，明月藏鷺。","類之不（《五燈會元》卷十三作「弗」）齊，混則知處。","意不在言，來機亦赴。","動成窠臼，差落顧佇。","背觸俱非，如大火聚。","但形文彩，即屬染污。","夜半正明，天曉不露。","爲物作則，用拔諸苦。","雖非有爲，不是無語。","如臨寶鏡，形形（《五燈會元》作「影」）相覩。","汝不是渠，渠正是汝。","如世嬰兒，五相完具。","不去不來，不起不住。","婆婆和和，有句無句。","終不得物，語未正故。","重離六爻，偏正回互。","疊而爲三，變盡成五。","如荎（《五燈會元》注：「徒結切」）草味，如金剛杵。","正中妙挾，敲唱雙舉。","通宗通途，挾帶挾路。","錯然則吉，不可犯忤。","天真而妙，不屬迷悟。","因緣時節，寂然昭著。","細入無間，大絕方所。","毫忽之差，不應律呂。","今有頓漸，緣立宗趣。","宗趣分矣，即是規矩。","宗通趣極，真常流注。","外寂中謠，係駒伏鼠。","先聖悲之，爲法檀度。","隨其顛倒，以緇爲素。","顛倒想滅，肯心自許。","要合古轍，請觀前古。","佛道垂成，十劫觀樹。","如虎之缺，如馬之馵（《五燈會元》注：「之戌切」）。","以有下劣，寶几珍御。","以有驚異，黧奴白牯。","羿以巧力，射中百步。","箭鋒相值，巧力何預？","木人方歌，石女起舞。","非情識到，寧容思慮？","臣奉於君，子順於父。","不順不（《五燈會元》作「非」）孝，不奉不（《五燈會元》作「非」）輔。","潜行密用，如愚如魯。","但能相續，名主中主。"]', '["如是之法，佛祖密付。","汝今得之，宜善保護。","銀盌盛雪，明月藏鷺。","類之不（《五灯會元》卷十三作「弗」）齊，混則知处。","意不在言，来機亦赴。","动成窠臼，差落顧佇。","背觸俱非，如大火聚。","但形文彩，即屬染污。","夜半正明，天晓不露。","爲物作則，用拔諸苦。","雖非有爲，不是無語。","如臨寶镜，形形（《五灯會元》作「影」）相覩。","汝不是渠，渠正是汝。","如世嬰兒，五相完具。","不去不来，不起不住。","婆婆和和，有句無句。","終不得物，語未正故。","重離六爻，偏正回互。","叠而爲三，变尽成五。","如荎（《五灯會元》注：「徒結切」）草味，如金剛杵。","正中妙挾，敲唱雙舉。","通宗通途，挾带挾路。","錯然則吉，不可犯忤。","天真而妙，不屬迷悟。","因緣时節，寂然昭著。","細入無间，大絕方所。","毫忽之差，不應律呂。","今有頓漸，緣立宗趣。","宗趣分矣，即是規矩。","宗通趣極，真常流注。","外寂中謠，係駒伏鼠。","先聖悲之，爲法檀度。","隨其顛倒，以緇爲素。","顛倒想滅，肯心自許。","要合古轍，請观前古。","佛道垂成，十劫观樹。","如虎之缺，如马之馵（《五灯會元》注：「之戌切」）。","以有下劣，寶几珍御。","以有驚異，黧奴白牯。","羿以巧力，射中百步。","箭鋒相值，巧力何預？","木人方歌，石女起舞。","非情識到，寧容思慮？","臣奉於君，子順於父。","不順不（《五灯會元》作「非」）孝，不奉不（《五灯會元》作「非」）輔。","潜行密用，如愚如魯。","但能相續，名主中主。"]', '诗', 'shi', '', NULL, '寶鏡三昧歌 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb13603-cdaa-4286-aa44-1d9c60b8c8c0', '自誡', '自誡', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["不求名利不求榮，只麽隨緣度此生。","三寸氣消誰是主？百年身後謾虛名。","衣裳破後重重補，糧食無時旋旋營。","一箇幻軀能幾日，爲他間事長無明。"]', '["不求名利不求榮，只麽隨緣度此生。","三寸氣消誰是主？百年身後謾虛名。","衣裳破後重重補，糧食無时旋旋營。","一箇幻軀能幾日，爲他间事长無明。"]', '诗', 'shi', '', NULL, '自誡 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9640417-438a-4c81-a1ea-d2bb6c5342f6', '辭北堂頌二首 一', '辞北堂頌二首 一', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["未了心源度數春，翻嗟浮世謾逡巡。","幾人得道空門裏，獨我淹留在世塵。","謹具尺書辭眷愛，願明大法報慈親。","不須灑淚頻相憶，譬似當初無我身。","。"]', '["未了心源度數春，翻嗟浮世謾逡巡。","幾人得道空门裏，独我淹留在世塵。","謹具尺书辞眷愛，願明大法報慈親。","不須灑泪頻相憶，譬似當初無我身。","。"]', '诗', 'shi', '', NULL, '辭北堂頌二首 一 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a45fdfd-1a76-49ba-890b-509bb4e301f6', '辭北堂頌二首 二', '辞北堂頌二首 二', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["巖下白雲常作伴，峰前碧障以爲隣。","免干世上名與利，永別人間愛與憎。","祖意直教言下曉，玄微須透句中真。","合門親戚要相見，直待當來證果因。"]', '["巖下白云常作伴，峰前碧障以爲隣。","免干世上名與利，永別人间愛與憎。","祖意直教言下晓，玄微須透句中真。","合门親戚要相见，直待當来證果因。"]', '诗', 'shi', '', NULL, '辭北堂頌二首 二 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44bc697c-f262-4ad1-98e2-4bb7ef5a1158', '後寄北堂頌（斯二一六五卷作「辭親偈」）', '後寄北堂頌（斯二一六五卷作「辞親偈」）', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["不求名利不求儒（斯二一六五卷作「不好浮榮不好儒」），願樂空門捨俗徒。","煩惱盡時愁火滅，恩情斷處愛河枯。","六根戒定香風引，一念無生慧力扶。","爲報北堂休悵望（斯二一六五卷作「憶念」），譬言死了譬如無。"]', '["不求名利不求儒（斯二一六五卷作「不好浮榮不好儒」），願乐空门捨俗徒。","煩惱尽时愁火滅，恩情斷处愛河枯。","六根戒定香风引，一念無生慧力扶。","爲報北堂休悵望（斯二一六五卷作「憶念」），譬言死了譬如無。"]', '诗', 'shi', '', NULL, '後寄北堂頌（斯二一六五卷作「辭親偈」） 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6979357e-59b6-484b-a047-3524f43ff985', '網要頌（《五燈會元》卷十三作「偈」）三首 敲唱俱行', '網要頌（《五灯會元》卷十三作「偈」）三首 敲唱俱行', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["金鍼雙鎖備，葉路隱全該。","寶印當空（《五燈會元》作「風」）妙，重重錦縫開。"]', '["金鍼雙鎖備，葉路隐全該。","寶印當空（《五灯會元》作「风」）妙，重重錦縫开。"]', '诗', 'shi', '', NULL, '網要頌（《五燈會元》卷十三作「偈」）三首 敲唱俱行 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf45c7e-ae95-4cd2-9ff9-5b5ee479aa75', '網要頌（《五燈會元》卷十三作「偈」）三首 金鎖玄路', '網要頌（《五灯會元》卷十三作「偈」）三首 金鎖玄路', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["交互明中暗，功齊轉覺難。","力窮忘進退，金鎖網鞔鞔。"]', '["交互明中暗，功齊轉覺难。","力窮忘進退，金鎖網鞔鞔。"]', '诗', 'shi', '', NULL, '網要頌（《五燈會元》卷十三作「偈」）三首 金鎖玄路 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce7f301-433b-41b7-98e3-891d7d114c7b', '網要頌（《五燈會元》卷十三作「偈」）三首 不墮凡聖（《五燈會元》注：「亦名理事不涉」）', '網要頌（《五灯會元》卷十三作「偈」）三首 不墮凡聖（《五灯會元》注：「亦名理事不涉」）', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["事理俱不涉，迴照絕幽微。","背風無巧拙，電火爍難追。"]', '["事理俱不涉，迴照絕幽微。","背风無巧拙，電火爍难追。"]', '诗', 'shi', '', NULL, '網要頌（《五燈會元》卷十三作「偈」）三首 不墮凡聖（《五燈會元》注：「亦名理事不涉」） 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147c0f67-7156-43f3-9ff6-71366ee0c9cf', '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 一', '功勳五位頌（原注：本則既已出上。異本作「上堂次示问話僧頌」） 一', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["聖主由來法帝堯，御人以禮曲龍腰。","有時鬧市頭邊過，到處文明賀聖朝。","（向）。"]', '["聖主由来法帝堯，御人以禮曲龙腰。","有时鬧市头邊過，到处文明賀聖朝。","（向）。"]', '诗', 'shi', '', NULL, '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 一 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffd4900-7f08-44d8-9d65-979650d2a5d8', '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 二', '功勳五位頌（原注：本則既已出上。異本作「上堂次示问話僧頌」） 二', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["淨洗濃粧爲阿誰？子規聲裏勸人歸。","百花落盡蹄無盡，更向亂峰深處啼。","（奉）。"]', '["淨洗濃粧爲阿誰？子規声裏勸人归。","百花落尽蹄無尽，更向亂峰深处啼。","（奉）。"]', '诗', 'shi', '', NULL, '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 二 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f1fc92-89d5-488c-a549-493a182934d6', '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 三', '功勳五位頌（原注：本則既已出上。異本作「上堂次示问話僧頌」） 三', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["枯木花開劫外春，倒騎玉象乘（《五燈會元》作「趁」）麒麟。","而今高隱千峰外，月皎風清好日辰。","（功）。"]', '["枯木花开劫外春，倒騎玉象乘（《五灯會元》作「趁」）麒麟。","而今高隐千峰外，月皎风清好日辰。","（功）。"]', '诗', 'shi', '', NULL, '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 三 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13cd4a20-ced5-4bed-9a3d-384ed40eba72', '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 四', '功勳五位頌（原注：本則既已出上。異本作「上堂次示问話僧頌」） 四', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["衆生諸佛不相侵，山自高兮水自深。","萬別千差明底事，鷓鴣啼處百花新。","（共功）。"]', '["衆生諸佛不相侵，山自高兮水自深。","万別千差明底事，鷓鴣啼处百花新。","（共功）。"]', '诗', 'shi', '', NULL, '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 四 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1868b5-bbff-42b3-b528-ca1072bd55a7', '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 五', '功勳五位頌（原注：本則既已出上。異本作「上堂次示问話僧頌」） 五', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["頭角纔生已不堪，擬心求佛好羞慚。","遲遲空劫無人識，肯向南訽五十三。","（功功）（按：《五燈會元》卷十三所收連作一首。","）。"]', '["头角纔生已不堪，擬心求佛好羞慚。","遲遲空劫無人識，肯向南訽五十三。","（功功）（按：《五灯會元》卷十三所收連作一首。","）。"]', '诗', 'shi', '', NULL, '功勳五位頌（原注：本則既已出上。異本作「上堂次示問話僧頌」） 五 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6939ab0-3b88-4f4d-87fa-a16094a736e1', '真讚', '真讚', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["□□□□□，□□□□□。","徒觀紙與墨，不是山中人。"]', '["□□□□□，□□□□□。","徒观紙與墨，不是山中人。"]', '诗', 'shi', '', NULL, '真讚 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752881cc-8722-4ebb-9da6-cf550031cdb7', '答僧問如何是主中主', '答僧问如何是主中主', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["嗟見今時學道流，千千萬萬認門頭。","恰似入京朝聖主，祇到潼關便[即]（據《五燈會元》卷十三補）休。"]', '["嗟见今时学道流，千千万万認门头。","恰似入京朝聖主，祇到潼关便[即]（據《五灯會元》卷十三補）休。"]', '诗', 'shi', '', NULL, '答僧問如何是主中主 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df47955d-15e5-4c0f-9a4c-4e1df3cd777a', '臨寂示頌（題擬）', '臨寂示頌（題擬）', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["學者恒沙無一悟，過在尋他舌頭路。","欲得忘形泯蹤跡，努力慇懃空裏步。","（以上均見《大正新修大藏經》第四七冊《筠州洞山悟本禪師語錄》）。"]', '["学者恒沙無一悟，過在尋他舌头路。","欲得忘形泯蹤跡，努力慇懃空裏步。","（以上均见《大正新修大藏經》第四七冊《筠州洞山悟本禪師語錄》）。"]', '诗', 'shi', '', NULL, '臨寂示頌（題擬） 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fc731f-d82e-4d93-88ae-cf2ccdbe712b', '過水覩影大悟前旨因有偈（題擬）', '過水覩影大悟前旨因有偈（題擬）', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["切忌從他覓，迢迢與我疎。","我今獨自往，處處得逢渠。","渠今正是我，我今不是渠。","應須與麽（《祖堂集》作「摩」，《五燈會元》、《悅心集》作「恁麽」）會，方始（前引三書作「得」）契如如。","（同前。","以《祖堂集》卷五、卷七、《五燈會元》卷十三、《悅心集》卷一所引相校。","《悅心集》題作《水中覩影口占》。","《五燈會元》卷七作《過水偈》，引疎、渠二韻）。"]', '["切忌從他覓，迢迢與我疎。","我今独自往，处处得逢渠。","渠今正是我，我今不是渠。","應須與麽（《祖堂集》作「摩」，《五灯會元》、《悅心集》作「恁麽」）會，方始（前引三书作「得」）契如如。","（同前。","以《祖堂集》卷五、卷七、《五灯會元》卷十三、《悅心集》卷一所引相校。","《悅心集》題作《水中覩影口占》。","《五灯會元》卷七作《過水偈》，引疎、渠二韻）。"]', '诗', 'shi', '', NULL, '過水覩影大悟前旨因有偈（題擬） 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c766ec-8d50-4a73-9e73-75ef32e08911', '王子頌五首 誕生', '王子頌五首 誕生', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["天然貴胤本非功，德合乾坤育勢隆。","始末一期無雜種，分宮六宅不他宗。","上和下睦陰陽順，共氣連枝器量同。","欲識誕生王子父，鶴騰霄漢出銀籠。"]', '["天然貴胤本非功，德合乾坤育勢隆。","始末一期無杂種，分宮六宅不他宗。","上和下睦陰陽順，共氣連枝器量同。","欲識誕生王子父，鹤腾霄漢出銀籠。"]', '诗', 'shi', '', NULL, '王子頌五首 誕生 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048ab896-8064-423c-a7b5-c5174b9e0401', '王子頌五首 朝生', '王子頌五首 朝生', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["苦學論情世不（《五燈會元》作「莫」）羣，出來凡事已超倫。","詩成五字三冬雪，筆落分毫四海雲。","萬卷積功彰聖代，一心忠孝輔明君。","鹽梅不是生知得，金榜何勞顯至勳。"]', '["苦学論情世不（《五灯會元》作「莫」）羣，出来凡事已超倫。","诗成五字三冬雪，笔落分毫四海云。","万卷積功彰聖代，一心忠孝輔明君。","鹽梅不是生知得，金榜何勞显至勳。"]', '诗', 'shi', '', NULL, '王子頌五首 朝生 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e72cd287-ec3b-4acb-8be9-cd5f305008cc', '王子頌五首 末生', '王子頌五首 末生', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["久棲巖嶽（《五燈會元》作「壑」）用功夫，草榻柴扉守志孤。","十載見聞心自委，一身冬夏衣縑無。","澄凝愁看（《五燈會元》作「含笑」，《禪門諸祖師偈頌》作「愁笑」）三愁思，情苦高名上哲圖。","業就巍（《五燈會元》作「高」，《禪門諸祖師偈頌》作「帝」）科酬極志（《五燈會元》作「志極」），比來臣相不當途。"]', '["久棲巖嶽（《五灯會元》作「壑」）用功夫，草榻柴扉守志孤。","十載见闻心自委，一身冬夏衣縑無。","澄凝愁看（《五灯會元》作「含笑」，《禪门諸祖師偈頌》作「愁笑」）三愁思，情苦高名上哲圖。","業就巍（《五灯會元》作「高」，《禪门諸祖師偈頌》作「帝」）科酬極志（《五灯會元》作「志極」），比来臣相不當途。"]', '诗', 'shi', '', NULL, '王子頌五首 末生 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb09df7f-4085-4c86-b431-298bb08009b3', '王子頌五首 化生', '王子頌五首 化生', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["傍分帝化（《五燈會元》作「位」，《禪門諸祖師偈頌》作「命」）爲傳持，萬里山河布政威。","紅影日輪凝下界，碧袖（《禪門諸祖師偈頌》作「油」）風冷暑炎時。","高低豈廢尊卑奉，五袴蘇途遠近知。","妙印手持煙塞靜，當陽那肯露纖機。"]', '["傍分帝化（《五灯會元》作「位」，《禪门諸祖師偈頌》作「命」）爲傳持，万里山河布政威。","紅影日輪凝下界，碧袖（《禪门諸祖師偈頌》作「油」）风冷暑炎时。","高低豈廢尊卑奉，五袴蘇途远近知。","妙印手持煙塞静，當陽那肯露纖機。"]', '诗', 'shi', '', NULL, '王子頌五首 化生 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ee4e6f-278e-4b44-b682-2468f3b1bc9c', '王子頌五首 內生', '王子頌五首 內生', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["九重深密（《五燈會元》作「密處」）復何宣，挂弊繇（《禪門諸祖師偈頌》作「興」）來顯妙傳。","秖奉一人天地貴，從他諸道自分權。","紫羅帳合君臣隔，黃閤簾垂禁制全。","爲汝方隅官（《禪門諸祖師偈頌》作「愚宮」）屬戀，遂將黃葉止啼錢。","（以上五首均見《大正新修大藏經》第四七冊《筠州洞山悟本禪師語錄·歌頌》校記引別本。","又見《五燈會元》卷五石霜慶諸引「頌洞山五位王子」。","《石倉歷代詩選》卷一一一收末首，誤爲慶諸作。","《禪門諸祖師偈頌》卷上之上云爲「石霜諸禪師出題，洞山悟本大師頌。","」）。"]', '["九重深密（《五灯會元》作「密处」）复何宣，挂弊繇（《禪门諸祖師偈頌》作「兴」）来显妙傳。","秖奉一人天地貴，從他諸道自分權。","紫羅帳合君臣隔，黄閤簾垂禁制全。","爲汝方隅官（《禪门諸祖師偈頌》作「愚宮」）屬戀，遂將黄葉止啼錢。","（以上五首均见《大正新修大藏經》第四七冊《筠州洞山悟本禪師語錄·歌頌》校記引別本。","又见《五灯會元》卷五石霜慶諸引「頌洞山五位王子」。","《石倉歷代诗選》卷一一一收末首，誤爲慶諸作。","《禪门諸祖師偈頌》卷上之上云爲「石霜諸禪師出題，洞山悟本大師頌。","」）。"]', '诗', 'shi', '', NULL, '王子頌五首 內生 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('451c69ee-cde6-45e4-afb2-ee7d09b9678b', '心丹訣 一', '心丹訣 一', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["吾有藥，號心丹，煩惱爐中煉歲年。","知伊不變胎中色，照耀光明遍大千。","開法眼，覩毫端，能變凡聖剎那間。","要知真假成功用，一到底時中鍛煉看。","無形狀，無方圓，言中無物物中言。","有心用即乖真用，無意安禪無不禪。","亦無滅，亦無起，森羅萬像皆驅使。","不論州土但將來，入此爐中無不是。","無一意，是吾意，無一智，是吾智，無一味，無不異。","色不變，轉難辯，更無一物於中現。","莫將一物制伏他，體合真空非鍛煉。","（見《大正新修大藏經》第四八冊吳越釋延壽《宗鏡錄》卷九八）。"]', '["吾有藥，號心丹，煩惱爐中煉歲年。","知伊不变胎中色，照耀光明遍大千。","开法眼，覩毫端，能变凡聖剎那间。","要知真假成功用，一到底时中鍛煉看。","無形狀，無方圓，言中無物物中言。","有心用即乖真用，無意安禪無不禪。","亦無滅，亦無起，森羅万像皆驱使。","不論州土但將来，入此爐中無不是。","無一意，是吾意，無一智，是吾智，無一味，無不異。","色不变，轉难辯，更無一物於中現。","莫將一物制伏他，體合真空非鍛煉。","（见《大正新修大藏經》第四八冊吳越釋延壽《宗镜錄》卷九八）。"]', '诗', 'shi', '', NULL, '心丹訣 一 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6febcb5-d693-474f-9e9b-f9bf4240e332', '心丹訣 二', '心丹訣 二', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["茫茫天下虛尋覓，未肯迴頭自相識。","信師行到無爲鄉，始覺從來枉施力。","（同前書卷十六引）。"]', '["茫茫天下虛尋覓，未肯迴头自相識。","信師行到無爲乡，始覺從来枉施力。","（同前书卷十六引）。"]', '诗', 'shi', '', NULL, '心丹訣 二 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d5e51c-8ee2-49d2-bb8b-8e0180b6ac44', '悟道偈', '悟道偈', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["向來物物上求通，祇爲從前不識宗。","如今見了渾無事，方知萬法本來空。","（同前書卷六引）。"]', '["向来物物上求通，祇爲從前不識宗。","如今见了渾無事，方知万法本来空。","（同前书卷六引）。"]', '诗', 'shi', '', NULL, '悟道偈 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37fb6bc-274d-44dc-92ba-2ffe38af21d8', '偈', '偈', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["世間塵事亂如毛，不向空門何處消。","若待境緣除蕩盡，古人那得喻芭蕉。","（同前書卷四十引）。"]', '["世间塵事亂如毛，不向空门何处消。","若待境緣除蕩尽，古人那得喻芭蕉。","（同前书卷四十引）。"]', '诗', 'shi', '', NULL, '偈 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfa2c5a-4271-4e19-9103-e5eb426a0c67', '缺題', '缺題', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["吾家本住在何方？鳥道無人到處鄉。","君若出家爲釋子，能行此路萬相當。","（同前書卷十二引）。"]', '["吾家本住在何方？鸟道無人到处乡。","君若出家爲釋子，能行此路万相當。","（同前书卷十二引）。"]', '诗', 'shi', '', NULL, '缺題 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5be86a-4754-4db1-a5e9-a14cf07b21a4', '五位君臣頌', '五位君臣頌', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '五位君臣頌 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f2f61c-b065-43b8-9c4f-9d9d4178befa', '五位君臣頌 一', '五位君臣頌 一', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["正中偏，三更初夜月明前。","莫怪相逢不相識，隱隱猶懷舊日嫌（一作「妍」）。"]', '["正中偏，三更初夜月明前。","莫怪相逢不相識，隐隐猶懷旧日嫌（一作「妍」）。"]', '诗', 'shi', '', NULL, '五位君臣頌 一 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e579fefa-53d2-45b8-90d7-2f19d7a03e05', '五位君臣頌 二', '五位君臣頌 二', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["偏中正，失曉老婆逢古鏡。","分明（一作「月」）覿面別無真，休更迷頭猶（一作「還」）認影。"]', '["偏中正，失晓老婆逢古镜。","分明（一作「月」）覿面別無真，休更迷头猶（一作「還」）認影。"]', '诗', 'shi', '', NULL, '五位君臣頌 二 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf78a94-58b3-4821-9c46-908a09c6f60b', '五位君臣頌 三', '五位君臣頌 三', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["正中來，無中有路隔塵埃。","但能不觸當今（一作「時」）諱，也勝前朝斷舌才。"]', '["正中来，無中有路隔塵埃。","但能不觸當今（一作「时」）諱，也勝前朝斷舌才。"]', '诗', 'shi', '', NULL, '五位君臣頌 三 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afab3e3d-5e10-4dee-97d6-1384a99a14e5', '五位君臣頌 四', '五位君臣頌 四', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["兼（一作「偏」）中至，兩刃交鋒不須避。","好手猶如火裏蓮，宛然自有沖天志。","（一作「氣」）。"]', '["兼（一作「偏」）中至，兩刃交鋒不須避。","好手猶如火裏蓮，宛然自有沖天志。","（一作「氣」）。"]', '诗', 'shi', '', NULL, '五位君臣頌 四 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23623ce2-c7d0-48ee-9587-541ada3eda02', '五位君臣頌 五', '五位君臣頌 五', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["兼中到，不落有無誰敢和。","人人盡欲出常流，折合還歸炭裏坐。","（見《五燈會元》卷十三，注「一作」者爲《撫州曹山元證禪師語錄》之異文）。"]', '["兼中到，不落有無誰敢和。","人人尽欲出常流，折合還归炭裏坐。","（见《五灯會元》卷十三，注「一作」者爲《撫州曹山元證禪師語錄》之異文）。"]', '诗', 'shi', '', NULL, '五位君臣頌 五 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e181ad30-8408-4d6b-ae64-ccdffb5694cf', '呈雲巖偈', '呈云巖偈', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["也大奇，也大奇（《祖堂集》作「可笑奇，可笑奇」），無情解說（《五燈會元》作「說法」）不思議。","若將耳聽聲不現（《五燈會元》作「終難會」），眼處聞聲始可知（《祖堂集》、《五燈會元》作「方得知」。","）（見《景德傳燈錄》卷十五、《五燈會元》卷十三）。"]', '["也大奇，也大奇（《祖堂集》作「可笑奇，可笑奇」），無情解说（《五灯會元》作「说法」）不思議。","若將耳听声不現（《五灯會元》作「終难會」），眼处闻声始可知（《祖堂集》、《五灯會元》作「方得知」。","）（见《景德傳灯錄》卷十五、《五灯會元》卷十三）。"]', '诗', 'shi', '', NULL, '呈雲巖偈 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f30ee3-b2c3-4d97-a4c8-c112c9b86333', '答仰山頌', '答仰山頌', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["詩詠人間事，空門何不刪？","探珠宜靜浪，動水取應難。","名利心須剪，非朋不用攀。","捨邪歸正道，何慮不閑閑。","（《天聖廣燈錄》卷十二）。"]', '["诗詠人间事，空门何不刪？","探珠宜静浪，动水取應难。","名利心須剪，非朋不用攀。","捨邪归正道，何慮不闲闲。","（《天聖廣灯錄》卷十二）。"]', '诗', 'shi', '', NULL, '答仰山頌 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4af2d41-a1e1-4fbd-a850-621b66dcaaf8', '頌', '頌', 'c1afe219-74b7-4b12-afa7-00d98a9a122c', '唐', '["道無心合人，人無心合道。","欲知此（《五燈會元》作「箇」）中意，一老一不老。","（《祖堂集》卷二十、《五燈會元》卷十三）。"]', '["道無心合人，人無心合道。","欲知此（《五灯會元》作「箇」）中意，一老一不老。","（《祖堂集》卷二十、《五灯會元》卷十三）。"]', '诗', 'shi', '', NULL, '頌 良价 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380cbe07-75ad-4777-91b7-3f36088108c9', '辭雪峰和尚（題擬）', '辞雪峰和尚（題擬）', 'a7599c1b-acd6-4a79-9233-59169b9ff5bf', '唐', '["暫辭雪嶺伴雲行，谷口無關路坦平。","禪師莫愁懷別恨，猶如秋月月常明。","（《祖堂集》卷七）。"]', '["暫辞雪嶺伴云行，谷口無关路坦平。","禪師莫愁懷別恨，猶如秋月月常明。","（《祖堂集》卷七）。"]', '诗', 'shi', '', NULL, '辭雪峰和尚（題擬） 道允 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e307bb7d-ad1b-4341-bbcc-01680c1874e8', '示洞山偈', '示洞山偈', 'f457039b-01e5-4df4-8a50-060341146cb9', '唐', '["青山白雲父，白雲青山兒。","白雲終日依（一作「倚」），青山都（一作「總」）不知。","欲知此中意，寸步不相離。","（見《祖堂集》卷二十）。"]', '["青山白云父，白云青山兒。","白云終日依（一作「倚」），青山都（一作「總」）不知。","欲知此中意，寸步不相離。","（见《祖堂集》卷二十）。"]', '诗', 'shi', '', NULL, '示洞山偈 隱山和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376d8f1a-3502-4c52-b640-958c6bdab718', '留壁（題從《沅湘耆舊集》）', '留壁（題從《沅湘耆旧集》）', 'f457039b-01e5-4df4-8a50-060341146cb9', '唐', '["三間茅屋從來住，一道神光萬境閑。","莫把事非來辨我，浮生穿鑿不相關。","（見《五燈會元》卷三、《石倉歷代詩選》卷一一一、《沅湘耆舊集》卷十）（按：《沅湘耆舊集》另錄一詩，爲大梅法常偈誤入，見本書卷二十七。","《正法眼藏》卷三作「洞山頌」。","）。"]', '["三间茅屋從来住，一道神光万境闲。","莫把事非来辨我，浮生穿鑿不相关。","（见《五灯會元》卷三、《石倉歷代诗選》卷一一一、《沅湘耆旧集》卷十）（按：《沅湘耆旧集》另錄一诗，爲大梅法常偈誤入，见本书卷二十七。","《正法眼藏》卷三作「洞山頌」。","）。"]', '诗', 'shi', '', NULL, '留壁（題從《沅湘耆舊集》） 隱山和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0df9fde-dd8d-4cf0-b11e-563527781f48', '栽松頌', '栽松頌', '7220285e-9e53-4e9d-9e07-74c2fc40c8bf', '唐', '["短短一尺餘（《景德傳燈錄》、《五燈會元》、《古今禪藻集》均作「長長三尺餘」），纖纖（前引三書均作「鬱鬱」）覆綠（《景德傳燈錄》作「荒」，《五燈會元》、《古今禪藻集》作「青」）草。","不知何世（前引三書均作「代」）人，得見此松老。","（見《祖堂集》卷八，以《景德傳燈錄》卷十七、《五燈會元》卷十三、《古今禪藻集》卷七對校）。"]', '["短短一尺餘（《景德傳灯錄》、《五灯會元》、《古今禪藻集》均作「长长三尺餘」），纖纖（前引三书均作「鬱鬱」）覆綠（《景德傳灯錄》作「荒」，《五灯會元》、《古今禪藻集》作「青」）草。","不知何世（前引三书均作「代」）人，得见此松老。","（见《祖堂集》卷八，以《景德傳灯錄》卷十七、《五灯會元》卷十三、《古今禪藻集》卷七对校）。"]', '诗', 'shi', '', NULL, '栽松頌 師虔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beed8fc1-4b4b-48de-bfc0-2ff8bb410c87', '偈 一', '偈 一', '93221dda-a24d-4194-930d-499e59dd136d', '唐', '["滄溟幾度變桑田，唯有虛（《三山志》作「靈」）空獨湛然。","已到岸人休戀筏，未曾度者任（一作「要」）須（《三山志》作「便求」）船。"]', '["滄溟幾度变桑田，唯有虛（《三山志》作「靈」）空独湛然。","已到岸人休戀筏，未曾度者任（一作「要」）須（《三山志》作「便求」）船。"]', '诗', 'shi', '', NULL, '偈 一 正原 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715e6df8-05bc-4564-bc2f-dc8351a8171d', '偈 二', '偈 二', '93221dda-a24d-4194-930d-499e59dd136d', '唐', '["尋師認得本心源，兩岸俱玄一不全。","是佛何（一作「不」）須更求（一作「覓」）佛，只因從（一作「如」）此便忘言（一作「緣」）。","（見《祖堂集》卷十七、《景德傳燈錄》卷十、《五燈會元》卷四。","注「一作」者爲後二書之異文。","《淳熙三山志》卷三七以前一首爲釋智真作，今不取。","）。"]', '["尋師認得本心源，兩岸俱玄一不全。","是佛何（一作「不」）須更求（一作「覓」）佛，只因從（一作「如」）此便忘言（一作「緣」）。","（见《祖堂集》卷十七、《景德傳灯錄》卷十、《五灯會元》卷四。","注「一作」者爲後二书之異文。","《淳熙三山志》卷三七以前一首爲釋智真作，今不取。","）。"]', '诗', 'shi', '', NULL, '偈 二 正原 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1294fb-f26a-4291-94a5-810ed127d8cf', '偈 三', '偈 三', '93221dda-a24d-4194-930d-499e59dd136d', '唐', '["劉民周續豈顛癡，棄世猶求遠大師。","今日幸逢玄旨在，須將心地種禪枝。","（見《淳熙三山志》卷三七）（按：《祖堂集》錄正原偈四首，後二首應爲智真作，參本卷智真條。","）。"]', '["劉民周續豈顛癡，棄世猶求远大師。","今日幸逢玄旨在，須將心地種禪枝。","（见《淳熙三山志》卷三七）（按：《祖堂集》錄正原偈四首，後二首應爲智真作，參本卷智真條。","）。"]', '诗', 'shi', '', NULL, '偈 三 正原 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51dc8903-aa64-4c67-a76c-b372723076f4', '判人求免稅（題擬）', '判人求免稅（題擬）', 'c1adf915-9df6-48e1-bea7-1fee8fc4c499', '唐', '["松垣筆力破滄溟，欲援任濤免稅□。","一段風流好公案，錦江重寫入圖經。","（《堯山堂外紀》卷二六）。"]', '["松垣笔力破滄溟，欲援任濤免稅□。","一段风流好公案，錦江重寫入圖經。","（《堯山堂外紀》卷二六）。"]', '诗', 'shi', '', NULL, '判人求免稅（題擬） 李隲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8ceb81-3ae1-4c94-8cd8-c37efb4f1384', '答王侍郎諷問黑豆未生芽時頌（題擬）', '答王侍郎諷问黑豆未生芽时頌（題擬）', '821404a1-42c5-4966-93da-b57a18da00c3', '唐', '["菩提慧日朝朝照，般若涼風夜夜吹。","此處不生聚雜樹，滿山明月是禪枝。"]', '["菩提慧日朝朝照，般若涼风夜夜吹。","此处不生聚杂樹，满山明月是禪枝。"]', '诗', 'shi', '', NULL, '答王侍郎諷問黑豆未生芽時頌（題擬） 義忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21c57d5-75a2-4874-b41c-64539380cecf', '偈四首 一', '偈四首 一', '821404a1-42c5-4966-93da-b57a18da00c3', '唐', '["即此見聞非見聞，無餘聲色可呈君。","箇中若了全（《宗鏡錄》卷九八作「渾」）無事，體用無（《五燈會元》卷五作「何」）妨分不分。","。"]', '["即此见闻非见闻，無餘声色可呈君。","箇中若了全（《宗镜錄》卷九八作「渾」）無事，體用無（《五灯會元》卷五作「何」）妨分不分。","。"]', '诗', 'shi', '', NULL, '偈四首 一 義忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13a80e5-286f-44b7-a34a-bd76bacada0e', '偈四首 二', '偈四首 二', '821404a1-42c5-4966-93da-b57a18da00c3', '唐', '["見聞覺知本非塵，識海波中自昧身。","狀似碧潭波沫覆，靈王翻作客中賓。"]', '["见闻覺知本非塵，識海波中自昧身。","狀似碧潭波沫覆，靈王翻作客中賓。"]', '诗', 'shi', '', NULL, '偈四首 二 義忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44758f5-aa07-44ab-a657-e712b533eb57', '偈四首 三', '偈四首 三', '821404a1-42c5-4966-93da-b57a18da00c3', '唐', '["見聞知覺本非因，當體虛玄覺妄真。","見相不生癡愛業，洞然全是釋迦身。","（見《祖堂集》卷五）。"]', '["见闻知覺本非因，當體虛玄覺妄真。","见相不生癡愛業，洞然全是釋迦身。","（见《祖堂集》卷五）。"]', '诗', 'shi', '', NULL, '偈四首 三 義忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c397f35-b049-4278-a6b0-72f6fe107e24', '偈四首 四', '偈四首 四', '821404a1-42c5-4966-93da-b57a18da00c3', '唐', '["解擘當胸箭，因何祇半人？","爲從途路曉，所以不全身。","（《五燈會元》卷八）。"]', '["解擘當胸箭，因何祇半人？","爲從途路晓，所以不全身。","（《五灯會元》卷八）。"]', '诗', 'shi', '', NULL, '偈四首 四 義忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42db61b4-ea7e-46fa-a435-0ea5976b459e', '謔楊萊兒', '謔楊萊兒', 'c5f8cc70-7f3b-46fc-bc12-5c34e8783562', '唐', '["盡道萊兒口可憑，一冬誇壻好聲名。","適來安遠門前見，光遠何曾解一鳴。","（見《北里志》）。"]', '["尽道萊兒口可憑，一冬誇壻好声名。","適来安远门前见，光远何曾解一鳴。","（见《北里志》）。"]', '诗', 'shi', '', NULL, '謔楊萊兒 京師小子弟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a636f43-8637-46db-9688-8c002f9993e2', '和江西李助副使早登開元寺閣', '和江西李助副使早登开元寺閣', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["空（按：《全唐詩》卷七四五此詩，第十五句缺一字。","檢胡震亨《唐首戊籤》八〖《統籤》卷五九七〗，收此詩於雍陶名下，題作《登武昌江山寺》，第十五句不缺，作「書劍忽若空」。","全詩較長，不重錄。","胡氏未云因何收歸雍陶名下。","《唐音戊籤餘》二八陳陶名下重收。","）。"]', '["空（按：《全唐诗》卷七四五此诗，第十五句缺一字。","檢胡震亨《唐首戊籤》八〖《統籤》卷五九七〗，收此诗於雍陶名下，題作《登武昌江山寺》，第十五句不缺，作「书劍忽若空」。","全诗較长，不重錄。","胡氏未云因何收归雍陶名下。","《唐音戊籤餘》二八陳陶名下重收。","）。"]', '诗', 'shi', '', NULL, '和江西李助副使早登開元寺閣 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9533c8-563b-4c0b-9b42-89a66a6c9cf0', '', '', '8b9e3778-c990-4c99-b854-23517bcd49de', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 嚴都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c6b516-f7a2-47d9-bfe1-5513d96a0fd4', '[擬]送賀秘監歸會稽詩', '[擬]送賀秘監归會稽诗', '8b9e3778-c990-4c99-b854-23517bcd49de', '唐', '["廣成何必掛朝衣，已奉玄珠佐萬機。","還躡舊衣鳧舃去，不將新賜鶴書歸。","（先生因辭寵祿，竟追成命）暫憑風馭遊清禁，終泛仙槎出紫微。","今日漢庭因少別，人間無限白雲飛。","（將離洛都，歷別公卿十數事，其處皆有白雲起。","見《會稽掇英總集》卷二）。"]', '["廣成何必掛朝衣，已奉玄珠佐万機。","還躡旧衣鳧舃去，不將新賜鹤书归。","（先生因辞寵祿，竟追成命）暫憑风馭游清禁，終泛仙槎出紫微。","今日漢庭因少別，人间無限白云飞。","（將離洛都，歷別公卿十數事，其处皆有白云起。","见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '[擬]送賀秘監歸會稽詩 嚴都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0077c22c-eef9-4aec-bf9a-fd47af0db207', '寶賢堂', '寶賢堂', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["遊訪曾經駐馬看，竇犨遺像在林巒。","泉分石洞千條碧，人在冰壺六月寒。","時雨欲來騰霧靄，微風初動漾波瀾。","箇中若置羊裘叟，絕勝當年七里灘。","（《古今圖書集成·職方典》卷三○五《太原府部》）。"]', '["游訪曾經駐马看，竇犨遺像在林巒。","泉分石洞千條碧，人在冰壺六月寒。","时雨欲来腾霧靄，微风初动漾波瀾。","箇中若置羊裘叟，絕勝當年七里灘。","（《古今圖书集成·職方典》卷三○五《太原府部》）。"]', '诗', 'shi', '', NULL, '寶賢堂 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087e27d0-a834-4a0c-ac29-537917bb51a7', '蘇州寒食日送人歸覲', '蘇州寒食日送人归覲', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["江聲寒食下，花木慘離魂。","幾宿投山寺，孤帆過海門。","篷聲潑火雨，柳色禁煙村。","定看堂高後，斑衣滅淚痕。","（見《擇是居叢書》影宋紹定二年刊本宋范成大《吳郡志》卷四九）（按：《全唐詩》卷五八九錄此詩，有缺字，今重錄。","另同卷《即席送許□之曹南省兄》，據《吳郡志》同卷，所缺一字爲「製」字，詩不重錄。","）。"]', '["江声寒食下，花木慘離魂。","幾宿投山寺，孤帆過海门。","篷声潑火雨，柳色禁煙村。","定看堂高後，斑衣滅泪痕。","（见《擇是居叢书》影宋紹定二年刊本宋范成大《吳郡志》卷四九）（按：《全唐诗》卷五八九錄此诗，有缺字，今重錄。","另同卷《即席送許□之曹南省兄》，據《吳郡志》同卷，所缺一字爲「製」字，诗不重錄。","）。"]', '诗', 'shi', '', NULL, '蘇州寒食日送人歸覲 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a11e20-b9bc-4a0b-a693-3d3c58610a36', '句', '句', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["恩深轉無語，懷抱自分明。","（見《吟窗雜錄》卷十三王夢簡《進士王氏詩要格律》）（按：原署「李穎」，收二聯，另一聯「天下已歸漢，山中猶避秦」，爲李頻《四皓廟》句，知此二句亦爲李頻詩。","）。"]', '["恩深轉無語，懷抱自分明。","（见《吟窗杂錄》卷十三王梦簡《進士王氏诗要格律》）（按：原署「李穎」，收二聯，另一聯「天下已归漢，山中猶避秦」，爲李頻《四皓廟》句，知此二句亦爲李頻诗。","）。"]', '诗', 'shi', '', NULL, '句 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f50b8c-7999-4b47-8e29-816a5a66461d', '披雲霧見青天詩', '披云霧见青天诗', '8d35ab1c-59ad-4375-98d0-3d5dd64ff3ba', '唐', '["顏回似（《吟窗雜錄》作「貌如」）青天。","（《太平廣記》卷二六一、《吟窗雜錄》卷三九）。"]', '["顏回似（《吟窗杂錄》作「貌如」）青天。","（《太平廣記》卷二六一、《吟窗杂錄》卷三九）。"]', '诗', 'shi', '', NULL, '披雲霧見青天詩 李罕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91745ee3-6f4b-4f1a-a48e-7ba85630cdf4', '王氏殤女墓銘', '王氏殤女墓銘', '9eb76d9c-87fd-4d3e-877e-9153e3771456', '唐', '["王氏殤女其名容，名由儀範三德充，誦詩閱史慕古風，卑盈樂善正養蒙。","是宜百祥期無窮，奈何美疓{下爲尔}剿其躬。","芳年奄謝午咸通，季夏二十三遘凶，翌月十八即幽宮，壽逾及笄三而終。","晉陽之胄冠諸宗，厥考長仁命不融，外族清河武城東，中外輝焯爲世雄。","今已矣夫石窌封，仲父刻銘藏戶中，以紓臨穴㛐悲恫。","古往今來萬化同，高高誰爲問圓穹？姑安是兮龜筮從，竢吉良兮從乃公。","（見饒宗頤編《唐宋墓誌·遠東學院藏拓片圖錄》）（按：此方墓誌無序，銘文通篇爲七言韻文，與詩無異。","在唐誌中頗罕見，故錄出之。","作者爲死者王容之仲父，「午咸通」即咸通三年壬午歲。","）。"]', '["王氏殤女其名容，名由儀範三德充，誦诗閱史慕古风，卑盈乐善正養蒙。","是宜百祥期無窮，奈何美疓{下爲尔}剿其躬。","芳年奄謝午咸通，季夏二十三遘凶，翌月十八即幽宮，壽逾及笄三而終。","晉陽之胄冠諸宗，厥考长仁命不融，外族清河武城东，中外輝焯爲世雄。","今已矣夫石窌封，仲父刻銘藏戶中，以紓臨穴㛐悲恫。","古往今来万化同，高高誰爲问圓穹？姑安是兮龟筮從，竢吉良兮從乃公。","（见饒宗頤編《唐宋墓誌·远东学院藏拓片圖錄》）（按：此方墓誌無序，銘文通篇爲七言韻文，與诗無異。","在唐誌中頗罕见，故錄出之。","作者爲死者王容之仲父，「午咸通」即咸通三年壬午歲。","）。"]', '诗', 'shi', '', NULL, '王氏殤女墓銘 王□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841d44fa-1ce7-4d5b-af15-c61034fbef3c', '牡丹', '牡丹', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["絕代祇西子，衆芳唯牡丹。","月中虛有桂，天上謾誇蘭。","夜濯金波滿，朝傾玉露殘。","性應輕菡萏，根本是琅玕。","奪日霞千片，[淩]（陵）風綺一端。","稍宜經（一作「霑」）宿雨，偏覺耐春寒。","見說開元歲，初令植御欄，貴妃嬌欲比，侍女妬羞看。","巧類鴛機織，光攢射月團。","漸移公子第，還種杏花壇。","豪士傾囊買，貧儒假乘觀。","葉藏梧際鳳，枝動鏡中鸞。","似笑賓初至，如愁酒欲闌。","詩人忘芍藥，釋子媿梅檀。","酷烈宜名壽，姿容想姓潘。","素光翻露羽，丹燄赩鷄冠。","鷰拂驚還語，蜂貪困未安。","儻令紅臉笑，兼解翠眉攢。","少長呈連萼，嬌矜寄合歡。","息肩移九軌，無脛到千官。","日耀香房折，風披蘂粉乾。","好酬青玉案，稱貯碧冰盤。","璧要連城與，[珠]（殊）堪十斛判。","更思初甲拆，那得異泥蟠。","騷詠應遺恨，農經祇粗刊。","魯般雕不得，延壽筆將殫。","醉客同攀折，佳人惜犯干。","始知來苑圃，全勝在林巒。","泥潭當澆灑，庭除又綽寬。","若將桃李並，方覺效嚬難。","（見《文苑英華》卷三二一）。"]', '["絕代祇西子，衆芳唯牡丹。","月中虛有桂，天上謾誇蘭。","夜濯金波满，朝傾玉露殘。","性應轻菡萏，根本是琅玕。","奪日霞千片，[淩]（陵）风綺一端。","稍宜經（一作「霑」）宿雨，偏覺耐春寒。","见说开元歲，初令植御欄，貴妃嬌欲比，侍女妬羞看。","巧類鴛機织，光攢射月團。","漸移公子第，還種杏花壇。","豪士傾囊買，貧儒假乘观。","葉藏梧際鳳，枝动镜中鸾。","似笑賓初至，如愁酒欲闌。","诗人忘芍藥，釋子媿梅檀。","酷烈宜名壽，姿容想姓潘。","素光翻露羽，丹燄赩鷄冠。","鷰拂驚還語，蜂貪困未安。","儻令紅臉笑，兼解翠眉攢。","少长呈連萼，嬌矜寄合歡。","息肩移九軌，無脛到千官。","日耀香房折，风披蘂粉乾。","好酬青玉案，稱貯碧冰盤。","璧要連城與，[珠]（殊）堪十斛判。","更思初甲拆，那得異泥蟠。","騷詠應遺恨，農經祇粗刊。","魯般雕不得，延壽笔將殫。","醉客同攀折，佳人惜犯干。","始知来苑圃，全勝在林巒。","泥潭當澆灑，庭除又綽寬。","若將桃李並，方覺效嚬难。","（见《文苑英华》卷三二一）。"]', '诗', 'shi', '', NULL, '牡丹 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f49a0c-c550-4358-8afb-2b63007450d3', '送李羣玉', '送李羣玉', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["君夢涔陽月，中秋憶[棹歌]（歸棹）。","鉛黃辭秘府，詩酒寄滄波。","妙吹應諧鳳，工書定得鵝。","[□□□□□，□□□□□。","]（詳附按）（按：此詩詩題及前四句，出宋王象之《輿地紀勝》卷七十。","「歸棹」二字不韻，從《全唐詩》卷五五一引《岳州府志》改。","「妙吹」二句，出宋錢易《南部新書》卷乙。","詳詩意及押韻，與前四句應爲一首。","原詩應爲五律，末二句缺。","「君夢」、「妙吹」二聯，《全唐詩》已收入。","）。"]', '["君梦涔陽月，中秋憶[棹歌]（归棹）。","鉛黄辞秘府，诗酒寄滄波。","妙吹應諧鳳，工书定得鵝。","[□□□□□，□□□□□。","]（詳附按）（按：此诗诗題及前四句，出宋王象之《輿地紀勝》卷七十。","「归棹」二字不韻，從《全唐诗》卷五五一引《岳州府志》改。","「妙吹」二句，出宋錢易《南部新书》卷乙。","詳诗意及押韻，與前四句應爲一首。","原诗應爲五律，末二句缺。","「君梦」、「妙吹」二聯，《全唐诗》已收入。","）。"]', '诗', 'shi', '', NULL, '送李羣玉 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dfb79cd-ff7c-4063-988f-682d7e966e93', '病馬', '病马', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["塵土臥多毛已（一作「色」）暗，風霜受盡眼猶（一作「光」）明。","（見陸游《渭南文集》卷二八《跋唐盧肇集》引）（〖1〗陸游跋云：「子發嘗謫春州，而集中誤作『青州』，蓋字之誤也。","《題清遠峽觀音院詩》，作『青州遠峽』，則又因州名而妄竄定也。","前輩謂印本之害，一誤之後，遂無別本可證，真知言哉！《病馬詩》云〖略〗。","足爲當時佳句。","此本乃以『已』爲『色』，『猶』爲『光』，壞盡一篇語意，未必非妄校之罪也。","可勝歎哉！慶元庚申二月三日，放翁燈下書。","」按：《吟窗雜錄》引《詩中旨格》收此二句爲秦韜玉詩，見本書卷三十三。","）。"]', '["塵土臥多毛已（一作「色」）暗，风霜受尽眼猶（一作「光」）明。","（见陸游《渭南文集》卷二八《跋唐盧肇集》引）（〖1〗陸游跋云：「子發嘗謫春州，而集中誤作『青州』，蓋字之誤也。","《題清远峽观音院诗》，作『青州远峽』，則又因州名而妄竄定也。","前輩謂印本之害，一誤之後，遂無別本可證，真知言哉！《病马诗》云〖略〗。","足爲當时佳句。","此本乃以『已』爲『色』，『猶』爲『光』，壞尽一篇語意，未必非妄校之罪也。","可勝歎哉！慶元庚申二月三日，放翁灯下书。","」按：《吟窗杂錄》引《诗中旨格》收此二句爲秦韜玉诗，见本书卷三十三。","）。"]', '诗', 'shi', '', NULL, '病馬 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df02165-1c71-4733-a441-9fb0733b3818', '咤姚巖傑詩', '咤姚巖傑诗', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["明月照巴山。","（見《唐摭言》卷十）。"]', '["明月照巴山。","（见《唐摭言》卷十）。"]', '诗', 'shi', '', NULL, '咤姚巖傑詩 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8014aa56-1358-4999-b50d-4cdbfaa72045', '題雲峯寺', '題云峯寺', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["朔風振林壑，樓殿虛無間。","半夜雲開月，流水滿空山。","（民國重刊明弘治《衡山縣志》卷六。","此詩承陶敏先生錄示）。"]', '["朔风振林壑，楼殿虛無间。","半夜云开月，流水满空山。","（民国重刊明弘治《衡山縣志》卷六。","此诗承陶敏先生錄示）。"]', '诗', 'shi', '', NULL, '題雲峯寺 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfde49f-df87-4aaf-851d-6d440fa5752b', '', '', 'cffb5737-f209-4990-9d0c-7d52555d24c9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 劉瞻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2964775-2073-477e-b3f1-1ae196ef974e', '竹枝詞（送李庚）', '竹枝词（送李庚）', 'cffb5737-f209-4990-9d0c-7d52555d24c9', '唐', '["躡履過溝（竹枝）恨渠深（女兒）。","（見《中朝故事》）（按：《中朝故事》：瞻「至湖南，李庾方典是郡，出迎於江次竹牌亭。","置酒，瞻唱《竹枝詞》送李庾〖略〗。","庾懾怒，乃上酒於瞻。","瞻命庾酬唱。","庾云：『不曉詞間音律』。","瞻投杯曰：『君應祇解爲制詞也。","』是夕，庾飲鴆而卒。","」）。"]', '["躡履過溝（竹枝）恨渠深（女兒）。","（见《中朝故事》）（按：《中朝故事》：瞻「至湖南，李庾方典是郡，出迎於江次竹牌亭。","置酒，瞻唱《竹枝词》送李庾〖略〗。","庾懾怒，乃上酒於瞻。","瞻命庾酬唱。","庾云：『不晓词间音律』。","瞻投杯曰：『君應祇解爲制词也。","』是夕，庾饮鴆而卒。","」）。"]', '诗', 'shi', '', NULL, '竹枝詞（送李庚） 劉瞻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d9864a-19e1-4368-9d74-9a91aadac08b', '將歸寂有偈', '將归寂有偈', 'cf42c841-87b5-4986-8c10-7cfc4974e8b8', '唐', '["三十年來住木陳，時中無一假功成。","有人問我西來意，展似眉毛作麽生。","（見《大正藏》本《景德傳燈錄》卷十一〖影宋本無〗、《五燈會元》卷四）。"]', '["三十年来住木陳，时中無一假功成。","有人问我西来意，展似眉毛作麽生。","（见《大正藏》本《景德傳灯錄》卷十一〖影宋本無〗、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '將歸寂有偈 從朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98416a42-e74b-48a5-818f-3bf383caeaba', '送張曄赴舉', '送張曄赴舉', '35270da7-109b-4f80-a75d-230da5e856b3', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '送張曄赴舉 盧庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9183ac-7e63-450b-8954-304c627df1ca', '送張曄赴舉 一', '送張曄赴舉 一', '35270da7-109b-4f80-a75d-230da5e856b3', '唐', '["一直照千曲，一雅肅羣俗。","如君一軸詩，把出姧妖服。"]', '["一直照千曲，一雅肅羣俗。","如君一軸诗，把出姧妖服。"]', '诗', 'shi', '', NULL, '送張曄赴舉 一 盧庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3900d6b1-9bfd-4123-815e-09a0177d7045', '送張曄赴舉 二', '送張曄赴舉 二', '35270da7-109b-4f80-a75d-230da5e856b3', '唐', '["乃知詩日月，曈曈出平地。","（見《千唐誌齋藏誌》咸通十一年李夷遇撰《唐故鄉貢進士南陽郡張公〖曄〗墓誌銘》引）。"]', '["乃知诗日月，曈曈出平地。","（见《千唐誌斋藏誌》咸通十一年李夷遇撰《唐故乡貢進士南陽郡張公〖曄〗墓誌銘》引）。"]', '诗', 'shi', '', NULL, '送張曄赴舉 二 盧庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac261a45-722e-4cfc-bc30-40e7225c6d23', '寄征衣', '寄征衣', '4b109962-b16c-4522-801b-02b14d2f760d', '唐', '["開箱整霞綺，欲製萬里衣。","愁剪鴛鴦破，恐爲相背飛。","（同前）。"]', '["开箱整霞綺，欲製万里衣。","愁剪鴛鴦破，恐爲相背飞。","（同前）。"]', '诗', 'shi', '', NULL, '寄征衣 張曄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5359edd-9093-42af-8ad0-fc831884c592', '臨終前月餘作隱語（題擬）', '臨終前月餘作隐語（題擬）', '02f85bf3-d221-4ab0-b3a7-445ea29975cc', '唐', '["許下無言奪少年，震而不雨月當弦。","風濤渭逆艅艎沒，從此無舟濟大川。","（《金石萃編》卷一一七鄭仁表《唐故左拾遺魯國孔府君墓誌銘》引）。"]', '["許下無言奪少年，震而不雨月當弦。","风濤渭逆艅艎沒，從此無舟濟大川。","（《金石萃編》卷一一七鄭仁表《唐故左拾遺魯国孔府君墓誌銘》引）。"]', '诗', 'shi', '', NULL, '臨終前月餘作隱語（題擬） 孔紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fbd5ee4-4857-4323-8975-a7f3bc16561c', '予自右轄出鎮鍾陵秘監家兄不忍遠別亟見宰坐求替遂得同赴江西時也薦福大德顯公禪門上首言歸東林亦獲結侶道路陪遊每承清論今過寺因留題詩一首', '予自右轄出鎮鍾陵秘監家兄不忍远別亟见宰坐求替遂得同赴江西时也薦福大德显公禪门上首言归东林亦獲結侶道路陪游每承清論今過寺因留題诗一首', 'b76a8941-30f9-42e3-9317-d89ee6713157', '唐', '["麟臺朝士辭書府，鳳闕禪宗出帝京。","歸到雙林親慧遠，行過五柳謁淵明。","白衣居士輕班爵，敗[衲]高僧[薄世]情。","引得病夫無外想，一心師事[竺先生]。","（見羅振玉《吉石盦叢書》影宋鈔本、《殷禮在斯堂叢書》校排本宋陳舜俞纂《廬山記》卷四。","詩缺六字，據《永樂大典》卷六六九九引宋佚名《江州志》補）（按：《全唐詩補逸》卷十二據《永樂大典》錄此詩，歸裴休，題闕另擬。","詩有誤字。","今重錄。","「一心」，宋抄誤作「二心」，羅校本已改正。","《江州志》作「一生」。","本詩作者，《永樂大典》及《廬山記》均題爲裴休，後者並收有作者兄裴謨之和詩。","岑仲勉先生《唐方鎮年表正補》謂：裴「休自中舍除江西，有張又新《建碑記》及杜牧《代讓平章事表》可證，非自右丞〖右轄〗出，休兄亦不名謨，唯《新表》中眷裴，僖宗相裴坦之兄名謨，乃知詩實坦作，後人誤書坦爲休也」。","其說可從，今據以移正。","）。"]', '["麟台朝士辞书府，鳳闕禪宗出帝京。","归到雙林親慧远，行過五柳謁淵明。","白衣居士轻班爵，敗[衲]高僧[薄世]情。","引得病夫無外想，一心師事[竺先生]。","（见羅振玉《吉石盦叢书》影宋鈔本、《殷禮在斯堂叢书》校排本宋陳舜俞纂《廬山記》卷四。","诗缺六字，據《永乐大典》卷六六九九引宋佚名《江州志》補）（按：《全唐诗補逸》卷十二據《永乐大典》錄此诗，归裴休，題闕另擬。","诗有誤字。","今重錄。","「一心」，宋抄誤作「二心」，羅校本已改正。","《江州志》作「一生」。","本诗作者，《永乐大典》及《廬山記》均題爲裴休，後者並收有作者兄裴謨之和诗。","岑仲勉先生《唐方鎮年表正補》謂：裴「休自中舍除江西，有張又新《建碑記》及杜牧《代讓平章事表》可證，非自右丞〖右轄〗出，休兄亦不名謨，唯《新表》中眷裴，僖宗相裴坦之兄名謨，乃知诗實坦作，後人誤书坦爲休也」。","其说可從，今據以移正。","）。"]', '诗', 'shi', '', NULL, '予自右轄出鎮鍾陵秘監家兄不忍遠別亟見宰坐求替遂得同赴江西時也薦福大德顯公禪門上首言歸東林亦獲結侶道路陪遊每承清論今過寺因留題詩一首 裴坦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af049a2-e9da-4821-9508-dfeb0b1aa4de', '與大願和尚詩（題擬）', '與大願和尚诗（題擬）', 'b76a8941-30f9-42e3-9317-d89ee6713157', '唐', '["竟辭聖主宮中詔，來赴遺民社內期。","（見貫休《禪月集》卷五《寄大願和尚》注引）（按：貫休詩注云二句爲「太平裴相公與師詩」，又云：「時裴公出守鍾陵，與師同行。","」又云：「裴公鎮襄陽，頻使迎取，師堅不往。","」《唐方鎮年表》考之甚詳，可參看。","又前詩題中所稱之「薦福大德顯公」，岑仲勉以爲與此大願應爲一人，只是「願、顯形近，未詳孰正」。","）。"]', '["竟辞聖主宮中詔，来赴遺民社內期。","（见貫休《禪月集》卷五《寄大願和尚》注引）（按：貫休诗注云二句爲「太平裴相公與師诗」，又云：「时裴公出守鍾陵，與師同行。","」又云：「裴公鎮襄陽，頻使迎取，師堅不往。","」《唐方鎮年表》考之甚詳，可參看。","又前诗題中所稱之「薦福大德显公」，岑仲勉以爲與此大願應爲一人，只是「願、显形近，未詳孰正」。","）。"]', '诗', 'shi', '', NULL, '與大願和尚詩（題擬） 裴坦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a838e86-2f03-4eb1-915d-8250917115ed', '和舍弟寄題東林寺', '和舍弟寄題东林寺', '1b4c9d8c-4fa6-4f99-9ffc-5ee3425bd30d', '唐', '["元非附鳳龍客，本是山猿野鹿身。","虛向班行紆[組]（祖）紱，爭如[□□□□]塵。","歡同玉季爲良伴，喜奉金[□□□]因。","今日香爐峰下過，方欣物外有遺民。","（見《吉石盦叢書》本《廬山記》卷四，缺訛據羅振玉《殷禮在斯堂叢書》校排本補改）。"]', '["元非附鳳龙客，本是山猿野鹿身。","虛向班行紆[組]（祖）紱，爭如[□□□□]塵。","歡同玉季爲良伴，喜奉金[□□□]因。","今日香爐峰下過，方欣物外有遺民。","（见《吉石盦叢书》本《廬山記》卷四，缺訛據羅振玉《殷禮在斯堂叢书》校排本補改）。"]', '诗', 'shi', '', NULL, '和舍弟寄題東林寺 裴謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3d416e-ad0b-4bbd-a3c5-9112b1c99540', '送陳讜授本府長史（題擬）', '送陳讜授本府长史（題擬）', '1b4c9d8c-4fa6-4f99-9ffc-5ee3425bd30d', '唐', '["甌閩地秀出文儒，書錦堪夸舊棄□。","（見明刻本《吟窗雜錄》卷四一）。"]', '["甌閩地秀出文儒，书錦堪夸旧棄□。","（见明刻本《吟窗杂錄》卷四一）。"]', '诗', 'shi', '', NULL, '送陳讜授本府長史（題擬） 裴謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba15563-55f9-4267-9972-370207de2d1a', '咏萬安邑（《方輿勝覽》題作《萬安驛》）', '咏万安邑（《方輿勝覽》題作《万安驛》）', '77c5d63b-d6d7-402e-bf09-0c768c2780de', '唐', '["勁兵重作付胡奴，敺雀敺魚計自疎。","地入萬安知幾許，却憐此邑始回車。","（見《錦繡萬花谷續集》卷十一「綿州」、《方輿勝覽》卷五四《綿州》）（〖1〗詩後附記云：「唐明皇幸蜀，至此而歎曰：『一安尚不可，況萬安乎？","』」）。"]', '["勁兵重作付胡奴，敺雀敺鱼計自疎。","地入万安知幾許，却怜此邑始回车。","（见《錦繡万花谷續集》卷十一「綿州」、《方輿勝覽》卷五四《綿州》）（〖1〗诗後附記云：「唐明皇幸蜀，至此而歎曰：『一安尚不可，況万安乎？","』」）。"]', '诗', 'shi', '', NULL, '咏萬安邑（《方輿勝覽》題作《萬安驛》） 張演 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f622d610-b2f9-4a35-a84d-f29150d7d021', '句', '句', '77c5d63b-d6d7-402e-bf09-0c768c2780de', '唐', '["雉膏美景在藂蔭，紅蘂丹跗次第尋。","（見宋楊伯嵒《臆乘》）。"]', '["雉膏美景在藂蔭，紅蘂丹跗次第尋。","（见宋楊伯嵒《臆乘》）。"]', '诗', 'shi', '', NULL, '句 張演 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217f9573-8a6f-40b3-baa1-d25565f44e4a', '吳興詩', '吳兴诗', '89ba9b4d-f157-4bd1-a9bb-4320897d49f5', '唐', '["桑柘遠連雲。","（見《嘉泰吳興志》卷二十）。"]', '["桑柘远連云。","（见《嘉泰吳兴志》卷二十）。"]', '诗', 'shi', '', NULL, '吳興詩 潘煒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d24c7c7-ff14-49e0-b09e-e643e047ba97', '真人酬寄羨門子', '真人酬寄羨门子', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["雲洞煙深意自迷，憶君腸斷武陵溪。","三山未覺家中遠，九府那知路甚低。","絳闕有時申再會，赤城何日手重攜。","唯愁不得分明語，惆悵長霄月又西。","（見《四庫珍本初集》本《天台前集別編》）。"]', '["云洞煙深意自迷，憶君腸斷武陵溪。","三山未覺家中远，九府那知路甚低。","絳闕有时申再會，赤城何日手重携。","唯愁不得分明語，惆悵长霄月又西。","（见《四庫珍本初集》本《天台前集別編》）。"]', '诗', 'shi', '', NULL, '真人酬寄羨門子 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1623518-2bab-4067-993f-e7a0dc46771f', '漢武帝宴西王母', '漢武帝宴西王母', '2f05ea7d-de55-4def-8790-15d2f6b4c8bc', '唐', '["花影暗回三殿月，樹聲深鎖九門霜。","（《五代史補》卷一。","此則承湯華泉同志見告）。"]', '["花影暗回三殿月，樹声深鎖九门霜。","（《五代史補》卷一。","此則承湯华泉同志见告）。"]', '诗', 'shi', '', NULL, '漢武帝宴西王母 曹唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029c090e-e95d-41aa-84a0-c1dc1119f85f', '灼灼歌 一', '灼灼歌 一', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["坐中之客皆龍虎。","（見《王狀元集注分類東坡先生詩》卷九《九日黃樓作》注引崔班《灼灼歌》）。"]', '["坐中之客皆龙虎。","（见《王狀元集注分類东坡先生诗》卷九《九日黄楼作》注引崔班《灼灼歌》）。"]', '诗', 'shi', '', NULL, '灼灼歌 一 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b02b48-49bd-4cef-b674-dcd5c7414d96', '灼灼歌 二', '灼灼歌 二', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["人心亦似春心逸。","（見陳元龍《片玉集注》卷七《玉燭新》注引崔珏詩）。"]', '["人心亦似春心逸。","（见陳元龙《片玉集注》卷七《玉燭新》注引崔珏诗）。"]', '诗', 'shi', '', NULL, '灼灼歌 二 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f6cef9-778a-46ea-9787-2c8b758e3cf4', '灼灼歌 三', '灼灼歌 三', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["舞停歌罷來中坐。","（見同書卷十《迎春樂》注引《灼灼歌》）（按：《片玉集注》引《麗情集》中詩，或稱篇名，或稱作者，或並引之，頗不一致，可參本書卷十八元稹《崔徽歌》條按語及拙輯《蘇舜欽詩文續拾》《愛愛歌》附按。","就《灼灼歌》三句出處不同稱引考察，可知「崔班」即爲崔珏之誤。","《才調集》卷三錄韋莊《傷灼灼》詩，可證崔珏與灼灼恰爲同時之人，有作詩之可能。","灼灼故事，詳《綠窗新話》卷上引《麗情集》。","又按：《全唐詩》卷五九一收崔珏《門前柳》，首句缺一字。","《文苑英華》卷三三七、《全蜀藝文志》卷十八收此詩皆不缺，前者作「先」，後者作「早」。","詩不重錄。","）。"]', '["舞停歌罷来中坐。","（见同书卷十《迎春乐》注引《灼灼歌》）（按：《片玉集注》引《丽情集》中诗，或稱篇名，或稱作者，或並引之，頗不一致，可參本书卷十八元稹《崔徽歌》條按語及拙輯《蘇舜欽诗文續拾》《愛愛歌》附按。","就《灼灼歌》三句出处不同稱引考察，可知「崔班」即爲崔珏之誤。","《才調集》卷三錄韋莊《傷灼灼》诗，可證崔珏與灼灼恰爲同时之人，有作诗之可能。","灼灼故事，詳《綠窗新話》卷上引《丽情集》。","又按：《全唐诗》卷五九一收崔珏《门前柳》，首句缺一字。","《文苑英华》卷三三七、《全蜀藝文志》卷十八收此诗皆不缺，前者作「先」，後者作「早」。","诗不重錄。","）。"]', '诗', 'shi', '', NULL, '灼灼歌 三 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e89a30fb-4084-45c0-9d64-850eb0df9d51', '它山歌', '它山歌', 'e4b10794-a8ca-4e22-b7a3-b1d2bbfe8497', '唐', '["它山堰，堰在四明之鄞懸。","一條水出四明山，晝夜長流如白練。","連接大江通海水，鹹潮直到深潭裏。","淡水雖多無計停，半邑人民田種費。","大和中有王侯令，清優爲官立民政。","昨因祈禱入山行，識得水源知利病。","櫂舟直到溪巖畔，極目江山波瀾漫。","略呼父老問來由，便設機謀造其堰。","疊石橫鋪兩山嘴，截斷鹹潮積溪水。","灌溉民田萬頃餘，此謂齊天功不毀。","民間日用自不知，年年豐稔因阿誰。","山邊却立它神廟，不爲長官興一祠。","本是長官治此水，却將飲食祭閑鬼。","時人若解感此恩，年年祭拜王元暐。"]', '["它山堰，堰在四明之鄞懸。","一條水出四明山，晝夜长流如白練。","連接大江通海水，鹹潮直到深潭裏。","淡水雖多無計停，半邑人民田種費。","大和中有王侯令，清優爲官立民政。","昨因祈禱入山行，識得水源知利病。","櫂舟直到溪巖畔，極目江山波瀾漫。","略呼父老问来由，便設機謀造其堰。","叠石橫鋪兩山嘴，截斷鹹潮積溪水。","灌溉民田万頃餘，此謂齊天功不毀。","民间日用自不知，年年豐稔因阿誰。","山邊却立它神廟，不爲长官兴一祠。","本是长官治此水，却將饮食祭闲鬼。","时人若解感此恩，年年祭拜王元暐。"]', '诗', 'shi', '', NULL, '它山歌 宗亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b06f601-b3a8-4f28-81b2-b1c80eec2595', '它山堰', '它山堰', 'e4b10794-a8ca-4e22-b7a3-b1d2bbfe8497', '唐', '["截斷寒流疊石基，海潮從此作回期。","行人自老青山路，澗急水聲無絕時。","（以上二首均見南宋魏峴《四明它山水利備覽》卷下，《四明叢書三集》本。","二詩承溫州師院張靖龍同志錄示）（〖1〗張靖龍云：南宋林元晉《回沙閘記》云：「唐僧元亮賦堰詩，有曰：『海潮從此作回期。","』人謂絕唱。","」明末李鄴嗣《甬上高僧詩》卷上曰：「縣令王元暐起它山堰，主水啓閉，民德之，亮公爲題一詩。","宋志載吾最四絕句，以公題它山堰爲第一。","所云景絕詩亦絕者也。","公又作長歌一首以記其事。","」魏峴考訂《它山歌》爲元亮所作：「人知它山之詩而不知它山之歌。","歌以言詩之未盡，詩以言歌之所不欲文。","不觀其詩，無以見亮公之絕唱，不觀其歌，無以見王侯之始謀。","予方幼時，蓋嘗耳其歌之大略矣。","每以石刻不存爲恨。","咨詢耆老有年于茲，近劃得墨刻，讀之甚喜。","或疑圖志上載絕句爲唐僧元亮所作，此刻不載歲月名稱，恐非亮公之筆。","然即其歌以溯其意，如因祈禱入山與夫櫂舟深入之語，非亮公距王侯未遠，其孰能知此耶？","」）。"]', '["截斷寒流叠石基，海潮從此作回期。","行人自老青山路，澗急水声無絕时。","（以上二首均见南宋魏峴《四明它山水利備覽》卷下，《四明叢书三集》本。","二诗承溫州師院張靖龙同志錄示）（〖1〗張靖龙云：南宋林元晉《回沙閘記》云：「唐僧元亮賦堰诗，有曰：『海潮從此作回期。","』人謂絕唱。","」明末李鄴嗣《甬上高僧诗》卷上曰：「縣令王元暐起它山堰，主水啓閉，民德之，亮公爲題一诗。","宋志載吾最四絕句，以公題它山堰爲第一。","所云景絕诗亦絕者也。","公又作长歌一首以記其事。","」魏峴考訂《它山歌》爲元亮所作：「人知它山之诗而不知它山之歌。","歌以言诗之未尽，诗以言歌之所不欲文。","不观其诗，無以见亮公之絕唱，不观其歌，無以见王侯之始謀。","予方幼时，蓋嘗耳其歌之大略矣。","每以石刻不存爲恨。","咨詢耆老有年于茲，近劃得墨刻，读之甚喜。","或疑圖志上載絕句爲唐僧元亮所作，此刻不載歲月名稱，恐非亮公之笔。","然即其歌以溯其意，如因祈禱入山與夫櫂舟深入之語，非亮公距王侯未远，其孰能知此耶？","」）。"]', '诗', 'shi', '', NULL, '它山堰 宗亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49aa5a8-92c2-44ed-a578-91c25807d6e4', '禮舍利塔', '禮舍利塔', 'e4b10794-a8ca-4e22-b7a3-b1d2bbfe8497', '唐', '["鐵輪王使鬼神功，靈塔飛來鄮嶺東。","有客不隨流水去，罄敲疎雪細雲中。","（明郭子章《明州阿育王山志》卷十）。"]', '["鐵輪王使鬼神功，靈塔飞来鄮嶺东。","有客不隨流水去，罄敲疎雪細云中。","（明郭子章《明州阿育王山志》卷十）。"]', '诗', 'shi', '', NULL, '禮舍利塔 宗亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6311c2b-1fd7-4b54-ad14-5c71b0730997', '靈鰻井', '靈鰻井', 'e4b10794-a8ca-4e22-b7a3-b1d2bbfe8497', '唐', '["散盡殘雲碧甃開，靈魚石縫露星腮。","寒生鏡底長清淺，泉脉流從印土來。","（同前。","又見同書卷五引吳越釋贊寧開寶五年撰《護塔靈鰻菩薩傳》引）。"]', '["散尽殘云碧甃开，靈鱼石縫露星腮。","寒生镜底长清淺，泉脉流從印土来。","（同前。","又见同书卷五引吳越釋贊寧开寶五年撰《護塔靈鰻菩薩傳》引）。"]', '诗', 'shi', '', NULL, '靈鰻井 宗亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be832273-364f-48eb-9c97-9241d3bfa360', '東洲', '东洲', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["江城隔水是東洲，渾似金鰲水上浮。","萬頃頹波分瀉去，一洲千古砥中流。","。"]', '["江城隔水是东洲，渾似金鰲水上浮。","万頃頹波分瀉去，一洲千古砥中流。","。"]', '诗', 'shi', '', NULL, '東洲 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370aff7e-10d4-44de-a5a4-07375cefc906', '東郎山', '东郎山', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["東郎矻立向東方，翹首朝朝候太陽。"]', '["东郎矻立向东方，翹首朝朝候太陽。"]', '诗', 'shi', '', NULL, '東郎山 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b348411-6a33-4984-8edf-8c4efcda21f4', '西郎山', '西郎山', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["西郎何事面西方？欲會東郎隔大江。","自古朋良時一遇，東郎未會恨斜陽。","（均見清汪森輯《粤西詩載》卷二二）（按：以上三詩，梁超然先生《曹鄴詩注》已收入。","《文學評論叢刊》第七輯刊同人《論晚唐詩人曹鄴》云：「《東郎山》、《西郎山》二詩在陽朔東、西郎山有石刻。","」）。"]', '["西郎何事面西方？欲會东郎隔大江。","自古朋良时一遇，东郎未會恨斜陽。","（均见清汪森輯《粤西诗載》卷二二）（按：以上三诗，梁超然先生《曹鄴诗注》已收入。","《文学評論叢刊》第七輯刊同人《論晚唐诗人曹鄴》云：「《东郎山》、《西郎山》二诗在陽朔东、西郎山有石刻。","」）。"]', '诗', 'shi', '', NULL, '西郎山 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e005b3-deaf-468f-b4f5-564f5222b688', '東都望幸賡歌（題擬）', '东都望幸賡歌（題擬）', 'bdd99cd1-5462-4693-a523-0942e4bfd26a', '唐', '["曉雲行兮西風，慶搖裔兮龍在中。","望雲光兮拜千百，西澤霈兮均東澤。","（見《文苑英華》卷四四《東都賦》）。"]', '["晓云行兮西风，慶搖裔兮龙在中。","望云光兮拜千百，西澤霈兮均东澤。","（见《文苑英华》卷四四《东都賦》）。"]', '诗', 'shi', '', NULL, '東都望幸賡歌（題擬） 李庾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de2071a-606a-4079-b8eb-d96e3182768a', '白鹿山人李端符捨書奉報四恩三有永充供奉善衆君子建尊勝幢因書長句', '白鹿山人李端符捨书奉報四恩三有永充供奉善衆君子建尊勝幢因书长句', '674e1a00-46fe-4b57-b924-18c54e7da248', '唐', '["善往因來詣法王，七生叢累獲銷亡。","還居忉利持章句，不遂天人戀色香。","波利一心瞻佛祖，文殊再遣往西方。","今朝國土雲幢立，□智巍巍天地長。","（見《江蘇通志稿金石略》卷六《李端符經幢》附）（按：此經幢今在無錫市錫惠公園內，爲八面刻石，先刻《佛頂尊勝陁羅尼經》幷序，後刻此詩，署「興甯沙門道朗」，詩後題記云：「大唐乾符三年歲次丙申十一月甲戌朔廿二日乙未建。","都維那僧宏益，上座僧全從，寺主僧行忠，老宿杜諫，都料郁□，直僧歲智宗。","」）。"]', '["善往因来詣法王，七生叢累獲銷亡。","還居忉利持章句，不遂天人戀色香。","波利一心瞻佛祖，文殊再遣往西方。","今朝国土云幢立，□智巍巍天地长。","（见《江蘇通志稿金石略》卷六《李端符經幢》附）（按：此經幢今在無錫市錫惠公园內，爲八面刻石，先刻《佛頂尊勝陁羅尼經》幷序，後刻此诗，署「兴甯沙门道朗」，诗後題記云：「大唐乾符三年歲次丙申十一月甲戌朔廿二日乙未建。","都維那僧宏益，上座僧全從，寺主僧行忠，老宿杜諫，都料郁□，直僧歲智宗。","」）。"]', '诗', 'shi', '', NULL, '白鹿山人李端符捨書奉報四恩三有永充供奉善衆君子建尊勝幢因書長句 道朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a151d8-60ec-422f-9669-a363b54e81d6', '登靈巖寺上方', '登靈巖寺上方', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["雨後靈巖寺上方，如何云者合思量。"]', '["雨後靈巖寺上方，如何云者合思量。"]', '诗', 'shi', '', NULL, '登靈巖寺上方 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610f6006-80c5-4acd-a63d-95c1903252cc', '登福唐縣樓', '登福唐縣楼', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["咸通五載後伏裏，登此福唐縣上樓。"]', '["咸通五載後伏裏，登此福唐縣上楼。"]', '诗', 'shi', '', NULL, '登福唐縣樓 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dba9148-8a2b-440b-b1ca-ac88c6b6211f', '古人早行詩', '古人早行诗', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["早起赴前程，鄰鷄尚未鳴。","（以上均見明刻本《吟窗雜錄》卷十二沙門文彧《詩格》引）。"]', '["早起赴前程，鄰鷄尚未鳴。","（以上均见明刻本《吟窗杂錄》卷十二沙门文彧《诗格》引）。"]', '诗', 'shi', '', NULL, '古人早行詩 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('011a4a69-9e9a-49f7-8b9d-1eff068143a4', '梨花（題擬）', '梨花（題擬）', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["臨風千點雪。","（見《全芳備祖前集》卷九《梨花門》）。"]', '["臨风千点雪。","（见《全芳備祖前集》卷九《梨花门》）。"]', '诗', 'shi', '', NULL, '梨花（題擬） 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93ac111-0a10-4813-a27e-211c966ce337', '天門靈泉院', '天门靈泉院', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["華亭參後最幽玄，一句能教萬古傳。","猿抱子歸青嶂後，鳥銜花落碧崖前。","雖知物理無窮際，却恐滄溟有盡年。","爲報五湖雲外客，何妨來此老林泉。","（按：《沅湘耆舊集》卷八云：「琮案：元慈利張兌《天門山圖詩》末云：『可憐宜都周內史，古冢纍纍在山址。","感時撫景亦愴然，周朴小詩何足擬？","』即指此詩也。","次聯爲中和間僧傳明語。","傳明即善會，自鶴林入夾山，有僧問如何是夾山境，答以猿抱子歸云云，朴即用其語也。","」）。"]', '["华亭參後最幽玄，一句能教万古傳。","猿抱子归青嶂後，鸟銜花落碧崖前。","雖知物理無窮際，却恐滄溟有尽年。","爲報五湖云外客，何妨来此老林泉。","（按：《沅湘耆旧集》卷八云：「琮案：元慈利張兌《天门山圖诗》末云：『可怜宜都周內史，古冢纍纍在山址。","感时撫景亦愴然，周朴小诗何足擬？","』即指此诗也。","次聯爲中和间僧傳明語。","傳明即善會，自鹤林入夾山，有僧问如何是夾山境，答以猿抱子归云云，朴即用其語也。","」）。"]', '诗', 'shi', '', NULL, '天門靈泉院 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40966bc9-d73b-4d1d-86ba-5d6cd57521d4', '南樓 一', '南楼 一', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["春山到處喜相從，又是天門十六峰。","翠壁深深回鸛鶴，青峰矗矗隱芙蓉。","乍疑日出同吳觀，祇少金泥擬漢封。","願借仙人杖九節，臨風直欲舞雙龍。"]', '["春山到处喜相從，又是天门十六峰。","翠壁深深回鸛鹤，青峰矗矗隐芙蓉。","乍疑日出同吳观，祇少金泥擬漢封。","願借仙人杖九節，臨风直欲舞雙龙。"]', '诗', 'shi', '', NULL, '南樓 一 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d0991e-3a45-451e-84a0-31e8c039c9b6', '南樓 二', '南楼 二', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["徙倚高樓夜色殘，故人聊得罄交歡。","千林日落晴偏雨，五月雲深暑亦寒。","詰曲斷巖飛鳥度，參差倒影過江看。","慚予浪着登山屐，酒罷豪吟興未闌。","（以上三首均見《鴻湘耆舊集》卷八、同治十三刊增壽等纂《直隸澧州志》卷二五、同治八年刊魏湘纂《續修慈利縣志》卷十四）（〖1〗《直隸澧州志》卷十六《隱逸》云：「周朴，隱居天門山，楚王馬殷徵召不起，著有《靈泉詩集》。","」〖2〗同書卷二六《辨訛》云：「周朴，能詩而隱，有氣節。","閩詩集中所載小傳，與《慈志》異。","其避地福州不降黃巢遇害者，吳興人也。","居天〖缺二十字〗於□□僅爲〖缺九字〗徵□則又爲唐□□□人，未可強合爲一。","其《天門靈泉院》詩『不惟用唐僧，傳明語即起』，已直溯其事。","章華孫斯億乃謂朴生於晉，老於五代，所詠之靈泉，屬慈，非石門夾山之靈泉寺。","指爲唐僧周朴詩，志亦載其墓，稱晉處士，不知何考？","若謂生於石晉時，則馬氏早滅；若所指司馬晉，則又先馬殷數百年，相距凡七姓八朝。","只是詩與《南樓》二首俱近體，非前五代人作。","而廖大隱《楚風補》又以朴爲慈利人，唐末寓福州，摭採閩集，益以《南樓》二作。","不知寓福者，本吳興人。","閩徐興公刻朴詩集，敍述甚詳，集內亦無《靈泉院》、《南樓》詩，與志載居若墓並在天門山，自當另爲一朴。","但閩集有《弔李群玉》一絕，曰『知何處』，曰『隔岸香』，固亦嘗遊澧者。","其《靈泉院》、《南樓詩》之爲慈周朴作，抑爲吳周朴遊澧時作，而閩集或以隔遠失採，惜不得《慈父》中所紀《靈泉詩集》具覽，一釐正之，並以決朴墓之在慈與辭楚辟之，信有事否？","若氏族譜，直載爲福州人，則尤疏謬者也。","」今按：《全唐詩》卷六七三收周朴詩一卷，其中有《弔李群玉》一首，可證朴確曾客澧。","又《宿玉泉寺》一首，《直隸澧州志》卷二四，以爲寺在澧州。","又有《春中途中寄南巴崔使君》、《喜賀拔先輩衡陽除正字》、《次梧州卻寄永州使君》，疑朴自巴东入湘，复南行经澧、衡、永、梧而南游。","《直隸澧州志》所載慈利另有一周朴之根據，尚嫌不足。","惟此说罕爲人知，謹錄出以資研究。","）。"]', '["徙倚高楼夜色殘，故人聊得罄交歡。","千林日落晴偏雨，五月云深暑亦寒。","詰曲斷巖飞鸟度，參差倒影過江看。","慚予浪着登山屐，酒罷豪吟兴未闌。","（以上三首均见《鴻湘耆旧集》卷八、同治十三刊增壽等纂《直隸澧州志》卷二五、同治八年刊魏湘纂《續修慈利縣志》卷十四）（〖1〗《直隸澧州志》卷十六《隐逸》云：「周朴，隐居天门山，楚王马殷徵召不起，著有《靈泉诗集》。","」〖2〗同书卷二六《辨訛》云：「周朴，能诗而隐，有氣節。","閩诗集中所載小傳，與《慈志》異。","其避地福州不降黄巢遇害者，吳兴人也。","居天〖缺二十字〗於□□僅爲〖缺九字〗徵□則又爲唐□□□人，未可強合爲一。","其《天门靈泉院》诗『不惟用唐僧，傳明語即起』，已直溯其事。","章华孫斯億乃謂朴生於晉，老於五代，所詠之靈泉，屬慈，非石门夾山之靈泉寺。","指爲唐僧周朴诗，志亦載其墓，稱晉处士，不知何考？","若謂生於石晉时，則马氏早滅；若所指司马晉，則又先马殷數百年，相距凡七姓八朝。","只是诗與《南楼》二首俱近體，非前五代人作。","而廖大隐《楚风補》又以朴爲慈利人，唐末寓福州，摭採閩集，益以《南楼》二作。","不知寓福者，本吳兴人。","閩徐兴公刻朴诗集，敍述甚詳，集內亦無《靈泉院》、《南楼》诗，與志載居若墓並在天门山，自當另爲一朴。","但閩集有《弔李群玉》一絕，曰『知何处』，曰『隔岸香』，固亦嘗游澧者。","其《靈泉院》、《南楼诗》之爲慈周朴作，抑爲吳周朴游澧时作，而閩集或以隔远失採，惜不得《慈父》中所紀《靈泉诗集》具覽，一釐正之，並以決朴墓之在慈與辞楚辟之，信有事否？","若氏族譜，直載爲福州人，則尤疏謬者也。","」今按：《全唐诗》卷六七三收周朴诗一卷，其中有《弔李群玉》一首，可證朴確曾客澧。","又《宿玉泉寺》一首，《直隸澧州志》卷二四，以爲寺在澧州。","又有《春中途中寄南巴崔使君》、《喜賀拔先輩衡陽除正字》、《次梧州卻寄永州使君》，疑朴自巴东入湘，复南行经澧、衡、永、梧而南游。","《直隸澧州志》所載慈利另有一周朴之根據，尚嫌不足。","惟此说罕爲人知，謹錄出以資研究。","）。"]', '诗', 'shi', '', NULL, '南樓 二 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6a3cda-f8c5-4850-8f82-12c5ff331e78', '句', '句', '632cfd82-c91f-4f47-b441-f84cb6e18f88', '唐', '["事向無心得。","（《老學庵筆記》卷四）。"]', '["事向無心得。","（《老学庵笔記》卷四）。"]', '诗', 'shi', '', NULL, '句 章碣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3523ae3a-2c29-4cb3-bede-3987bd19fe00', '', '', '66c92cc2-0574-4710-9029-c27a02b3e1cc', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陳蓬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('111c8a0e-49ee-460c-9242-086c9e72f148', '讖', '讖', '66c92cc2-0574-4710-9029-c27a02b3e1cc', '唐', '["東去無邊海，西來萬頃田。","松山沙徑合，朱紫出其間。"]', '["东去無邊海，西来万頃田。","松山沙徑合，朱紫出其间。"]', '诗', 'shi', '', NULL, '讖 陳蓬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af8f87fd-daba-4c24-bfc1-a019ef4a5420', '詩', '诗', '66c92cc2-0574-4710-9029-c27a02b3e1cc', '唐', '["石頭犖确高低踏，竹戶鼓亨左右間。","（均見宋梁克家《淳熙三山志》卷六）。"]', '["石头犖确高低踏，竹戶鼓亨左右间。","（均见宋梁克家《淳熙三山志》卷六）。"]', '诗', 'shi', '', NULL, '詩 陳蓬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433f3f26-39c1-433b-9dd2-75060d91f5be', '隱居即事', '隐居即事', '6a94351c-0ee7-4a8a-aa4f-c2752657f9f7', '唐', '["半榻和雲臥碧山，飄飄似鶴一身閒。","十年不作紅塵夢，卓午呼童早閉關。","（見《光緒仙居志》卷二三）。"]', '["半榻和云臥碧山，飄飄似鹤一身閒。","十年不作紅塵梦，卓午呼童早閉关。","（见《光緒仙居志》卷二三）。"]', '诗', 'shi', '', NULL, '隱居即事 蔣琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2f0618-a57a-432c-bf15-e4a99fac100e', '日泊', '日泊', '6a94351c-0ee7-4a8a-aa4f-c2752657f9f7', '唐', '["誰惜光陰似惜金，十年湖海已投簪。","於今雨屋（《安州詩錄》作「屋雨」）青燈夜，消盡風塵未了心。","（見清戚鶴泉編《三台詩錄》卷一。","張靖龍云見清王魏勝《安州詩錄》卷一）。"]', '["誰惜光陰似惜金，十年湖海已投簪。","於今雨屋（《安州诗錄》作「屋雨」）青灯夜，消尽风塵未了心。","（见清戚鹤泉編《三台诗錄》卷一。","張靖龙云见清王魏勝《安州诗錄》卷一）。"]', '诗', 'shi', '', NULL, '日泊 蔣琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50bebea-1991-43b7-8b92-3cb5da76f2bb', '詞 一', '词 一', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["吳刀楚製爲佩褘，纖羅霧縠爲羽衣。","含商咀徵歌露晞，珠履颯沓歌袖飛。","淒風戛起素雲回，車怠馬煩客忘歸，蘭膏明燭承夜暉。"]', '["吳刀楚製爲佩褘，纖羅霧縠爲羽衣。","含商咀徵歌露晞，珠履颯沓歌袖飞。","淒风戛起素云回，车怠马煩客忘归，蘭膏明燭承夜暉。"]', '诗', 'shi', '', NULL, '詞 一 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e83773-c3f0-46ee-8748-860c3fa4df13', '詞 二', '词 二', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["桂宮柏寢擬天居，朱爵文窗韜碧疏。","象床瑤席鎮犀渠，雕屏合匝組帷舒。","秦箏趙瑟挾笙竽，垂璫散佩盈玉除，停觴不御欲誰須。"]', '["桂宮柏寢擬天居，朱爵文窗韜碧疏。","象床瑤席鎮犀渠，雕屏合匝組帷舒。","秦箏趙瑟挾笙竽，垂璫散佩盈玉除，停觴不御欲誰須。"]', '诗', 'shi', '', NULL, '詞 二 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef929288-7a52-4f73-aca1-7be72d725848', '詞 三', '词 三', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["三星差池露霑濕，絃悲管清月將入。","寒光蕭條候蟲急，荆王流歎楚妃泣。","紅顏難長時易戢，凝華結綵久延立，非君之故豈妄集。"]', '["三星差池露霑濕，絃悲管清月將入。","寒光蕭條候蟲急，荆王流歎楚妃泣。","紅顏难长时易戢，凝华結綵久延立，非君之故豈妄集。"]', '诗', 'shi', '', NULL, '詞 三 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b438e7cd-a2f5-43dc-b4ce-b6c5bbd9f6b3', '詞 四', '词 四', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["池中赤鯉庖所捐，琴高乘去飛上天。","命逢福世丁溢恩，簪巾藉綺昇曲筵。","恩厚德深委如山，潔誠洗志期暮年，烏臼馬角寧足言。","（影印本《詩淵》第六冊第四一一五頁）。"]', '["池中赤鯉庖所捐，琴高乘去飞上天。","命逢福世丁溢恩，簪巾藉綺昇曲筵。","恩厚德深委如山，潔誠洗志期暮年，烏臼马角寧足言。","（影印本《诗淵》第六冊第四一一五頁）。"]', '诗', 'shi', '', NULL, '詞 四 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3adc851-31b6-4fe3-a440-9467c1a38dcf', '句 一', '句 一', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["不知天上月，曾別幾多人？","（見宋江少虞《皇朝事實類苑》卷五九引李錞《李希聲詩話》引）（〖1〗《李希聲詩話》云：「余亡友李秉彝德叟寒暑假爲余曰：『家藏唐邵謁詩八十篇，甚工。","謁選於吏部，部中牓此詩曰：有能過此者，當先注官。","衆無間言。","……』余欲借傳，因循不果。","」按：今傳謁詩僅三十二首，未及半數。","）。"]', '["不知天上月，曾別幾多人？","（见宋江少虞《皇朝事實類苑》卷五九引李錞《李希声诗話》引）（〖1〗《李希声诗話》云：「余亡友李秉彝德叟寒暑假爲余曰：『家藏唐邵謁诗八十篇，甚工。","謁選於吏部，部中牓此诗曰：有能過此者，當先注官。","衆無间言。","……』余欲借傳，因循不果。","」按：今傳謁诗僅三十二首，未及半數。","）。"]', '诗', 'shi', '', NULL, '句 一 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd269885-ff71-4f73-8511-76140e5bfa4e', '句 二', '句 二', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["望望不相近。","（見宋李龏《剪綃集》卷下引）。"]', '["望望不相近。","（见宋李龏《剪綃集》卷下引）。"]', '诗', 'shi', '', NULL, '句 二 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e3722a-ad26-4b9d-8718-04548e0c1f00', '遇（疑爲「過」）信美臺詩', '遇（疑爲「過」）信美台诗', '3f88f6d2-c039-4ee1-a032-d0ef1e4d9278', '唐', '["零陵郡北雲帆落，信美臺前江月明。","石淺風高灘瀨急，孤舟一夜聽寒聲。","（見《輿地紀勝》卷五六《永州》）。"]', '["零陵郡北云帆落，信美台前江月明。","石淺风高灘瀨急，孤舟一夜听寒声。","（见《輿地紀勝》卷五六《永州》）。"]', '诗', 'shi', '', NULL, '遇（疑爲「過」）信美臺詩 李當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69024f14-167d-4a9f-8b99-b876de406c43', '送友人北遊', '送友人北游', '1d584162-0b85-4f01-a204-7683e2985eac', '唐', '["東歸未遂心，北去幾沉吟。","把酒思鄉遠，投文入塞深。","晉山擎白道，汾水截青林。","想見連天雪，安知（一作「長安」）是積霖。","（見《文苑英華》卷二八三、《唐音統籤》卷六四九《戊籤》六四）。"]', '["东归未遂心，北去幾沉吟。","把酒思乡远，投文入塞深。","晉山擎白道，汾水截青林。","想见連天雪，安知（一作「长安」）是積霖。","（见《文苑英华》卷二八三、《唐音統籤》卷六四九《戊籤》六四）。"]', '诗', 'shi', '', NULL, '送友人北遊 張喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac9a2b4-6ab4-4152-8cc6-89b7fe438c50', '頌 一', '頌 一', '7677efce-3f5f-493f-906b-6612e476a915', '唐', '["三十年來住子（《祖堂集》卷十八作「紫」）湖，二時粥飯（《祖堂集》及《景德傳燈錄》卷十作「齋粥」）氣力麤。","無事上山走一轉（《祖堂集》、《燈錄》作「每日上山三五轉」）。","試（《五燈會元》卷四作「借」）問（《燈錄》作「問汝」）時人（《祖堂集》作「迴頭問汝」）會也無。"]', '["三十年来住子（《祖堂集》卷十八作「紫」）湖，二时粥飯（《祖堂集》及《景德傳灯錄》卷十作「斋粥」）氣力麤。","無事上山走一轉（《祖堂集》、《灯錄》作「每日上山三五轉」）。","試（《五灯會元》卷四作「借」）问（《灯錄》作「问汝」）时人（《祖堂集》作「迴头问汝」）會也無。"]', '诗', 'shi', '', NULL, '頌 一 利蹤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68182f75-c67e-4c43-8bc7-32d5527de8c6', '頌 二', '頌 二', '7677efce-3f5f-493f-906b-6612e476a915', '唐', '["從來事非物，方便名爲佛。","中下競（《祖堂集》作「覓」）是非，上流（《祖堂集》作「士」）始知屈。"]', '["從来事非物，方便名爲佛。","中下競（《祖堂集》作「覓」）是非，上流（《祖堂集》作「士」）始知屈。"]', '诗', 'shi', '', NULL, '頌 二 利蹤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7417ea-a463-47db-9260-455954cc87f5', '臨行頌三首 一', '臨行頌三首 一', '7677efce-3f5f-493f-906b-6612e476a915', '唐', '["我聞過去佛，縱橫盡丈夫。","示汝真歸處，千江月影孤。"]', '["我闻過去佛，縱橫尽丈夫。","示汝真归处，千江月影孤。"]', '诗', 'shi', '', NULL, '臨行頌三首 一 利蹤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d947660-a80f-4cd3-a93e-30f6aab61ed1', '臨行頌三首 二', '臨行頌三首 二', '7677efce-3f5f-493f-906b-6612e476a915', '唐', '["觀音與文殊，示我常飛動。","吾今已歸真，觸處皆無用。","。"]', '["观音與文殊，示我常飞动。","吾今已归真，觸处皆無用。","。"]', '诗', 'shi', '', NULL, '臨行頌三首 二 利蹤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd39f64-e3b8-49f2-8feb-c6fbc09dc5de', '臨行頌三首 三', '臨行頌三首 三', '7677efce-3f5f-493f-906b-6612e476a915', '唐', '["佛性本來無阻障，衆生不識難歸向。","若見如來成佛時，莫向世間求取相。","（以上五首均見宋渭頤藏主編《古尊宿語錄》卷十二《衢州子湖山第一代神力禪師語錄》）（按：《祖堂集》卷十八作「紫湖和尚」。","）。"]', '["佛性本来無阻障，衆生不識难归向。","若见如来成佛时，莫向世间求取相。","（以上五首均见宋渭頤藏主編《古尊宿語錄》卷十二《衢州子湖山第一代神力禪師語錄》）（按：《祖堂集》卷十八作「紫湖和尚」。","）。"]', '诗', 'shi', '', NULL, '臨行頌三首 三 利蹤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6a66d22-0961-4133-b997-b3a939cb6732', '歌', '歌', 'eaa17411-40c3-42f6-87c9-03416c008bd1', '唐', '["咸通七載初參道，到處逢言不識言。","心裏癡（《五燈會元》作「疑」）團若栲栳，三春不樂止林泉。","忽遇法王氈上坐，便陳疑懇向師前。","師從氈上那伽起（一作「定」），袒膊當胸打一拳。","駭散癡（《五燈會元》作「疑」）團獦狚落，舉頭看見日初圓。","從茲蹬蹬以碣碣，直至如今常快活。","只聞肚裏飽膨脝，更不東西去持鉢。"]', '["咸通七載初參道，到处逢言不識言。","心裏癡（《五灯會元》作「疑」）團若栲栳，三春不乐止林泉。","忽遇法王氈上坐，便陳疑懇向師前。","師從氈上那伽起（一作「定」），袒膊當胸打一拳。","駭散癡（《五灯會元》作「疑」）團獦狚落，舉头看见日初圓。","從茲蹬蹬以碣碣，直至如今常快活。","只闻肚裏飽膨脝，更不东西去持鉢。"]', '诗', 'shi', '', NULL, '歌 羅漢和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5816148f-4760-4f91-a3de-5562bff924e7', '偈', '偈', 'eaa17411-40c3-42f6-87c9-03416c008bd1', '唐', '["宇內爲閑客，人中作野僧。","任從他笑我，隨處自騰騰。","（均見《景德傳燈錄》卷十一、《五燈會元》卷四）。"]', '["宇內爲闲客，人中作野僧。","任從他笑我，隨处自腾腾。","（均见《景德傳灯錄》卷十一、《五灯會元》卷四）。"]', '诗', 'shi', '', NULL, '偈 羅漢和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f875cd5-78f4-4074-8715-7ac8775d48f7', '海棠（補序）', '海棠（補序）', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["（按：《全唐詩》卷五六○錄此序僅存三十九字，殆據《容齋隨筆》卷七之節錄本。","陳耀東據《古今圖書集成·草木典》卷二九九《海棠部》錄此序。","）。"]', '["（按：《全唐诗》卷五六○錄此序僅存三十九字，殆據《容斋隨笔》卷七之節錄本。","陳耀东據《古今圖书集成·草木典》卷二九九《海棠部》錄此序。","）。"]', '诗', 'shi', '', NULL, '海棠（補序） 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c86f796-4e6e-4acc-9a0c-6155ae794b67', '海棠', '海棠', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["四海應無蜀海棠，一時開處一城香。","晴來使府低臨檻，雨後人家散出墻。","閑地細飄浮淨蘚，短亭深綻隔垂楊。","從來看盡詩誰苦，不及歡遊與畫將。","（同前）。"]', '["四海應無蜀海棠，一时开处一城香。","晴来使府低臨檻，雨後人家散出墻。","闲地細飄浮淨蘚，短亭深綻隔垂楊。","從来看尽诗誰苦，不及歡游與畫將。","（同前）。"]', '诗', 'shi', '', NULL, '海棠 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('718e61f4-84c8-4a16-ad44-4084f4a60639', '再遊雲門訪僧不遇', '再游云门訪僧不遇', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["數歇渡深水，漸非塵俗間。","泉聲入秋寺，月色徧寒山。","石路幾迴雪，禪房又閉關。","不知雙樹客，何處與雲閑。","（見《會稽掇英總集》卷六）（按：《全唐詩》卷五九五收作于武陵詩，題作《夜尋僧不遇》。","當以薛作爲是。","）。"]', '["數歇渡深水，漸非塵俗间。","泉声入秋寺，月色徧寒山。","石路幾迴雪，禪房又閉关。","不知雙樹客，何处與云闲。","（见《會稽掇英總集》卷六）（按：《全唐诗》卷五九五收作于武陵诗，題作《夜尋僧不遇》。","當以薛作爲是。","）。"]', '诗', 'shi', '', NULL, '再遊雲門訪僧不遇 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3c9166-718e-4709-9de0-d34367228504', '風詩', '风诗', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["就樹撮將黃葉去，入山吹出白雲來。","（見《吟窗雜錄》卷十四《詩中旨格》）。"]', '["就樹撮將黄葉去，入山吹出白云来。","（见《吟窗杂錄》卷十四《诗中旨格》）。"]', '诗', 'shi', '', NULL, '風詩 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a3eedd-5330-4301-9d85-806a8bd8b00b', '', '', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1531341d-6f04-4bb7-b33d-dc777d39950f', '野廟碑附詩', '野廟碑附诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["土木其形，竊吾民之酒牲，固無以名。","土木其智，竊吾君之祿位，如何可議。","祿位頎頎，酒牲甚微，神之饗也，孰云其非。","視吾之碑，知斯文之孔碑。","（見《甫里先生文集》卷十八、《唐文粹》卷五二）（按：《全唐詩》卷六一九收《紀夢遊甘露寺》第十四句缺三字。","今檢《四庫全書》本《甫里集》卷四，此句作「嘹嘵餘韻𠲜」。","詩甚長，不重錄。","）。"]', '["土木其形，竊吾民之酒牲，固無以名。","土木其智，竊吾君之祿位，如何可議。","祿位頎頎，酒牲甚微，神之饗也，孰云其非。","視吾之碑，知斯文之孔碑。","（见《甫里先生文集》卷十八、《唐文粹》卷五二）（按：《全唐诗》卷六一九收《紀梦游甘露寺》第十四句缺三字。","今檢《四庫全书》本《甫里集》卷四，此句作「嘹嘵餘韻𠲜」。","诗甚长，不重錄。","）。"]', '诗', 'shi', '', NULL, '野廟碑附詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b441545a-45db-40f3-91e5-cae54048c216', '句', '句', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["思量浮世何如夢，試就南牕一寐看。","（《大正藏》本崔致遠《唐大薦福寺故寺主翻經大德法藏和尚傳》）。"]', '["思量浮世何如梦，試就南牕一寐看。","（《大正藏》本崔致远《唐大薦福寺故寺主翻經大德法藏和尚傳》）。"]', '诗', 'shi', '', NULL, '句 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a456267-4189-4869-ba20-b4492e5d57ed', '臨終偈', '臨終偈', 'fea66df8-5d5e-40a4-8d3a-28ee7f7597f0', '唐', '["大江沉盡小江現，明月高峰法自流。","石牛水上臥，影落孤峰頭。","荒田聞我訝，始同不繫舟。","（見《祖堂集》卷七）。"]', '["大江沉尽小江現，明月高峰法自流。","石牛水上臥，影落孤峰头。","荒田闻我訝，始同不繫舟。","（见《祖堂集》卷七）。"]', '诗', 'shi', '', NULL, '臨終偈 善會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda884b4-30c9-47f4-b067-182805227d82', '頌 一', '頌 一', 'fea66df8-5d5e-40a4-8d3a-28ee7f7597f0', '唐', '["明明無悟法，悟法却迷人。","長舒兩脚睡，無僞亦無真。","（見《景德傳燈錄》卷十五、《五燈會元》卷五）。"]', '["明明無悟法，悟法却迷人。","长舒兩脚睡，無僞亦無真。","（见《景德傳灯錄》卷十五、《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '頌 一 善會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee645a7-673a-410f-8047-669832783f51', '頌 二', '頌 二', 'fea66df8-5d5e-40a4-8d3a-28ee7f7597f0', '唐', '["勞持生死法，唯向佛邊求。","目前迷正理，擬火覓浮漚。","（《五燈會元》卷五）。"]', '["勞持生死法，唯向佛邊求。","目前迷正理，擬火覓浮漚。","（《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '頌 二 善會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfcd4a6-a680-475d-9c80-c9182d03d90b', '奉和大德思天台次韻', '奉和大德思天台次韻', '2ee2c0eb-1cd4-4e12-ae63-6b4932e362f8', '唐', '["金地爐峰秀氣濃，近離雙澗憶青松。","劚泉拄錫淨心相，遠傳佛教觀真容。","（見日本三井唐院藏真跡本，轉錄自傅雲龍《遊歷日本圖經》）。"]', '["金地爐峰秀氣濃，近離雙澗憶青松。","劚泉拄錫淨心相，远傳佛教观真容。","（见日本三井唐院藏真跡本，轉錄自傅云龙《游歷日本圖經》）。"]', '诗', 'shi', '', NULL, '奉和大德思天台次韻 李達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067ded67-e6f9-4c14-a1f8-fdd98bdf787f', '次韻二首 一', '次韻二首 一', '9737412f-1ef0-4d79-a220-b1a04225de79', '唐', '["大理車回教正濃，乍離金地意思松。","滄溟要過流杯送，禪坐依然政法容。"]', '["大理车回教正濃，乍離金地意思松。","滄溟要過流杯送，禪坐依然政法容。"]', '诗', 'shi', '', NULL, '次韻二首 一 詹景全 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27aed459-df3b-4d56-a64c-72f49bca9ed6', '次韻二首 二', '次韻二首 二', '9737412f-1ef0-4d79-a220-b1a04225de79', '唐', '["一乘元儀道無踪，居憇觀心靜倚松。","三界永除幾外想，一誠歸禮釋迦容。","（同前）（按：李達、詹景全詩，皆轉錄自張步雲《唐代逸詩輯存》。","）。"]', '["一乘元儀道無踪，居憇观心静倚松。","三界永除幾外想，一誠归禮釋迦容。","（同前）（按：李達、詹景全诗，皆轉錄自張步云《唐代逸诗輯存》。","）。"]', '诗', 'shi', '', NULL, '次韻二首 二 詹景全 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dab6a1a-a294-4e74-81a7-57ad72ba9c40', '頌', '頌', '8b6e22d5-8c5c-4428-8f6d-bb6e354c4fae', '唐', '["藏身沒跡師親囑，沒跡藏身自可知。","昔日時時逢劍客，今朝往往遇癡兒。","（《祖堂集》卷五）。"]', '["藏身沒跡師親囑，沒跡藏身自可知。","昔日时时逢劍客，今朝往往遇癡兒。","（《祖堂集》卷五）。"]', '诗', 'shi', '', NULL, '頌 休靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9085546-ea0a-4686-8336-32e9466c2b05', '因道吾指夾山尋師頌', '因道吾指夾山尋師頌', '6fc9f7ab-e977-4591-8295-31bf02d440a3', '唐', '["京口談玄已有名，吾山特地涉途程。","雖云法眼無瑕翳，爭奈真人掩耳聽。","參學須參真心匠。","合頭須詐不勞聆。","此來更欲尋師去，決至應當暫改形。","道友當年深契會，老僧今日苦叮嚀。","特報水雲知識道，半秋孤月落花亭。"]', '["京口談玄已有名，吾山特地涉途程。","雖云法眼無瑕翳，爭奈真人掩耳听。","參学須參真心匠。","合头須詐不勞聆。","此来更欲尋師去，決至應當暫改形。","道友當年深契會，老僧今日苦叮嚀。","特報水云知識道，半秋孤月落花亭。"]', '诗', 'shi', '', NULL, '因道吾指夾山尋師頌 擇禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04d72bc-a3b5-4a38-baa0-eb40f5a0595a', '夾山頓遇以華亭頌', '夾山頓遇以华亭頌', '6fc9f7ab-e977-4591-8295-31bf02d440a3', '唐', '["一泛輕舟數十年，隨風逐浪任因緣。","祇道子期能□（此字殘損）律，誰知座主將參禪。","□前無寺成椿橛，句下相投事不然。","遙指碧潭垂釣叟，被師呵退頓忘筌。","（同前）。"]', '["一泛轻舟數十年，隨风逐浪任因緣。","祇道子期能□（此字殘損）律，誰知座主將參禪。","□前無寺成椿橛，句下相投事不然。","遙指碧潭垂釣叟，被師呵退頓忘筌。","（同前）。"]', '诗', 'shi', '', NULL, '夾山頓遇以華亭頌 擇禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b1550f-2b1d-4de2-93d9-80d442a8ef5a', '心珠歌', '心珠歌', '9fe4e426-b826-4443-87c5-37ae2242f3f0', '唐', '["山僧自達空門久，淬鍊心珠功已構。","珠迥玲瓏主客分，往往聲如師子吼。","師子吼，非常久，皆明佛性真如理。","有時往往自思惟，豁然大意心歡喜。","或造經，或造論，或說漸兮或說頓。","若在諸佛運神通，或在凡夫興鄙恡。","此心珠，如水月，地角天涯無殊別。","祇因迷悟有參差，所以如來多種說。","地獄趣，餓鬼趣，多種輪迴無暫住。","此非諸佛不慈悲，豈非閻王配交做。","勸時流，深體悉，見在心珠勿浪失。","五蘊身全尚不知，百骸散後何處覓。","（見《景德傳燈錄》卷三十）。"]', '["山僧自達空门久，淬鍊心珠功已構。","珠迥玲瓏主客分，往往声如師子吼。","師子吼，非常久，皆明佛性真如理。","有时往往自思惟，豁然大意心歡喜。","或造經，或造論，或说漸兮或说頓。","若在諸佛運神通，或在凡夫兴鄙恡。","此心珠，如水月，地角天涯無殊別。","祇因迷悟有參差，所以如来多種说。","地獄趣，餓鬼趣，多種輪迴無暫住。","此非諸佛不慈悲，豈非閻王配交做。","勸时流，深體悉，见在心珠勿浪失。","五蘊身全尚不知，百骸散後何处覓。","（见《景德傳灯錄》卷三十）。"]', '诗', 'shi', '', NULL, '心珠歌 寰普 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6c4ebe-2a01-4a49-a821-22f860a9791b', '簡寂觀', '簡寂观', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["物外靈蹤客到稀，竹房斜掩舊荆扉。","丹書萬卷題朱字，碧岫千重鎖翠微。","泣露白猿攜子去，唳風玄鶴傍人歸。","祇應玉闕名長在，日暮閑雲空自飛。","（見《吉石庵叢書》本《廬山記》卷四）。"]', '["物外靈蹤客到稀，竹房斜掩旧荆扉。","丹书万卷題朱字，碧岫千重鎖翠微。","泣露白猿携子去，唳风玄鹤傍人归。","祇應玉闕名长在，日暮闲云空自飞。","（见《吉石庵叢书》本《廬山記》卷四）。"]', '诗', 'shi', '', NULL, '簡寂觀 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebef1610-2ff1-4fe0-96e2-a23e8ddb25db', '馬詩', '马诗', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["塵土臥多毛色暗，風霜受盡眼由（《詩學指南》本「猶」）明。","（見《吟窗雜錄》卷十四《詩中旨格》）（按：陸游引此二句爲盧肇詩，見本書卷三十一。","）。"]', '["塵土臥多毛色暗，风霜受尽眼由（《诗学指南》本「猶」）明。","（见《吟窗杂錄》卷十四《诗中旨格》）（按：陸游引此二句爲盧肇诗，见本书卷三十一。","）。"]', '诗', 'shi', '', NULL, '馬詩 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55bff4fe-bca5-4eb1-8b70-ba9e1bc31c28', '題招提院靜照堂', '題招提院静照堂', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["缾錫爲生久，門闌過客疎。","於閑見真寂，燕坐此清虛。","事事皆身外，悠悠度歲餘。","如何繁草木，還長舊庭除。","（見《至元嘉禾志》卷三二）。"]', '["缾錫爲生久，门闌過客疎。","於闲见真寂，燕坐此清虛。","事事皆身外，悠悠度歲餘。","如何繁草木，還长旧庭除。","（见《至元嘉禾志》卷三二）。"]', '诗', 'shi', '', NULL, '題招提院靜照堂 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4da1ba4-7cbe-49e4-a63c-fdeea84b3dee', '清弋江田舍', '清弋江田舍', 'f3837197-b414-428f-bd46-0c8b1aca344e', '唐', '["草木翳荒徑，巖阿有竹扉。","童牛隨㹀出，乳燕哺雛歸。","釣艇橫幽渚，耕蓑挂落暉。","罕知鹽酪味，父子入城稀。","（見民國十三年刊徐乃昌等纂《南陵縣志》卷四二）。"]', '["草木翳荒徑，巖阿有竹扉。","童牛隨㹀出，乳燕哺雛归。","釣艇橫幽渚，耕蓑挂落暉。","罕知鹽酪味，父子入城稀。","（见民国十三年刊徐乃昌等纂《南陵縣志》卷四二）。"]', '诗', 'shi', '', NULL, '清弋江田舍 張賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5232661b-6a8f-4042-a157-3c9bb9fb9dac', '庚子年遇赦', '庚子年遇赦', '2965da63-c004-4441-951d-324aaf46e36c', '唐', '["時清無大赦，何以安天下？直到赤眉來，始尋黃紙寫，草草蠲賦與（《學海》本作「稅」），忙忙點兵馬。"]', '["时清無大赦，何以安天下？直到赤眉来，始尋黄紙寫，草草蠲賦與（《学海》本作「稅」），忙忙点兵马。"]', '诗', 'shi', '', NULL, '庚子年遇赦 張孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da87756d-70a5-4319-9e72-8b61f2f01e47', '雜言', '杂言', '2965da63-c004-4441-951d-324aaf46e36c', '唐', '["祇愛輕與肥，不憂貧與賤。","著牙賣朱紫，斷錢賖舉選。","（均見何光遠《鑑誡錄》卷九）（〖1〗《鑑戒錄》云：「又駕在蜀日，孜著雜言數百篇，傷時頗切，其一首兩聯云〖略〗。","」前二句，《全唐詩》卷六百七已據《唐詩紀事》收入。","）。"]', '["祇愛轻與肥，不憂貧與賤。","著牙賣朱紫，斷錢賖舉選。","（均见何光远《鑑誡錄》卷九）（〖1〗《鑑戒錄》云：「又駕在蜀日，孜著杂言數百篇，傷时頗切，其一首兩聯云〖略〗。","」前二句，《全唐诗》卷六百七已據《唐诗紀事》收入。","）。"]', '诗', 'shi', '', NULL, '雜言 張孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e0c991-3974-48fc-a8f1-e39078404b69', '送白相公', '送白相公', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["飛龍在天，雲雨闐闐。","賢相秉鈞，倫方序圓。","時哉時哉，君其勉焉。","（見《文苑英華》卷六六二《上白相公啓》引）。"]', '["飞龙在天，云雨闐闐。","賢相秉鈞，倫方序圓。","时哉时哉，君其勉焉。","（见《文苑英华》卷六六二《上白相公啓》引）。"]', '诗', 'shi', '', NULL, '送白相公 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('120ad0bb-c56c-4dc4-a014-5a8d686cfcb0', '元日觀仗（之二）', '元日观仗（之二）', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["紫掖晴來宮殿高，萬方瞻拜赤霜袍。","關中王氣浮雙闕，海外歡聲抃九鼇。","晨箭莫催青鏁漏，壽宮方獻碧花桃。","香煙不動龍顏悅，初日輝輝上采旄（施）。","（見《古今歲時雜詠》卷一。","共三首，《全唐詩》僅收二首）。"]', '["紫掖晴来宮殿高，万方瞻拜赤霜袍。","关中王氣浮雙闕，海外歡声抃九鼇。","晨箭莫催青鏁漏，壽宮方獻碧花桃。","香煙不动龙顏悅，初日輝輝上采旄（施）。","（见《古今歲时杂詠》卷一。","共三首，《全唐诗》僅收二首）。"]', '诗', 'shi', '', NULL, '元日觀仗（之二） 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a32053-5571-4347-b202-c35501bd008f', '寄湖州開元寺座主', '寄湖州开元寺座主', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["傍城花柳覆精廬。","（見《輿地紀勝》卷四《安吉州》、《嘉泰吳興志》卷十三）。"]', '["傍城花柳覆精廬。","（见《輿地紀勝》卷四《安吉州》、《嘉泰吳兴志》卷十三）。"]', '诗', 'shi', '', NULL, '寄湖州開元寺座主 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e74aafa0-76b3-48ba-a186-8850cd847018', '', '', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c04b0d7-3625-40d4-be84-d16919ac0e28', '偈 一', '偈 一', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["法身無作化身作，薄伽玄應諸病藥。","啀喍聞響擬嘷吠，焰水覓魚癡老鶴。","（見《祖堂集》卷十八）。"]', '["法身無作化身作，薄伽玄應諸病藥。","啀喍闻响擬嘷吠，焰水覓鱼癡老鹤。","（见《祖堂集》卷十八）。"]', '诗', 'shi', '', NULL, '偈 一 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52604b56-0e84-4618-82ab-cbdd798af09d', '偈 二', '偈 二', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["年滿七十七，老去是今日。","任性自浮沉（《五燈會元》卷九作「無常在今日。","日輪正當午」），兩手攀屈膝。","（見《景德傳燈錄》卷十一）。"]', '["年满七十七，老去是今日。","任性自浮沉（《五灯會元》卷九作「無常在今日。","日輪正當午」），兩手攀屈膝。","（见《景德傳灯錄》卷十一）。"]', '诗', 'shi', '', NULL, '偈 二 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9415252-d285-47b2-bc9f-72c0b79f6038', '偈 三', '偈 三', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["滔滔不持戒，兀兀不坐禪。","釅茶三兩椀，意在钁頭邊。"]', '["滔滔不持戒，兀兀不坐禪。","釅茶三兩椀，意在钁头邊。"]', '诗', 'shi', '', NULL, '偈 三 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e09f5b3-f0bd-4521-8da4-944ec8a3b1d6', '偈 四', '偈 四', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["一二二三子，平目復仰視。","兩口一無舌，即是吾宗旨。","（見《五燈會元》卷九）。"]', '["一二二三子，平目复仰視。","兩口一無舌，即是吾宗旨。","（见《五灯會元》卷九）。"]', '诗', 'shi', '', NULL, '偈 四 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ac296e-e7f2-48d8-99d6-df2a8bc6292e', '上洞山頌', '上洞山頌', '372c2775-251c-4feb-8faa-770b0244ae5c', '唐', '["何代隱荒丘，茅堂獨寢幽。","隨緣三事衲，頓覺萬緣休。","貌古因持戒，身貧爲少求。","吾師登鳥量，物外絕追遊。","（《天聖廣燈錄》卷十二）。"]', '["何代隐荒丘，茅堂独寢幽。","隨緣三事衲，頓覺万緣休。","貌古因持戒，身貧爲少求。","吾師登鸟量，物外絕追游。","（《天聖廣灯錄》卷十二）。"]', '诗', 'shi', '', NULL, '上洞山頌 慧寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02133961-7885-4f38-9bc3-191106862d09', '巖嵌綠玉', '巖嵌綠玉', 'b5c0b21e-517c-4c29-979d-a8177925fb64', '唐', '["天孫昔謫下天綠，霧鬢風鬟愛草木。","一朝騎鳳上丹霄，翠翹花鈿留空谷。","（見《明滇南詩略》卷首、民國五年周宗麟纂《大理縣志稿》卷三一）。"]', '["天孫昔謫下天綠，霧鬢风鬟愛草木。","一朝騎鳳上丹霄，翠翹花鈿留空谷。","（见《明滇南诗略》卷首、民国五年周宗麟纂《大理縣志稿》卷三一）。"]', '诗', 'shi', '', NULL, '巖嵌綠玉 楊奇鯤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ab6095-95a4-4306-958a-33efcec278ce', '酬通義劉相瞻', '酬通義劉相瞻', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["劉剛暗借飈輪便，叡武樓中似去年。","（見《苕溪漁隱叢話後集》卷三五引《蔡寬夫詩話》）。"]', '["劉剛暗借飈輪便，叡武楼中似去年。","（见《苕溪漁隐叢話後集》卷三五引《蔡寬夫诗話》）。"]', '诗', 'shi', '', NULL, '酬通義劉相瞻 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5634ece4-b555-4851-93ea-c68d71a0dba8', '二十八宿詩', '二十八宿诗', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["員明青{飢右爲凡}飯，光潤碧霞漿。","（《增修詩話總龜》卷二一引《零陵總記》）（按：《全唐詩》卷五五七錄二句，缺題，今重錄。","）。"]', '["員明青{飢右爲凡}飯，光潤碧霞漿。","（《增修诗話總龟》卷二一引《零陵總記》）（按：《全唐诗》卷五五七錄二句，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '二十八宿詩 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4a9d7d-2010-415c-83b5-27a636874dc6', '句', '句', 'b89959bf-be68-4b18-9121-4494f339bf79', '唐', '["思牽吳岫起，吟索剡雲開。","（貫休《禪月集》卷十《懷諸葛珏二首》「謬獨哭不錯」句自注引）（按：此則據《中華文史論叢》一九八七年第一期刊曹汛先生《淡然考》收入。","）。"]', '["思牽吳岫起，吟索剡云开。","（貫休《禪月集》卷十《懷諸葛珏二首》「謬独哭不錯」句自注引）（按：此則據《中华文史論叢》一九八七年第一期刊曹汛先生《淡然考》收入。","）。"]', '诗', 'shi', '', NULL, '句 謬獨一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb277246-54bc-469b-9a4b-d50552076c1f', '', '', '50ac646a-6cdf-404c-b8d1-2ed966120f91', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 麻衣禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0fbe15e-b32e-4b75-8367-56d82adfa333', '麻衣頌', '麻衣頌', '50ac646a-6cdf-404c-b8d1-2ed966120f91', '唐', '["勑下如來到翠微，佛前垂淚脫麻衣。","深山有寺不容住，四海無家何處歸？","（見《輿地紀勝》卷十九《池州》）（按：《補續高僧傳》卷二三有釋麻衣，五代之際往來澤潞間，發河圖之秘授陳摶。","似爲另一僧。","又《五燈會元》卷四收智真一偈，與此首僅數字不同，見本書卷三十。","）。"]', '["勑下如来到翠微，佛前垂泪脫麻衣。","深山有寺不容住，四海無家何处归？","（见《輿地紀勝》卷十九《池州》）（按：《補續高僧傳》卷二三有釋麻衣，五代之際往来澤潞间，發河圖之秘授陳摶。","似爲另一僧。","又《五灯會元》卷四收智真一偈，與此首僅數字不同，见本书卷三十。","）。"]', '诗', 'shi', '', NULL, '麻衣頌 麻衣禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de14ab66-956c-440c-95a7-bbb87d109aa1', '歌', '歌', '76ed4676-5f7b-4271-9fc0-c9f2d5dab2c5', '唐', '["山花頭上插，濁酒口中斟。","醉眼看醒漢，忙忙盡喪真。","（見《宛委別藏》本宋陳田夫《南嶽總勝集》卷上）（〖1〗《南嶽總勝集》云：「靈隱峰，下有伏虎巖。","舊記云：廣明末有野人張白醪辟穀，日飲渾酒未嘗醒。","時來往衡陽，晝臥石鼓洞，夜歸巖中，人數見之。","虎臥巖前，無敢近者。","或詢之來往，答云：『拂地來，拂地去。","』頭上插野花，每念謌云〖略〗。","後亦不知所往。","樵者見之，但破缽而已。","虎亦從此不來。","後五年，里人見之於成都。","」）。"]', '["山花头上插，濁酒口中斟。","醉眼看醒漢，忙忙尽喪真。","（见《宛委別藏》本宋陳田夫《南嶽總勝集》卷上）（〖1〗《南嶽總勝集》云：「靈隐峰，下有伏虎巖。","旧記云：廣明末有野人張白醪辟穀，日饮渾酒未嘗醒。","时来往衡陽，晝臥石鼓洞，夜归巖中，人數见之。","虎臥巖前，無敢近者。","或詢之来往，答云：『拂地来，拂地去。","』头上插野花，每念謌云〖略〗。","後亦不知所往。","樵者见之，但破缽而已。","虎亦從此不来。","後五年，里人见之於成都。","」）。"]', '诗', 'shi', '', NULL, '歌 張白醪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3007980a-9aef-4ba6-a6e3-90c30401545e', '水仙花（題擬） 一', '水仙花（題擬） 一', '946eb92d-0948-499b-8844-32f48584cf46', '唐', '["瑤池來宴老金家，醉倒風流萼綠華。","白玉斷笄金暈頂，幻成癡絕女兒花。","。"]', '["瑤池来宴老金家，醉倒风流萼綠华。","白玉斷笄金暈頂，幻成癡絕女兒花。","。"]', '诗', 'shi', '', NULL, '水仙花（題擬） 一 來鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f5c1303-41b9-4384-99a1-ee67bb372a0e', '水仙花（題擬） 二', '水仙花（題擬） 二', '946eb92d-0948-499b-8844-32f48584cf46', '唐', '["花盟平日不曾寒，六月曝根高處安。","待得秋殘親手種，萬姬圍繞雪中看。","（見《全芳備祖前集》卷二一「水仙花」門）。"]', '["花盟平日不曾寒，六月曝根高处安。","待得秋殘親手種，万姬圍繞雪中看。","（见《全芳備祖前集》卷二一「水仙花」门）。"]', '诗', 'shi', '', NULL, '水仙花（題擬） 二 來鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7cedd4-3250-4c34-9dfa-8137cf1275fa', '望故沔城', '望故沔城', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["江城遺壤在，艤棹望天涯。","古壁昭丘樹，殘紅夢苑花。","樓臺依水勢，雉堞帶山斜。","何事堪揮淚，鄉程北去賖。","（見民國十年刊《湖北通志》卷一○一《金石》九錄《鄂州雜詩碑》引）（按：《鄂州雜詩碑》分五層，錄謝朓及唐人詩三十九首，題「熙寧二年六月□日額立」。","不著書人姓名。","清時尚存黃鶴樓後斗姥閣西壁。","）。"]', '["江城遺壤在，艤棹望天涯。","古壁昭丘樹，殘紅梦苑花。","楼台依水勢，雉堞带山斜。","何事堪揮泪，乡程北去賖。","（见民国十年刊《湖北通志》卷一○一《金石》九錄《鄂州杂诗碑》引）（按：《鄂州杂诗碑》分五層，錄謝朓及唐人诗三十九首，題「熙寧二年六月□日額立」。","不著书人姓名。","清时尚存黄鹤楼後斗姥閣西壁。","）。"]', '诗', 'shi', '', NULL, '望故沔城 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85267c0a-ae6b-4604-99d4-500b7b27c9f7', '天門夕照', '天门夕照', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["落霞如綺絢晴空，坐看天門欲下舂。","十里孤峯層漢碧，數家殘照半江紅。","荒村市暝人歸牧，遠浦沙明水宿鴻。","回首長安何處是？嵯峨宮闕五雲中。"]', '["落霞如綺絢晴空，坐看天门欲下舂。","十里孤峯層漢碧，數家殘照半江紅。","荒村市暝人归牧，远浦沙明水宿鴻。","回首长安何处是？嵯峨宮闕五云中。"]', '诗', 'shi', '', NULL, '天門夕照 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea2b085-b864-4ed7-99ef-c20b7bff5eb2', '道院迎仙', '道院迎仙', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["百尺丹臺倚翠華，洞門迢遞隔煙霞。","雨中白鹿眠芳草，松下青牛臥落花。","幽谷月明浮紫氣，瑤池水暖伏丹沙。","拋書亦欲尋真去，安得相從一飯麻。"]', '["百尺丹台倚翠华，洞门迢遞隔煙霞。","雨中白鹿眠芳草，松下青牛臥落花。","幽谷月明浮紫氣，瑤池水暖伏丹沙。","拋书亦欲尋真去，安得相從一飯麻。"]', '诗', 'shi', '', NULL, '道院迎仙 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3b32aa-8c9f-4744-9a48-8776731b4b0e', '青城暮雨', '青城暮雨', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["草樹連雲雉堞平，蕭蕭風雨暗荒城。","流歸澗壑應無色，響入松杉覺有聲。","旅邸愁人寧復夢，書堂倦客若爲情。","芭蕉滴瀝傷心處，俯仰空懷一笑名。","（以上三首均見《古今圖書集成·職方典》卷一一四七《安陸府部》。","疑僞。","）。"]', '["草樹連云雉堞平，蕭蕭风雨暗荒城。","流归澗壑應無色，响入松杉覺有声。","旅邸愁人寧复梦，书堂倦客若爲情。","芭蕉滴瀝傷心处，俯仰空懷一笑名。","（以上三首均见《古今圖书集成·職方典》卷一一四七《安陸府部》。","疑僞。","）。"]', '诗', 'shi', '', NULL, '青城暮雨 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90446b75-2a6a-404e-a45d-6d7988d4b6f1', '[擬]送賀秘監歸會稽詩', '[擬]送賀秘監归會稽诗', '540ee676-e749-4d6c-8377-619cbec06f5d', '唐', '["詔許真人歸舊隱，爲言海上憶孤峰。","宸庭（《廣卓異記》作「旒」）暫別期千歲，野服飄然出九重。","華表尚迷丁令鶴，竹陂猶認葛仙龍。","自憐弱羽塵埃重，於此（《廣卓異記》作「雲外」）無由躡去蹤。","（見《會稽掇英總集》卷二，校以《廣卓異記》卷三。","《廣卓異記》題下署：「門下侍郎王鐸。","」）。"]', '["詔許真人归旧隐，爲言海上憶孤峰。","宸庭（《廣卓異記》作「旒」）暫別期千歲，野服飄然出九重。","华表尚迷丁令鹤，竹陂猶認葛仙龙。","自怜弱羽塵埃重，於此（《廣卓異記》作「云外」）無由躡去蹤。","（见《會稽掇英總集》卷二，校以《廣卓異記》卷三。","《廣卓異記》題下署：「门下侍郎王鐸。","」）。"]', '诗', 'shi', '', NULL, '[擬]送賀秘監歸會稽詩 王鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f979d7-afcf-463b-95f9-235eea4b6821', '曜日頌', '曜日頌', 'f7e0b049-c846-4ca9-899f-e6d803fdc044', '唐', '["當機直下現前真，認詩之徒未可親。","本色先陁如𢣾㦬，巖頭松檜鎮長新。","（見《祖堂集》卷七）。"]', '["當機直下現前真，認诗之徒未可親。","本色先陁如𢣾㦬，巖头松檜鎮长新。","（见《祖堂集》卷七）。"]', '诗', 'shi', '', NULL, '曜日頌 全豁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('956ffe45-ab76-4ff7-90ad-9c67b54024fa', '依韻繼和王霞卿詩（題擬）', '依韻繼和王霞卿诗（題擬）', '41ab7254-cf37-4798-91c1-c2a9839440a5', '唐', '["題詩仙子此曾遊，應是尋春別鳳樓。","賴得從來未相識，免交錦帳對銀鉤。","（見王銍《侍兒小名錄補》引《女仙圖》）。"]', '["題诗仙子此曾游，應是尋春別鳳楼。","賴得從来未相識，免交錦帳对銀鉤。","（见王銍《侍兒小名錄補》引《女仙圖》）。"]', '诗', 'shi', '', NULL, '依韻繼和王霞卿詩（題擬） 鄭殷彝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd71966-7311-48ff-aaa2-f51ed966a6bb', '擊甌賦附歌', '擊甌賦附歌', 'bb3aa3f2-888f-4b5a-97da-0104e38f8deb', '唐', '["江風起兮江樓春，千里萬里兮愁殺人。","樓前芳草兮關山道，江上孤帆兮楊柳津。","是何貺（《全唐文》作「況」）我兮擊拊，眷我兮慇懃。","（見宋史繩祖《學齋佔畢》卷二、《全唐文》卷八二九）（按：史繩祖云此篇「巴州郡樓尚有碑刻，曾祖作巴倅時，曾有墨本藏之家。","」擬題爲《擊甌賦》。","杜文瀾《古謠諺》卷九二則擬題爲《遊巴州東樓歌》。","）。"]', '["江风起兮江楼春，千里万里兮愁殺人。","楼前芳草兮关山道，江上孤帆兮楊柳津。","是何貺（《全唐文》作「況」）我兮擊拊，眷我兮慇懃。","（见宋史繩祖《学斋佔畢》卷二、《全唐文》卷八二九）（按：史繩祖云此篇「巴州郡楼尚有碑刻，曾祖作巴倅时，曾有墨本藏之家。","」擬題爲《擊甌賦》。","杜文瀾《古謠諺》卷九二則擬題爲《游巴州东楼歌》。","）。"]', '诗', 'shi', '', NULL, '擊甌賦附歌 張曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd3902f-e5f2-428b-9714-7f849fce91ea', '途中聞蟬', '途中闻蟬', 'bb3aa3f2-888f-4b5a-97da-0104e38f8deb', '唐', '["每歲聽蟬處，那將此際同。","孤村寒色裏，野店夕陽中。","（見《能改齋漫錄》卷八。","爲原詩的前四句。","）。"]', '["每歲听蟬处，那將此際同。","孤村寒色裏，野店夕陽中。","（见《能改斋漫錄》卷八。","爲原诗的前四句。","）。"]', '诗', 'shi', '', NULL, '途中聞蟬 張曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f08951b-f88b-4154-aeb0-b0d5a1ade1d5', '', '', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b69d2a-be87-4c14-b0ff-be080a63df27', '識黃芽歌', '識黄芽歌', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["乾坤感合始成形，造化元居北戶生。","日月循環魂魄滿，陰陽交媾龍虎成。","分明本自從金長，誰悟偏能與水幷。","無限徧於塵世裏，時人日用不知名。"]', '["乾坤感合始成形，造化元居北戶生。","日月循环魂魄满，陰陽交媾龙虎成。","分明本自從金长，誰悟偏能與水幷。","無限徧於塵世裏，时人日用不知名。"]', '诗', 'shi', '', NULL, '識黃芽歌 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bbbdce-11d2-4039-8dc9-75417e30e08f', '識鉛汞歌 一', '識鉛汞歌 一', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["世事忙忙無了程，百年如夢瞥然榮。","不知道有雲衢客，剛自爭邀塵裏名。","欲駐流年泛太清，須知靈藥必長生。","純燒天地陰陽髓，全鍊乾坤日月精。","嫁娶陰陽成匹配，對持龍虎自相吞。","伏得離宮赤帝精，感他坎戶白龍液。","黃芽祇此是根源，自外徒勞虛費力。","若不曾逢真至人，如何得到幽玄術？","火候須教經九轉，丹成直待周千日。","鑪上煙生五彩光，鼎中藥奮弘紅色。","刀圭一粒沖天漢，逍遙頓躡三清畔。","駕鶴乘龍役鬼神，反笑桑田數迴換。","自此長居碧落宮，永共羣仙醉金殿。"]', '["世事忙忙無了程，百年如梦瞥然榮。","不知道有云衢客，剛自爭邀塵裏名。","欲駐流年泛太清，須知靈藥必长生。","純燒天地陰陽髓，全鍊乾坤日月精。","嫁娶陰陽成匹配，对持龙虎自相吞。","伏得離宮赤帝精，感他坎戶白龙液。","黄芽祇此是根源，自外徒勞虛費力。","若不曾逢真至人，如何得到幽玄術？","火候須教經九轉，丹成直待周千日。","鑪上煙生五彩光，鼎中藥奮弘紅色。","刀圭一粒沖天漢，逍遙頓躡三清畔。","駕鹤乘龙役鬼神，反笑桑田數迴換。","自此长居碧落宮，永共羣仙醉金殿。"]', '诗', 'shi', '', NULL, '識鉛汞歌 一 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f655c871-587c-44c5-83e4-b589c66e5917', '識鉛汞歌 二', '識鉛汞歌 二', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["日華兼月魄，戊己本爲君。","金木東西併，陰陽上下分。","減添依次序，進退合先文。","十月懷胎滿，翩翩泛白雲。"]', '["日华兼月魄，戊己本爲君。","金木东西併，陰陽上下分。","減添依次序，進退合先文。","十月懷胎满，翩翩泛白云。"]', '诗', 'shi', '', NULL, '識鉛汞歌 二 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967666ce-2030-465f-9a44-256f007fd893', '師訪', '師訪', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["共擬丹霄萬古存，出塵心事苦曾論。","於今莫倦頻相訪，已似孤雲鶴到門。"]', '["共擬丹霄万古存，出塵心事苦曾論。","於今莫倦頻相訪，已似孤云鹤到门。"]', '诗', 'shi', '', NULL, '師訪 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7587557-5d7d-407b-b940-fbe23c181fd4', '師勉', '師勉', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["早向忙中認取閑，休將心力役機關。","花依時節重開得，水向東流定不還。","春色潛偷青鬢髮，風光暗換少年顏。","須知世事堪悲歎，盡在莊周一夢間。"]', '["早向忙中認取闲，休將心力役機关。","花依时節重开得，水向东流定不還。","春色潛偷青鬢髮，风光暗換少年顏。","須知世事堪悲歎，尽在莊周一梦间。"]', '诗', 'shi', '', NULL, '師勉 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc343e09-28f3-40bb-b199-c35a255f21be', '師貽', '師貽', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["我今一一訣真門，古聖皆因此出塵。","昨日蓬萊仙會裏，長生籍上又添君。"]', '["我今一一訣真门，古聖皆因此出塵。","昨日蓬萊仙會裏，长生籍上又添君。"]', '诗', 'shi', '', NULL, '師貽 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915c4cb3-d37c-47fd-a1f6-49fb236565ea', '師誨而餞之', '師誨而餞之', '858d4483-b777-4623-92b8-d4847f8039cf', '唐', '["松柏堅且貞，澗水流復清。","勿久塵寰間，是非污耳聆。","（以上均見《正統道藏》本《大還丹金虎白龍論》。","末有附跋，錄如次。","）（〖1〗跋云：「時光啓二年冬首中旬有七，橫峰先生永陽子杜希遁，字忘機，多事之秋，避禍汶郊，每抵鄽中，祇接大隱南陽公。","公頗奉道，耽玄悟真，棲心閑雅，若夫發跡揚名，俟之知己。","夫爲交者，有名焉，有利焉，余與公交，非名與利，每一接，未嘗不話道永日，除玄之又玄外，餘無所云。","故書先師藥訣相贈，切希千萬保惜，勿傳下士。","大凡方外之事，豈使常人知之？","常人知之，則自遭譴謫。","仙師曰：欽承者紀名於玄籙，泄慢者責身爲下鬼。","又曰：殃慶逮於九祖，昇沉止於一形。","今以青山白雲爲誓，勿負誓言，千萬千萬。","」）。"]', '["松柏堅且貞，澗水流复清。","勿久塵寰间，是非污耳聆。","（以上均见《正統道藏》本《大還丹金虎白龙論》。","末有附跋，錄如次。","）（〖1〗跋云：「时光啓二年冬首中旬有七，橫峰先生永陽子杜希遁，字忘機，多事之秋，避禍汶郊，每抵鄽中，祇接大隐南陽公。","公頗奉道，耽玄悟真，棲心闲雅，若夫發跡揚名，俟之知己。","夫爲交者，有名焉，有利焉，余與公交，非名與利，每一接，未嘗不話道永日，除玄之又玄外，餘無所云。","故书先師藥訣相贈，切希千万保惜，勿傳下士。","大凡方外之事，豈使常人知之？","常人知之，則自遭譴謫。","仙師曰：欽承者紀名於玄籙，泄慢者責身爲下鬼。","又曰：殃慶逮於九祖，昇沉止於一形。","今以青山白云爲誓，勿負誓言，千万千万。","」）。"]', '诗', 'shi', '', NULL, '師誨而餞之 還陽子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4001afd5-7788-465b-bd48-cc9949519e5c', '與崔渥登眺江亭賦長韻（題擬）', '與崔渥登眺江亭賦长韻（題擬）', '3a24d422-d575-43f8-9448-6cef5dc15cbb', '唐', '["檻外征帆次第行，漁歌偏唱《竹枝》聲。","荷翻水面真珠碎，柳颺灣頭綠綫輕。","巒隱九疑忘去處，淚經千古轉分明。","寥寥日暮雲空淡，應爲嚴妝廟貌清。","（《燈下閑談》卷下《湘妃神會》）。"]', '["檻外征帆次第行，漁歌偏唱《竹枝》声。","荷翻水面真珠碎，柳颺灣头綠綫轻。","巒隐九疑忘去处，泪經千古轉分明。","寥寥日暮云空淡，應爲嚴妝廟貌清。","（《灯下闲談》卷下《湘妃神會》）。"]', '诗', 'shi', '', NULL, '與崔渥登眺江亭賦長韻（題擬） 濮陽人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ecdc2d-6194-492f-9f56-a3b2f7e99227', '和濮陽人登眺江亭賦長韻（題擬）', '和濮陽人登眺江亭賦长韻（題擬）', '77011fc4-6270-48e1-bc8e-4f8403dc5e13', '唐', '["閑步江亭駐客行，殿臺高敞杜鵑聲。","風生屈宋魂應散，雨過黃娥恨亦輕。","春筍亂穿階蘚缺，晚霞旁襯野花明。","翠華不返蒲關去，鴛鷺數行松韻清。","（同前）。"]', '["闲步江亭駐客行，殿台高敞杜鵑声。","风生屈宋魂應散，雨過黄娥恨亦轻。","春筍亂穿階蘚缺，晚霞旁襯野花明。","翠华不返蒲关去，鴛鷺數行松韻清。","（同前）。"]', '诗', 'shi', '', NULL, '和濮陽人登眺江亭賦長韻（題擬） 崔渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83037033-2169-4eae-8597-f1abee208d39', '題三陵冢', '題三陵冢', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["春到三陵淑氣和，雪初消處翠嵯峨。","梅花未知開多少，策杖攜壺試一過。","（《記纂淵海》卷十七）。"]', '["春到三陵淑氣和，雪初消处翠嵯峨。","梅花未知开多少，策杖携壺試一過。","（《記纂淵海》卷十七）。"]', '诗', 'shi', '', NULL, '題三陵冢 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7280da3a-152c-4d50-ad80-572f320479f4', '玉川偶興', '玉川偶兴', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["玉川鶴避盧仝啜，盤谷猿驚李愿歸。","興盡攜筇一迴首，西風拂拂白雲飛。","（見乾隆二十四年刊蕭應植纂《濟源縣志》卷十六。","此詩疑僞。","）。"]', '["玉川鹤避盧仝啜，盤谷猿驚李愿归。","兴尽携筇一迴首，西风拂拂白云飞。","（见乾隆二十四年刊蕭應植纂《濟源縣志》卷十六。","此诗疑僞。","）。"]', '诗', 'shi', '', NULL, '玉川偶興 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b00d408-76f6-493c-84e0-e0625ac1b7cc', '夏日（題擬）', '夏日（題擬）', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["汗浹衣巾詩癖減，茶盈杯椀睡魔降。","（見《錦繡萬花谷後集》卷三「夏」門）。"]', '["汗浹衣巾诗癖減，茶盈杯椀睡魔降。","（见《錦繡万花谷後集》卷三「夏」门）。"]', '诗', 'shi', '', NULL, '夏日（題擬） 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f925860-5227-4e69-8eb6-d9d02f148a40', '宿雲門寺', '宿云门寺', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["入松穿竹路難分，藉地連巖總是雲。","欲問老僧多少事，亂泉相聒不相聞。","（見《會稽掇英總集》卷六）。"]', '["入松穿竹路难分，藉地連巖總是云。","欲问老僧多少事，亂泉相聒不相闻。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '宿雲門寺 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed6c962-8960-44f2-9152-87bf9b23bc3d', '句', '句', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["窗前遠岫懸生碧，簾外殘霞掛熟紅。","（《太平廣記》卷二六一）。"]', '["窗前远岫懸生碧，簾外殘霞掛熟紅。","（《太平廣記》卷二六一）。"]', '诗', 'shi', '', NULL, '句 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06794f1-66a3-4936-ba51-e03b10134dd1', '答楚兒', '答楚兒', 'e4f59dd7-c6c4-4382-aa27-6dc2cba45e97', '唐', '["大開眼界莫言冤，畢世甘他（《說郛》本作「必若遭伊」）也是緣。","無計不煩乾（《說郛》本作「輕」）偃蹇，有門須是疾連拳。","據論當道加嚴箠，便合披緇念《法蓮》。","如此興情殊不（《說郛》本作「都未」）減，始知昨日是蒲鞭。","（見孫棨《北里志》）。"]', '["大开眼界莫言冤，畢世甘他（《说郛》本作「必若遭伊」）也是緣。","無計不煩乾（《说郛》本作「轻」）偃蹇，有门須是疾連拳。","據論當道加嚴箠，便合披緇念《法蓮》。","如此兴情殊不（《说郛》本作「都未」）減，始知昨日是蒲鞭。","（见孫棨《北里志》）。"]', '诗', 'shi', '', NULL, '答楚兒 鄭昌圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d5227e-dd32-4eee-83b7-2d669bfb88b8', '再遊雲門', '再游云门', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["嶺頭雲向窗中起，砌下泉從石上來。","僧老終無出山意，巖猿澗鳥莫相猜。","（見《會稽掇英總集》卷六）。"]', '["嶺头云向窗中起，砌下泉從石上来。","僧老終無出山意，巖猿澗鸟莫相猜。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '再遊雲門 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11794640-12d9-4f8a-aea5-9754de4276e5', '和征婦寄寒衣', '和征婦寄寒衣', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["西風吹雁到東吳，自整寒衣欲寄夫。","一剪一鍼腸一斷，不知夫亦斷腸無。","（見清王魏勝《安州詩錄》卷一。","此詩承張靖龍同志錄示）。"]', '["西风吹雁到东吳，自整寒衣欲寄夫。","一剪一鍼腸一斷，不知夫亦斷腸無。","（见清王魏勝《安州诗錄》卷一。","此诗承張靖龙同志錄示）。"]', '诗', 'shi', '', NULL, '和征婦寄寒衣 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17cd55dd-4c09-4e6e-a364-14721fcf8880', '遊雪竇寺', '游雪竇寺', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["絕頂空王宅，香風萍薜蘿。","地高春色晚，天近日光多。","流水隨寒玉，遙峰（《四明山志》作「岑」）擁翠波。","前山有丹鳳，雲外一聲過。","（見《古今圖書集成·山川典》卷一一○、雍正十一年刊曹秉仁纂《寧波府志》卷三五。","）（〖1〗張靖龍云：見黃宗羲《四明山志》卷七《詩括》。","黃宗羲按：「有爲《雪竇志》者載此詩，注其爵里曰『元和狀元』。","不知方干唐末不第，死後得賜一官以慰冥魂。","余戲爲一絕云：『元英詩句不銷磨，十舉終難占一科。","死後奏名何足慰，不如雪竇莽禪和』」。","此詩又見康熙《雪竇寺志》卷九下、雍正《寧波府志》卷三五、清陳之網《四明古跡》卷二。","雪竇寺在奉化溪口附近的雪竇山，爲天下禪宗十剎之一。","寺本唐會昌以前創，名瀑布，咸通八年改名雪竇。","）。"]', '["絕頂空王宅，香风萍薜蘿。","地高春色晚，天近日光多。","流水隨寒玉，遙峰（《四明山志》作「岑」）擁翠波。","前山有丹鳳，云外一声過。","（见《古今圖书集成·山川典》卷一一○、雍正十一年刊曹秉仁纂《寧波府志》卷三五。","）（〖1〗張靖龙云：见黄宗羲《四明山志》卷七《诗括》。","黄宗羲按：「有爲《雪竇志》者載此诗，注其爵里曰『元和狀元』。","不知方干唐末不第，死後得賜一官以慰冥魂。","余戲爲一絕云：『元英诗句不銷磨，十舉終难占一科。","死後奏名何足慰，不如雪竇莽禪和』」。","此诗又见康熙《雪竇寺志》卷九下、雍正《寧波府志》卷三五、清陳之網《四明古跡》卷二。","雪竇寺在奉化溪口附近的雪竇山，爲天下禪宗十剎之一。","寺本唐會昌以前創，名瀑布，咸通八年改名雪竇。","）。"]', '诗', 'shi', '', NULL, '遊雪竇寺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b91ef7-4f01-4f32-8bb6-a08782610814', '遊岳林寺', '游岳林寺', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["投閒猶自喜，古剎（《岳林寺志》作「策」）剡東尋。","祗樹隨僧老，龍溪遶岸深。","樓高春色晚，天近日光陰。","共笑家聲舊，何時解盍簪。","（見光緒三十四年刊張美翊纂《奉化縣志》卷四。","）（〖1〗張靖龍云：見清戴明琮《明州岳林寺志》卷五《詩賦》。","岳林寺在奉化縣城東北，梁大同二年創于龍溪西，名崇福院。","李紳書額。","會昌中毀。","大中二年閑曠禪師徙建溪東，改岳林寺。","）。"]', '["投閒猶自喜，古剎（《岳林寺志》作「策」）剡东尋。","祗樹隨僧老，龙溪遶岸深。","楼高春色晚，天近日光陰。","共笑家声旧，何时解盍簪。","（见光緒三十四年刊張美翊纂《奉化縣志》卷四。","）（〖1〗張靖龙云：见清戴明琮《明州岳林寺志》卷五《诗賦》。","岳林寺在奉化縣城东北，梁大同二年創于龙溪西，名崇福院。","李紳书額。","會昌中毀。","大中二年闲曠禪師徙建溪东，改岳林寺。","）。"]', '诗', 'shi', '', NULL, '遊岳林寺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6de63af0-ca9e-472d-aca7-188126bb7946', '駐紫霞觀', '駐紫霞观', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["易覺春光老，難消夏晝長。","問囚傷道氣，嚼句療饑腸。","殿古苔痕澀，壇高松檜涼。","黃冠誰可語，試與辯亡羊。","（見民國二十五年刊陳善同等纂《重修信陽縣志》卷三十）。"]', '["易覺春光老，难消夏晝长。","问囚傷道氣，嚼句療饑腸。","殿古苔痕澀，壇高松檜涼。","黄冠誰可語，試與辯亡羊。","（见民国二十五年刊陳善同等纂《重修信陽縣志》卷三十）。"]', '诗', 'shi', '', NULL, '駐紫霞觀 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91d79dd-16eb-43ef-a98a-41a4db3ab7e4', '戲吳傑令（題擬）', '戲吳傑令（題擬）', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["一盞酒，一捻鹽，止見門前懸箔，何處眼上垂簾。","（見《唐語林》卷七）。"]', '["一盞酒，一捻鹽，止见门前懸箔，何处眼上垂簾。","（见《唐語林》卷七）。"]', '诗', 'shi', '', NULL, '戲吳傑令（題擬） 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdbc6252-95d4-4879-bb7d-041befb8e7a4', '還方干令（題擬）', '還方干令（題擬）', '547f3c1d-9a7a-4b9c-9ad8-a4535d0b971c', '唐', '["一盞酒，一臠鮓，止見半臂著襴，何處口唇開袴。","（同前）（〖1〗《唐語林》云：「方干貌陋唇缺，味嗜魚鮓，性多譏戲。","蕭中丞典杭，軍倅吳傑，患眸子赤。","會宴於城樓飲，促召傑。","傑至，目爲風掠，不堪其苦。","憲笑命近座女伶，裂紅巾方寸帖臉，以障風掠。","時在席，因爲令戲傑曰〖略〗。","傑還之曰〖略〗。","一席絕倒。","爾後人多目干爲『方開袴』」。","按：《唐摭言》卷十三載方干與龍丘李主簿互嘲酒令，均爲六言四句，內容相近，爲同一嘲謔之不同傳本。","六言二首已收入《全唐詩》卷八七九。","）。"]', '["一盞酒，一臠鮓，止见半臂著襴，何处口唇开袴。","（同前）（〖1〗《唐語林》云：「方干貌陋唇缺，味嗜鱼鮓，性多譏戲。","蕭中丞典杭，軍倅吳傑，患眸子赤。","會宴於城楼饮，促召傑。","傑至，目爲风掠，不堪其苦。","憲笑命近座女伶，裂紅巾方寸帖臉，以障风掠。","时在席，因爲令戲傑曰〖略〗。","傑還之曰〖略〗。","一席絕倒。","爾後人多目干爲『方开袴』」。","按：《唐摭言》卷十三載方干與龙丘李主簿互嘲酒令，均爲六言四句，內容相近，爲同一嘲謔之不同傳本。","六言二首已收入《全唐诗》卷八七九。","）。"]', '诗', 'shi', '', NULL, '還方干令（題擬） 吳傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d74db80-7cb6-4ac0-bd87-8bba688067cd', '偈', '偈', 'c24f7da3-db34-4dda-b305-7c5893362829', '唐', '["光明寂照遍恒（一作「河」）沙，凡聖含靈共一（一作「我」）家。","一念不生全體現，六情（一作「根」）纔動被雲遮。","遣除凡拙（一作「破除煩惱」）重增病，趣（一作「趨」）向真如亦是邪。","任逐境緣（一作「隨順世緣」）無罣[碍]（得），真如凡聖是空花（一作「涅槃生死等空花」）。","（見《祖堂集》卷六，據《五燈會元》卷六，鄭方坤《全閩詩話》卷一校改。","）。"]', '["光明寂照遍恒（一作「河」）沙，凡聖含靈共一（一作「我」）家。","一念不生全體現，六情（一作「根」）纔动被云遮。","遣除凡拙（一作「破除煩惱」）重增病，趣（一作「趨」）向真如亦是邪。","任逐境緣（一作「隨順世緣」）無罣[碍]（得），真如凡聖是空花（一作「涅槃生死等空花」）。","（见《祖堂集》卷六，據《五灯會元》卷六，鄭方坤《全閩诗話》卷一校改。","）。"]', '诗', 'shi', '', NULL, '偈 張拙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0470be3f-fd1b-46d2-8a8c-cdaaabaafedd', '頌 一', '頌 一', 'a9a32e4a-d8c4-4ec5-8874-704908c9de8e', '唐', '["心靜愁難入，無憂禍不侵。","道高龍虎伏，德重鬼神欽。","（見《祖堂集》卷九）。"]', '["心静愁难入，無憂禍不侵。","道高龙虎伏，德重鬼神欽。","（见《祖堂集》卷九）。"]', '诗', 'shi', '', NULL, '頌 一 慧光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696e0664-22c2-4df6-9243-66606dc43665', '頌 二', '頌 二', 'a9a32e4a-d8c4-4ec5-8874-704908c9de8e', '唐', '["修多妙用勿（《五燈會元》作「好句枉」）功夫，返本還源是大愚。","古（《五燈會元》作「祖」）佛不從修證得，直饒玄妙（《五燈會元》作「縱行玄路」）也崎嶇。","（《祖堂集》卷九、《五燈會元》卷六）。"]', '["修多妙用勿（《五灯會元》作「好句枉」）功夫，返本還源是大愚。","古（《五灯會元》作「祖」）佛不從修證得，直饒玄妙（《五灯會元》作「縱行玄路」）也崎嶇。","（《祖堂集》卷九、《五灯會元》卷六）。"]', '诗', 'shi', '', NULL, '頌 二 慧光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d8a3607-a6d8-4fe7-9fe3-498ea5e9c1b2', '答僧問（題擬） 一', '答僧问（題擬） 一', '5a65034d-6086-4204-b1a5-e4cdd7aee3fc', '唐', '["寶蓋高高掛，其中事若何？","誰師言下旨，一句不消多。","（僧問）。"]', '["寶蓋高高掛，其中事若何？","誰師言下旨，一句不消多。","（僧问）。"]', '诗', 'shi', '', NULL, '答僧問（題擬） 一 約禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c39ea83d-bfe5-4476-8aca-9fc5f8512773', '答僧問（題擬） 二', '答僧问（題擬） 二', '5a65034d-6086-4204-b1a5-e4cdd7aee3fc', '唐', '["寶蓋掛空中，有路不曾通。","儻求言下旨，便是有西東。","（師答。","《景德傳燈錄》卷十六、《五燈會元》卷六）。"]', '["寶蓋掛空中，有路不曾通。","儻求言下旨，便是有西东。","（師答。","《景德傳灯錄》卷十六、《五灯會元》卷六）。"]', '诗', 'shi', '', NULL, '答僧問（題擬） 二 約禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582e93ad-fba7-4929-bb9e-153d364494ea', '還丹口訣', '還丹口訣', '8f1bc609-95e1-4466-bb0a-e4b164e30e7f', '唐', '["置天立地混沌分，造化含花處處焚。","一陰一陽乃成道，秋石蒼蒼浪子孫。","玄武朱雀明前路，湧泉真汞守乾坤。","鼎鼎製鉛成寶物，姹女藏頭不肯出。","十二葫中紫河車，四十二氣烈仙窟。","顏如玉，貌如霜，棗葉雄朱修修畢。","手摶日月入爐中，炎炎赫赫魂不失。","非濟凡間飢凍疾，不如學道急須出。","水煑冥冥白虎身，獸鑪上下兩莫測。","大象不遊於兔穴，大悟不拘於小節，迷者心差皆總失。","非傳下界盲瞽人，滅族亡身不可出。","六謌六謌，爾翺已去往蓬萊，白日霞仙，今古密鶴，叫前程，洞庭湖，禮我聖祖爲留術。","去無聲，甘如蜜，一七二七七萬畢。","開鑪忽見火一團，光彩炎炎赫赫奕。","雖濟凡間飢凍疾，不如訪道棲金室。","（《大還丹照鑑》）（按：《十國春秋》卷四七：「爾朱先生，成都人也。","字通微，亦號歸元子。","唐僖宗時隱鍊於金雞關下石室。","居久之，有異人與藥一丸，且戒曰：『子見浮石而服之，仙道成矣。","』自是遇石必投之水間，視其浮沉。","人皆笑以爲狂。","一日遊峽上，有叟艤舟相待，叩其姓氏，對曰：『涪州石姓也。","』遂豁然悟曰：『異人浮石之言，斯其應乎？","』因服藥輕舉而去。","時天復末年也。","先生有《還丹歌》傳於蜀中。","」應即此人。","此詩應即《還丹歌》。","《大還丹照鑑》作者爲後蜀廣政間人，故得以收錄之。","）。"]', '["置天立地混沌分，造化含花处处焚。","一陰一陽乃成道，秋石蒼蒼浪子孫。","玄武朱雀明前路，湧泉真汞守乾坤。","鼎鼎製鉛成寶物，姹女藏头不肯出。","十二葫中紫河车，四十二氣烈仙窟。","顏如玉，貌如霜，棗葉雄朱修修畢。","手摶日月入爐中，炎炎赫赫魂不失。","非濟凡间飢凍疾，不如学道急須出。","水煑冥冥白虎身，獸鑪上下兩莫測。","大象不游於兔穴，大悟不拘於小節，迷者心差皆總失。","非傳下界盲瞽人，滅族亡身不可出。","六謌六謌，爾翺已去往蓬萊，白日霞仙，今古密鹤，叫前程，洞庭湖，禮我聖祖爲留術。","去無声，甘如蜜，一七二七七万畢。","开鑪忽见火一團，光彩炎炎赫赫奕。","雖濟凡间飢凍疾，不如訪道棲金室。","（《大還丹照鑑》）（按：《十国春秋》卷四七：「爾朱先生，成都人也。","字通微，亦號归元子。","唐僖宗时隐鍊於金雞关下石室。","居久之，有異人與藥一丸，且戒曰：『子见浮石而服之，仙道成矣。","』自是遇石必投之水间，視其浮沉。","人皆笑以爲狂。","一日游峽上，有叟艤舟相待，叩其姓氏，对曰：『涪州石姓也。","』遂豁然悟曰：『異人浮石之言，斯其應乎？","』因服藥轻舉而去。","时天复末年也。","先生有《還丹歌》傳於蜀中。","」應即此人。","此诗應即《還丹歌》。","《大還丹照鑑》作者爲後蜀廣政间人，故得以收錄之。","）。"]', '诗', 'shi', '', NULL, '還丹口訣 爾朱翺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d170aa-0a54-4cd1-ab41-8db6aa1cbd2a', '送崔致遠西遊將還（題擬）', '送崔致远西游將還（題擬）', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["我聞海上三金鰲，金鰲頭戴山高高。","山之上兮，珠宮貝闕黃金殿；山之下兮，千里萬里之洪濤。","傍邊一點鷄林碧，鰲山孕秀生奇特。","十二乘船渡海來，文章感動中華國。","十八橫行戰詞苑，一箭射破金門策。","（《三國史記》卷四六。","《大正藏》第四九冊《新刊賢首碑傳正誤》引「文章感動中華國」一句。","）（按：《三國史記》引此詩爲節引。","）。"]', '["我闻海上三金鰲，金鰲头戴山高高。","山之上兮，珠宮貝闕黄金殿；山之下兮，千里万里之洪濤。","傍邊一点鷄林碧，鰲山孕秀生奇特。","十二乘船渡海来，文章感动中华国。","十八橫行戰词苑，一箭射破金门策。","（《三国史記》卷四六。","《大正藏》第四九冊《新刊賢首碑傳正誤》引「文章感动中华国」一句。","）（按：《三国史記》引此诗爲節引。","）。"]', '诗', 'shi', '', NULL, '送崔致遠西遊將還（題擬） 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5988e299-9cde-4811-b0c9-795b3f0696a4', '孤雲篇', '孤云篇', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["因風離海上，伴月到人間。","徘徊不可住，漠漠又東還。","（高麗李仁老《破閑集》引，轉引自韋旭升《朝鮮文學史》）（按：《破閑集》云：「文昌公崔致遠字孤雲，以賓貢入中朝擢第，游高駢幕府。","時天下雲擾，簡檄皆出其手。","及還鄉，同年顧雲賦《孤雲篇》以送之云〖詩略〗。","」疑與前《三國史記》所錄者爲同一首詩中之斷片。","）。"]', '["因风離海上，伴月到人间。","徘徊不可住，漠漠又东還。","（高丽李仁老《破闲集》引，轉引自韋旭升《朝鲜文学史》）（按：《破闲集》云：「文昌公崔致远字孤云，以賓貢入中朝擢第，游高駢幕府。","时天下云擾，簡檄皆出其手。","及還乡，同年顧云賦《孤云篇》以送之云〖诗略〗。","」疑與前《三国史記》所錄者爲同一首诗中之斷片。","）。"]', '诗', 'shi', '', NULL, '孤雲篇 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e28c9c3-bde7-4a60-9465-1c8aab644dac', '', '', '57a0bc80-8a2b-4028-b4cc-e5a1b45dc0c9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 劉崇龜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f0163d-4ddf-45d9-a407-aefff2fbed58', '伏蒙僕射相公許崇龜攀和杜鵑花詩勒諸巖石伏以崇龜本乏成章矧恐絕唱徒荷發揚之賜終流唐突之愛將厠庭覲光叨榮被謹次前韻兼寄呈桂州僕射', '伏蒙僕射相公許崇龟攀和杜鵑花诗勒諸巖石伏以崇龟本乏成章矧恐絕唱徒荷發揚之賜終流唐突之愛將厠庭覲光叨榮被謹次前韻兼寄呈桂州僕射', '57a0bc80-8a2b-4028-b4cc-e5a1b45dc0c9', '唐', '["碧幢紅苑合洪鈞，桂樹林前信有春。","莫戀花時好風景，磻溪不是釣魚人。","（見桂林市文物管理委員會編《桂林石刻》每一冊《唐張濬劉崇龜杜鵑花唱和詩》）（按：張、劉二人詩刻摩崖在龍隱洞，高一尺五寸，寬二尺四寸，真書徑八分。","劉詩下署銜曰：「前嶺南東道節度使檢校右僕射劉崇龜上。","」末題記一行云：「乾寧元年三月廿七日將仕郎前守監察御史張巖書。","」劉詩已收入《全唐詩》卷七一五，題僅作《寄桂帥》，有五字誤，今重錄之。","）。"]', '["碧幢紅苑合洪鈞，桂樹林前信有春。","莫戀花时好风景，磻溪不是釣鱼人。","（见桂林市文物管理委員會編《桂林石刻》每一冊《唐張濬劉崇龟杜鵑花唱和诗》）（按：張、劉二人诗刻摩崖在龙隐洞，高一尺五寸，寬二尺四寸，真书徑八分。","劉诗下署銜曰：「前嶺南东道節度使檢校右僕射劉崇龟上。","」末題記一行云：「乾寧元年三月廿七日將仕郎前守監察御史張巖书。","」劉诗已收入《全唐诗》卷七一五，題僅作《寄桂帥》，有五字誤，今重錄之。","）。"]', '诗', 'shi', '', NULL, '伏蒙僕射相公許崇龜攀和杜鵑花詩勒諸巖石伏以崇龜本乏成章矧恐絕唱徒荷發揚之賜終流唐突之愛將厠庭覲光叨榮被謹次前韻兼寄呈桂州僕射 劉崇龜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c77d6d2-8a23-4840-a4a5-e0dd64179696', '句', '句', '37178ffa-7ac7-432f-8f44-c502e389c4b5', '唐', '["鰲頭浪蹙掀天白，鯨目光燒半海紅。","（見宋吳坰《五總志》）（按：《全唐詩》卷八五一據《增修詩話總龜》卷八收「唐末蜀沙門」爾鳥逸句二，與此二句全同，惟前後互乙。","今考僧爾鳥未見唐人記載。","「鸞」字離作「、鳥」二字，與「爾鳥」二字字形極相近。","可知「僧爾鳥」必爲「僧鸞」之形訛，非另有其人。","）。"]', '["鰲头浪蹙掀天白，鯨目光燒半海紅。","（见宋吳坰《五總志》）（按：《全唐诗》卷八五一據《增修诗話總龟》卷八收「唐末蜀沙门」爾鸟逸句二，與此二句全同，惟前後互乙。","今考僧爾鸟未见唐人記載。","「鸾」字離作「、鸟」二字，與「爾鸟」二字字形極相近。","可知「僧爾鸟」必爲「僧鸾」之形訛，非另有其人。","）。"]', '诗', 'shi', '', NULL, '句 僧鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6d2e6c-5472-4fc6-a873-f739099bcc4f', '', '', '08d20cb5-470a-4428-9146-36a49012cd0b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 文炬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38f6740-6eaf-4b16-8eb8-9f6ca7b836be', '偈', '偈', '08d20cb5-470a-4428-9146-36a49012cd0b', '唐', '["小月走爍爍，千落及萬落。","處處鳳離穴，家家種葵藿。","（《十國春秋》卷九九《僧文炬傳》）。"]', '["小月走爍爍，千落及万落。","处处鳳離穴，家家種葵藿。","（《十国春秋》卷九九《僧文炬傳》）。"]', '诗', 'shi', '', NULL, '偈 文炬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88e4780-b10d-4578-af0a-ab132ede3f37', '過尤溪青印石留偈（題擬）', '過尤溪青印石留偈（題擬）', '08d20cb5-470a-4428-9146-36a49012cd0b', '唐', '["塔前青印見，家家親筆硯。","水流保安前，尤溪出狀元。","（見嘉靖《尤溪縣志》卷一。","稱爲黃涅槃作。","）。"]', '["塔前青印见，家家親笔硯。","水流保安前，尤溪出狀元。","（见嘉靖《尤溪縣志》卷一。","稱爲黄涅槃作。","）。"]', '诗', 'shi', '', NULL, '過尤溪青印石留偈（題擬） 文炬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412e9bf5-d50f-4dc1-89a9-1b00956b7065', '六合懷古詩 橫山（原題作「橫山懷古」）', '六合懷古诗 橫山（原題作「橫山懷古」）', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["昭明曾置讀書堂，後倚橫山翠石岡。","巨盜黃巢鋒刃刺，神堅終不下僧床。","（見康熙《儀真縣志》卷十二，據上海圖書館藏縮微膠卷）（〖1〗隆慶《儀真縣志》卷二載：「梁讀晝堂，在橫山西，天監中建。","宋郟滂詩謂昭明太子嘗讀書於此，即禪征寺也。","」「宋」爲「唐」之誤。","）。"]', '["昭明曾置读书堂，後倚橫山翠石岡。","巨盜黄巢鋒刃刺，神堅終不下僧床。","（见康熙《儀真縣志》卷十二，據上海圖书館藏縮微膠卷）（〖1〗隆慶《儀真縣志》卷二載：「梁读晝堂，在橫山西，天監中建。","宋郟滂诗謂昭明太子嘗读书於此，即禪征寺也。","」「宋」爲「唐」之誤。","）。"]', '诗', 'shi', '', NULL, '六合懷古詩 橫山（原題作「橫山懷古」） 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9059470e-a8c1-4ece-9872-1f465a1dae33', '六合懷古詩 芳草澗', '六合懷古诗 芳草澗', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["芳草澗邊灌水（《光緒志》作「木」）陰，青青別有歲寒心。","卻緣飄落秋風後，才子臨流亦費吟。","（〖1〗《嘉靖志》注：「《嘉定志》。","自此以下二十首皆郟滂《懷古詩》。","」）。"]', '["芳草澗邊灌水（《光緒志》作「木」）陰，青青別有歲寒心。","卻緣飄落秋风後，才子臨流亦費吟。","（〖1〗《嘉靖志》注：「《嘉定志》。","自此以下二十首皆郟滂《懷古诗》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 芳草澗 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201c8bc0-6ce1-4dcb-83e7-66e09bf1342e', '六合懷古詩 塔山二首 一', '六合懷古诗 塔山二首 一', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["此山元以形如塔，貞觀年中改疊層（《光緒志》作「成」）。","圭字峰尖真似畫，塔名不語爲高增（《光緒志》作「河僧」）。","（〖1〗《嘉靖志》注：「嘉定志。","」）。"]', '["此山元以形如塔，貞观年中改叠層（《光緒志》作「成」）。","圭字峰尖真似畫，塔名不語爲高增（《光緒志》作「河僧」）。","（〖1〗《嘉靖志》注：「嘉定志。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 塔山二首 一 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588f030c-bd6d-48c3-9338-aca7c37e2e30', '六合懷古詩 塔山二首 二', '六合懷古诗 塔山二首 二', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["疊疊山形似塔形，崔峩聳翠幾稜層。","乘騶翫罷歸禪院，佳境（《光緒志》作「地」）原來盡屬僧。","（〖1〗《嘉靖志》注：「《成化志》。","」）。"]', '["叠叠山形似塔形，崔峩聳翠幾稜層。","乘騶翫罷归禪院，佳境（《光緒志》作「地」）原来尽屬僧。","（〖1〗《嘉靖志》注：「《成化志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 塔山二首 二 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f667e8d-084d-4a4b-ba79-23f6601baf8e', '六合懷古詩 獨山 一', '六合懷古诗 独山 一', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["獨山有峰插天表，湖水臨谿接官道。","我欲浩歌一登遊，不忍足脚（《光緒志》作「踏」）青青草。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["独山有峰插天表，湖水臨谿接官道。","我欲浩歌一登游，不忍足脚（《光緒志》作「踏」）青青草。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 獨山 一 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d91334-8f85-4d62-b2de-57849f4ccfeb', '六合懷古詩 獨山 二', '六合懷古诗 独山 二', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["廣澤之中是獨山，恍疑翠帶遶城（《光緒志》作「層」）巒。","馬臨絕頂遙相望，惟見煙雲萬木攢。","（〖1〗《嘉靖志》注：「《成化志》。","」）。"]', '["廣澤之中是独山，恍疑翠带遶城（《光緒志》作「層」）巒。","马臨絕頂遙相望，惟见煙云万木攢。","（〖1〗《嘉靖志》注：「《成化志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 獨山 二 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353fef33-7c09-4a4e-afce-3dbe2dcbb612', '六合懷古詩 惜水灣', '六合懷古诗 惜水灣', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["惜水紆迴懼水奔，春潮帶雨晚流渾。","靈巖滁口常縈遶，沙際磯頭祇見痕。","（〖1〗《嘉靖志》注：「見《成化志》，參之《嘉定志》，有數字不同，正之，後多改正。","「）。"]', '["惜水紆迴懼水奔，春潮带雨晚流渾。","靈巖滁口常縈遶，沙際磯头祇见痕。","（〖1〗《嘉靖志》注：「见《成化志》，參之《嘉定志》，有數字不同，正之，後多改正。","「）。"]', '诗', 'shi', '', NULL, '六合懷古詩 惜水灣 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55177ac1-d128-41d5-aaa4-8bb49e6c0c6d', '六合懷古詩 龍池 一', '六合懷古诗 龙池 一', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["波光杳靄遠連天，鷺宿沙頭玉一拳。","料想中流深莫測，龍潛潭底抱珠眠。","。"]', '["波光杳靄远連天，鷺宿沙头玉一拳。","料想中流深莫測，龙潛潭底抱珠眠。","。"]', '诗', 'shi', '', NULL, '六合懷古詩 龍池 一 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4655571-ff27-4942-afd2-4d0e619d0bda', '六合懷古詩 龍池 二', '六合懷古诗 龙池 二', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["池深常有神龍隱，灣島如人出擘（《光緒志》作「臂」）拳。","澄澈無涯深淺水，虔恭祈禱雨連綿。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["池深常有神龙隐，灣島如人出擘（《光緒志》作「臂」）拳。","澄澈無涯深淺水，虔恭祈禱雨連綿。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 龍池 二 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc29752-7021-4dfb-abbd-0ef8961be6e0', '六合懷古詩 晉王城', '六合懷古诗 晉王城', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["隋收建業臨江渚，東望金陵築此城。","正與石頭爲對岸，從茲一統六朝平。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["隋收建業臨江渚，东望金陵築此城。","正與石头爲对岸，從茲一統六朝平。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 晉王城 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad0f430-7bd7-4725-8375-d656d274d19a', '六合懷古詩 [苻]（符）融城', '六合懷古诗 [苻]（符）融城', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["秦人百萬征南日，蕞（《光緒志》作「驀」）地[苻]（符）築此城。","把隘亡兵今有幾，蓮峰之下誤爭名。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["秦人百万征南日，蕞（《光緒志》作「驀」）地[苻]（符）築此城。","把隘亡兵今有幾，蓮峰之下誤爭名。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 [苻]（符）融城 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ffa18a-7c9f-4f4f-92f7-e513ba2d4f08', '六合懷古詩 龍津橋', '六合懷古诗 龙津橋', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["橋灣螮蝀臨滁水，十八衖高似月輪。","不是巢兵燒燬後，至今猶復（《光緒志》作「得」）跨龍津。"]', '["橋灣螮蝀臨滁水，十八衖高似月輪。","不是巢兵燒燬後，至今猶复（《光緒志》作「得」）跨龙津。"]', '诗', 'shi', '', NULL, '六合懷古詩 龍津橋 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343fd0c6-5d5c-4fd5-9f18-2c15200669b8', '六合懷古詩 永定岡', '六合懷古诗 永定岡', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["梁朝瞻見長岡秀，鑿斷川流寺濤（《光緒志》作「壽」）基。","杳杳松門千萬綠，山亭溪樹蓽（《光緒志》作「有」）蘿垂。"]', '["梁朝瞻见长岡秀，鑿斷川流寺濤（《光緒志》作「壽」）基。","杳杳松门千万綠，山亭溪樹蓽（《光緒志》作「有」）蘿垂。"]', '诗', 'shi', '', NULL, '六合懷古詩 永定岡 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78fbda57-21b5-4848-8dab-e705b252fa7d', '六合懷古詩 治浦橋', '六合懷古诗 治浦橋', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["治浦橋連香積寺，東出城門五里遙。","遠望真如有圖畫，關防迢遞在雲霄。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["治浦橋連香積寺，东出城门五里遙。","远望真如有圖畫，关防迢遞在云霄。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 治浦橋 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be90933-bdc0-43d7-a5db-4acc7d82224a', '六合懷古詩 滁河', '六合懷古诗 滁河', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["滁水源從德固塘，支流六九合流棠。","經過瓜步趨江海，惟有入心難測量。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["滁水源從德固塘，支流六九合流棠。","經過瓜步趨江海，惟有入心难測量。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 滁河 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e32aee-c27b-4ec6-86d6-101349859927', '六合懷古詩 廢清風亭', '六合懷古诗 廢清风亭', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["舊縣元基城巽隅，亭簾高檻蘸清滁。","風生六月思裘褐，百里恩波剸割餘。","（〖1〗《嘉靖志》題注：「《嘉定志》：唐時縣治有清風亭，縣令獨孤及建。","至郟滂時已廢。","」〖2〗《光緒志》詩末注：「士林館在竹鎮，地多習儒業。","」）。"]', '["旧縣元基城巽隅，亭簾高檻蘸清滁。","风生六月思裘褐，百里恩波剸割餘。","（〖1〗《嘉靖志》題注：「《嘉定志》：唐时縣治有清风亭，縣令独孤及建。","至郟滂时已廢。","」〖2〗《光緒志》诗末注：「士林館在竹鎮，地多習儒業。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 廢清風亭 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ed1d07-9bcf-4085-bea0-1bada71c9095', '六合懷古詩 廢士林館', '六合懷古诗 廢士林館', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["士林館側盡儒流，朝士莊田隔近陬。","見說人稀難駐泊，于今荆棘走獐麀。","（〖1〗《嘉靖志》題注：「《嘉定志》：士林館在竹鎮，其地習儒業，多仕官。","郟滂時館已廢。","」〖2〗《光緒志》詩末注：「士林館在竹鎮，地多習儒業。","」）。"]', '["士林館側尽儒流，朝士莊田隔近陬。","见说人稀难駐泊，于今荆棘走獐麀。","（〖1〗《嘉靖志》題注：「《嘉定志》：士林館在竹鎮，其地習儒業，多仕官。","郟滂时館已廢。","」〖2〗《光緒志》诗末注：「士林館在竹鎮，地多習儒業。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 廢士林館 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcaaa37-82c9-4b62-b5c6-3ef54d99a522', '六合懷古詩 廢如歸館', '六合懷古诗 廢如归館', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["旅況淒淒南北涯，每投新館便如歸。","當年盛（《光緒志》作「勝」）事今何在，卻使揚朱淚滿衣。","（〖1〗《嘉靖志》題注：「《嘉定志》：如歸館在東門，南北若館驛然。","郟滂時已廢。","」〖2〗《光緒志》詩末注：「如歸館在東門北。","」〖3〗《金陵詩徵》卷三五題注：「在東門外。","」）。"]', '["旅況淒淒南北涯，每投新館便如归。","當年盛（《光緒志》作「勝」）事今何在，卻使揚朱泪满衣。","（〖1〗《嘉靖志》題注：「《嘉定志》：如归館在东门，南北若館驛然。","郟滂时已廢。","」〖2〗《光緒志》诗末注：「如归館在东门北。","」〖3〗《金陵诗徵》卷三五題注：「在东门外。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 廢如歸館 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbce3522-2a2e-4be7-93a3-b57b32ae972d', '六合懷古詩 城隍廟', '六合懷古诗 城隍廟', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["黥布城隍有感靈，祇緣劉項霸江津。","古來廟祝依然在，福蔭江壖萬萬春。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '["黥布城隍有感靈，祇緣劉項霸江津。","古来廟祝依然在，福蔭江壖万万春。","（〖1〗《嘉靖志》注：「《嘉定志》。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 城隍廟 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10844d40-8470-4fe6-b63e-9f1f08433fd1', '六合懷古詩 儒學舊基', '六合懷古诗 儒学旧基', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["牛市街中儒祖廟，衣冠俎豆五經書。","不知殿宅今存否？雙檜蒼虬聳碧虛。","（〖1〗《嘉靖志》題注：「《嘉定志》：儒學在河南牛市街。","郟滂時學己遷。","其地有杜荀鶴所植偃松二。","」）。"]', '["牛市街中儒祖廟，衣冠俎豆五經书。","不知殿宅今存否？雙檜蒼虬聳碧虛。","（〖1〗《嘉靖志》題注：「《嘉定志》：儒学在河南牛市街。","郟滂时学己遷。","其地有杜荀鹤所植偃松二。","」）。"]', '诗', 'shi', '', NULL, '六合懷古詩 儒學舊基 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c0211e-30c1-4c71-a105-18f932ae200c', '六合懷古詩 偃松（《光緒志》作「偃蓋松」）', '六合懷古诗 偃松（《光緒志》作「偃蓋松」）', 'b0a198f4-a2a8-49b0-b52b-796e2024b166', '唐', '["千年松樹枝芳偃，屈曲如人掉臂形。","見說瓦棺藏檜下，杜生題後定時名。","（以上二十首均錄自上海圖書館據天一閣藏本所攝膠卷明嘉靖刻本嘉三十二年黃紹文纂《六合縣志》〖簡稱《嘉靖志》〗卷八《藝文志·詩類》。","校以光緒癸未年刊賀廷壽纂《六合縣志》〖簡稱《光緒志》〗卷七所錄詩及光緒刊朱緒曾輯《金陵詩徵》卷三五所收詩。","《光緒志》錄十六首，缺《治浦橋》、《滁河》、《儒學舊基》、《城隍廟》四首。","《金陵詩徵》僅收《龍池》之一、《廢如歸館》二首。","）（〖1〗《嘉靖志》題注：「《嘉定志》：偃松在牛市街，文宣王廟前，偃蹇若蓋，清陰數畝。","傳云杜荀鶴所植。","又云松下有瓦棺。","」〖2〗《光緒志》詩末注：「古志云，松下有瓦棺。","」〖3〗《嘉靖志》詩末注：「按以上二十首，皆郟滂詩。","五十首，今《成化志》所載僅數首耳，餘皆《嘉定志》得之，然尚未及其半云。","」〖4〗《嘉靖志》卷首凡例云：「宋嘉定間縣令劉昌詩所修志，板已劘滅，其本無傳。","近於藏書家覓得寫本，據其所載，有可採者增入。","」〖5〗《嘉靖志》卷四《秩官志》云：「郟滂，光化中爲六合宰，嘗作《懷古詩》五十首，敍靈巖則曰：『巖峻嘗有靈瑞。","』敍龍津則曰：『士馬更戍往來。","』若儒學、士林館、龍池、昌市樓等處，皆有題詠。","意滂必文彩風流之士，當時之民被和平之化矣。","惜其政事無傳，詩之存者載《詩紀》。","」末注：「《嘉定》、《成化志》。","」〖6〗《光緒志》卷四《官師志》云：「郟滂，光化中爲六合令。","懼文獻無徵，作《懷古詩》五十首，各繫以小敍，今其詩存者三十二首，惜政蹟不傳。","」〖7〗《金陵詩徵》卷三五錄滂詩二首，小傳云：「滂，光化中六合令，因家焉。","」注云：「宋《嘉定六合縣志》云：郟令懼棠邑文獻無徵，作《懷古詩》五十首，各係以小敍，其叙靈巖曰：『巖峻嘗有靈瑞。","』敍龍津曰：『士馬更戍往來。","』士林曰：『其地業儒多宦。","』敍寺則始於解脫，敍混成觀則起於宋元。","《嘉靖儀真志》存三十二首，至雍正乙卯六合令蘇作睿《志》尚存十六首，乾隆癸卯廖掄升《志》，乃悉削去。","唐人著作，徵文考獻，何可棄也。","」今按：嘉定、成化修《六合縣志》，今均無傳。","傳世者以《嘉靖志》爲最早，所錄二十首。","據修志者所云，則《嘉定志》所收亦不過此數。","《光緒志》當係自雍正《六合縣志》轉錄，文字歧異較多，疑非源出於嘉靖《六合縣志》，而係自嘉靖《儀真縣志》錄出。","唐六合縣轄境，明代部分歸儀真縣，故其詩得兼收之。","今傳《儀真縣志》，似以《隆慶志》爲最早，已有影印天一閣本行世，經檢幷無滂詩。","朱緒曾、賀廷壽皆清季人，皆云所存有三十二首之數，疑曾獲見嘉靖《儀真縣志》，俟續訪之。","滂詩除已錄出之二十一首外，僅知詩題者尚有《靈巖》、《龍津》、《昌市樓》、《混城觀》等，已見前錄。","）。"]', '["千年松樹枝芳偃，屈曲如人掉臂形。","见说瓦棺藏檜下，杜生題後定时名。","（以上二十首均錄自上海圖书館據天一閣藏本所攝膠卷明嘉靖刻本嘉三十二年黄紹文纂《六合縣志》〖簡稱《嘉靖志》〗卷八《藝文志·诗類》。","校以光緒癸未年刊賀廷壽纂《六合縣志》〖簡稱《光緒志》〗卷七所錄诗及光緒刊朱緒曾輯《金陵诗徵》卷三五所收诗。","《光緒志》錄十六首，缺《治浦橋》、《滁河》、《儒学旧基》、《城隍廟》四首。","《金陵诗徵》僅收《龙池》之一、《廢如归館》二首。","）（〖1〗《嘉靖志》題注：「《嘉定志》：偃松在牛市街，文宣王廟前，偃蹇若蓋，清陰數畝。","傳云杜荀鹤所植。","又云松下有瓦棺。","」〖2〗《光緒志》诗末注：「古志云，松下有瓦棺。","」〖3〗《嘉靖志》诗末注：「按以上二十首，皆郟滂诗。","五十首，今《成化志》所載僅數首耳，餘皆《嘉定志》得之，然尚未及其半云。","」〖4〗《嘉靖志》卷首凡例云：「宋嘉定间縣令劉昌诗所修志，板已劘滅，其本無傳。","近於藏书家覓得寫本，據其所載，有可採者增入。","」〖5〗《嘉靖志》卷四《秩官志》云：「郟滂，光化中爲六合宰，嘗作《懷古诗》五十首，敍靈巖則曰：『巖峻嘗有靈瑞。","』敍龙津則曰：『士马更戍往来。","』若儒学、士林館、龙池、昌市楼等处，皆有題詠。","意滂必文彩风流之士，當时之民被和平之化矣。","惜其政事無傳，诗之存者載《诗紀》。","」末注：「《嘉定》、《成化志》。","」〖6〗《光緒志》卷四《官師志》云：「郟滂，光化中爲六合令。","懼文獻無徵，作《懷古诗》五十首，各繫以小敍，今其诗存者三十二首，惜政蹟不傳。","」〖7〗《金陵诗徵》卷三五錄滂诗二首，小傳云：「滂，光化中六合令，因家焉。","」注云：「宋《嘉定六合縣志》云：郟令懼棠邑文獻無徵，作《懷古诗》五十首，各係以小敍，其叙靈巖曰：『巖峻嘗有靈瑞。","』敍龙津曰：『士马更戍往来。","』士林曰：『其地業儒多宦。","』敍寺則始於解脫，敍混成观則起於宋元。","《嘉靖儀真志》存三十二首，至雍正乙卯六合令蘇作睿《志》尚存十六首，乾隆癸卯廖掄升《志》，乃悉削去。","唐人著作，徵文考獻，何可棄也。","」今按：嘉定、成化修《六合縣志》，今均無傳。","傳世者以《嘉靖志》爲最早，所錄二十首。","據修志者所云，則《嘉定志》所收亦不過此數。","《光緒志》當係自雍正《六合縣志》轉錄，文字歧異較多，疑非源出於嘉靖《六合縣志》，而係自嘉靖《儀真縣志》錄出。","唐六合縣轄境，明代部分归儀真縣，故其诗得兼收之。","今傳《儀真縣志》，似以《隆慶志》爲最早，已有影印天一閣本行世，經檢幷無滂诗。","朱緒曾、賀廷壽皆清季人，皆云所存有三十二首之數，疑曾獲见嘉靖《儀真縣志》，俟續訪之。","滂诗除已錄出之二十一首外，僅知诗題者尚有《靈巖》、《龙津》、《昌市楼》、《混城观》等，已见前錄。","）。"]', '诗', 'shi', '', NULL, '六合懷古詩 偃松（《光緒志》作「偃蓋松」） 郟滂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f181d1e7-eaab-432c-9b98-39d9e132100a', '詩 一', '诗 一', '18433359-fd27-4fc2-8026-984796c1658f', '唐', '["境風吹性海，波起成連山。"]', '["境风吹性海，波起成連山。"]', '诗', 'shi', '', NULL, '詩 一 海印 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed94632-456a-45a8-abc9-803bc0aa0ec4', '詩 二', '诗 二', '18433359-fd27-4fc2-8026-984796c1658f', '唐', '["澄渟復湛然，影像分如印。","（宋晁迥《道院集要》卷三）。"]', '["澄渟复湛然，影像分如印。","（宋晁迥《道院集要》卷三）。"]', '诗', 'shi', '', NULL, '詩 二 海印 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53529657-f73e-443e-9e19-c762e1b9fd12', '句', '句', '48d9082b-b68e-4cc6-bd4e-c3f49ada862a', '唐', '["金甲終不卸，將分理立憂。","（見《吟窗雜錄》卷四一《閩川〖原誤作「山」〗名士傳》）。"]', '["金甲終不卸，將分理立憂。","（见《吟窗杂錄》卷四一《閩川〖原誤作「山」〗名士傳》）。"]', '诗', 'shi', '', NULL, '句 陳巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd35595-2bc4-498c-97a4-65fa317904e3', '牡丹', '牡丹', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["嫚黃妖紫間輕紅，穀雨初晴早景中。","靜女不言還愛日，綵雲無定只隨風。","爐煙坐覺沈檀薄，妝面行看粉黛空。","此別又須經歲月，酒闌把燭遶芳叢。","（見《夢梁錄》卷十八）。"]', '["嫚黄妖紫间轻紅，穀雨初晴早景中。","静女不言還愛日，綵云無定只隨风。","爐煙坐覺沈檀薄，妝面行看粉黛空。","此別又須經歲月，酒闌把燭遶芳叢。","（见《梦梁錄》卷十八）。"]', '诗', 'shi', '', NULL, '牡丹 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96190c7-1cce-4fce-b158-e12bfd6ea31e', '贈前翰林待詔王敬傲（題擬）', '贈前翰林待詔王敬傲（題擬）', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["幽蘭綠水耿清音，歎息先生枉用心。","世上幾時曾好古，人前何必苦霑襟。","（《太平廣記》卷二○三引《耳目記》引）（按：《全唐詩》卷六四三收山甫七律《贈彈琴李處士》，前四句與此首較相似，但首句完全不同，另三句也頗有異文，故仍錄出。","）。"]', '["幽蘭綠水耿清音，歎息先生枉用心。","世上幾时曾好古，人前何必苦霑襟。","（《太平廣記》卷二○三引《耳目記》引）（按：《全唐诗》卷六四三收山甫七律《贈彈琴李处士》，前四句與此首較相似，但首句完全不同，另三句也頗有異文，故仍錄出。","）。"]', '诗', 'shi', '', NULL, '贈前翰林待詔王敬傲（題擬） 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793ac283-725b-4835-b365-5288afdb5397', '神劍歌', '神劍歌', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["異哉神劍實摽奇，自古求人得者稀。","在匣謂（伯作「爲」）言無照耀，用來方覺轉（伯作「見騰」）光輝。","破猶（伯作「由」）預，除狐疑，壯心膽兮定神姿。","六賊既因斯剪拂，八萬塵勞盡乃（伯作「猶自」）揮。","斬邪徒，盪妖孽，生死榮枯（伯作「魔雲」）齊了決。","三尺靈虵覆（伯作「赴」）碧潭，一片晴光瑩（伯作「暎」）寒月。","愚人忘（伯作「望」）劍尅舟求，奔馳（伯作「他」）濁浪徒悠悠（伯作「遊遊」）。","拋棄澄（伯作「塵」）源逐渾派，豈知神劍不隨流。","他人劍兮（伯無「兮」字）帶血腥，我之劍兮含靈鳴（伯作「明」）。","他人（伯作「之」）有劍傷物命，我之有劍救生靈。","君子得時（伯作「之」）離彼此（伯作「我」），小人得處自輕（伯作「之傾其」）生。","他家不用我家劍，世上（伯作「時向」）高低早晚平。","須知神劍功（伯作「弘」）難紀，懾魔威（伯作「怨」）兮定生死。","未得之者易成難，得劍之人難却易。","（伯無此二句）展則（伯作「耶」）周遍（伯作「遊」）法界中，收乃還歸一塵裏。","（伯此下有「不逢斯劍異成難，得劍之人難成異」二句）若將此劍鎮乾坤，四塞終無戰雲起。","（見《祖堂集》卷九、伯三五九一卷）。"]', '["異哉神劍實摽奇，自古求人得者稀。","在匣謂（伯作「爲」）言無照耀，用来方覺轉（伯作「见腾」）光輝。","破猶（伯作「由」）預，除狐疑，壯心膽兮定神姿。","六賊既因斯剪拂，八万塵勞尽乃（伯作「猶自」）揮。","斬邪徒，盪妖孽，生死榮枯（伯作「魔云」）齊了決。","三尺靈虵覆（伯作「赴」）碧潭，一片晴光瑩（伯作「暎」）寒月。","愚人忘（伯作「望」）劍尅舟求，奔驰（伯作「他」）濁浪徒悠悠（伯作「游游」）。","拋棄澄（伯作「塵」）源逐渾派，豈知神劍不隨流。","他人劍兮（伯無「兮」字）带血腥，我之劍兮含靈鳴（伯作「明」）。","他人（伯作「之」）有劍傷物命，我之有劍救生靈。","君子得时（伯作「之」）離彼此（伯作「我」），小人得处自轻（伯作「之傾其」）生。","他家不用我家劍，世上（伯作「时向」）高低早晚平。","須知神劍功（伯作「弘」）难紀，懾魔威（伯作「怨」）兮定生死。","未得之者易成难，得劍之人难却易。","（伯無此二句）展則（伯作「耶」）周遍（伯作「游」）法界中，收乃還归一塵裏。","（伯此下有「不逢斯劍異成难，得劍之人难成異」二句）若將此劍鎮乾坤，四塞終無戰云起。","（见《祖堂集》卷九、伯三五九一卷）。"]', '诗', 'shi', '', NULL, '神劍歌 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a183273e-ad4e-4c90-a727-a1c8f254e205', '浮漚歌（《景德傳燈錄》卷三十作樂普和尚《浮漚歌》）', '浮漚歌（《景德傳灯錄》卷三十作乐普和尚《浮漚歌》）', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["秋（《燈錄》作「雲」）天雨滴（《燈錄》作「落」）庭中水，水上漂漂見漚起。","前者已滅後者生，前後相續何（《燈錄》作「無」）窮已。","本因雨滴水成漚，還緣風激漚歸水。","不知漚水性無殊，隨他轉變將爲異。","外明瑩，內含虛，內外朎朧（《燈錄》作「玲瓏」）若寶珠。","正在澄波看似有，及乎動著又如無，有無動靜事騅明，無相之中有相形。","祇知漚向水中出，豈知水不（《燈錄》作「亦」）從漚生。","權將漚水類余身，五藴虛攢假立人。","能達藴空漚不實，方能明見本來真。","（同前。","以《景德傳燈錄》卷三十所錄詩相校）。"]', '["秋（《灯錄》作「云」）天雨滴（《灯錄》作「落」）庭中水，水上漂漂见漚起。","前者已滅後者生，前後相續何（《灯錄》作「無」）窮已。","本因雨滴水成漚，還緣风激漚归水。","不知漚水性無殊，隨他轉变將爲異。","外明瑩，內含虛，內外朎朧（《灯錄》作「玲瓏」）若寶珠。","正在澄波看似有，及乎动著又如無，有無动静事騅明，無相之中有相形。","祇知漚向水中出，豈知水不（《灯錄》作「亦」）從漚生。","權將漚水類余身，五藴虛攢假立人。","能達藴空漚不實，方能明见本来真。","（同前。","以《景德傳灯錄》卷三十所錄诗相校）。"]', '诗', 'shi', '', NULL, '浮漚歌（《景德傳燈錄》卷三十作樂普和尚《浮漚歌》） 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cef30f2-834e-413e-a55c-1b88adc5cd3c', '答學人問如何是西來意（題擬）', '答学人问如何是西来意（題擬）', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["颯颯當軒竹，經霜不知寒。","祇聞風擊響，不知幾千竿。","（同前）。"]', '["颯颯當軒竹，經霜不知寒。","祇闻风擊响，不知幾千竿。","（同前）。"]', '诗', 'shi', '', NULL, '答學人問如何是西來意（題擬） 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172e6bef-6916-4161-8285-4f249369eb66', '偈 一', '偈 一', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["決志歸鄉去，乘船渡五湖。","舉篙星月隱，停棹日輪孤。","解纜離邪岸，張帆出正途。","到來家蕩盡，免作屋中愚。","（《五燈會元》卷六）。"]', '["決志归乡去，乘船渡五湖。","舉篙星月隐，停棹日輪孤。","解纜離邪岸，張帆出正途。","到来家蕩尽，免作屋中愚。","（《五灯會元》卷六）。"]', '诗', 'shi', '', NULL, '偈 一 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fea549-88d0-49e3-865c-1f5930f00c99', '偈 二', '偈 二', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["石人機似汝，也解唱巴歌。","汝若似石人，雪曲也應和。","（同前）。"]', '["石人機似汝，也解唱巴歌。","汝若似石人，雪曲也應和。","（同前）。"]', '诗', 'shi', '', NULL, '偈 二 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc616895-301e-45ad-92be-6c103ba7a0d8', '偈 三', '偈 三', 'c93e9b5d-c1c2-447a-95c6-5c83b686cf4b', '唐', '["亭午猶虧半，烏沈始得圓。","要會箇中意，牛頭尾上安。","（同前）。"]', '["亭午猶虧半，烏沈始得圓。","要會箇中意，牛头尾上安。","（同前）。"]', '诗', 'shi', '', NULL, '偈 三 元安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27cc84bd-8969-4639-b4cf-ed7c00d49902', '題九疑山', '題九疑山', 'dbb3f46d-f989-4323-a0ae-a9e8ecc12701', '唐', '["靈山登暫歇，欲別忍攜筇。","卻上雲房後，翻思塵世慵。","壇鋪秋月靜，竹掛曉煙濃。","稽首壺中客，仙方願指蹤。","（見同治十一年刊錫榮纂《萍鄉縣志》卷六）。"]', '["靈山登暫歇，欲別忍携筇。","卻上云房後，翻思塵世慵。","壇鋪秋月静，竹掛晓煙濃。","稽首壺中客，仙方願指蹤。","（见同治十一年刊錫榮纂《萍乡縣志》卷六）。"]', '诗', 'shi', '', NULL, '題九疑山 劉松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb04145c-bd43-4e75-bc37-b79190976164', '垂訓詩', '垂訓诗', 'e8e22eea-44fa-45f9-985d-772465799eed', '唐', '["行藏虛實自家知，禍福因由更問誰。","善惡到頭終有報，只爭來早與來遲。","閑中檢點平生事，靜坐思量日所爲。","常把一心行正道，自然天地不相虧。","（見《悅心集》卷一）。"]', '["行藏虛實自家知，禍福因由更问誰。","善惡到头終有報，只爭来早與来遲。","闲中檢点平生事，静坐思量日所爲。","常把一心行正道，自然天地不相虧。","（见《悅心集》卷一）。"]', '诗', 'shi', '', NULL, '垂訓詩 令超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e447ad5-5e0f-4e0c-8d18-81c4de0edbb8', '五臺山夜行遇童子問答忽然不見作', '五台山夜行遇童子问答忽然不见作', '1e758114-fa62-48ec-84b4-45206ddfcfcb', '唐', '["豁州沙界勝伽藍，滿目文殊接話談。","言下聞知開佛眼，迴頭祇見翠山巖。","（見《全五代詩》卷七四）。"]', '["豁州沙界勝伽藍，满目文殊接話談。","言下闻知开佛眼，迴头祇见翠山巖。","（见《全五代诗》卷七四）。"]', '诗', 'shi', '', NULL, '五臺山夜行遇童子問答忽然不見作 文喜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9f8a30-06cb-4081-baa7-6b149fc6aadc', '南遷至衡嶽贈全玼詩（題擬）', '南遷至衡嶽贈全玼诗（題擬）', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["窠居過後更何人，傳得如來法印真。","昨日祝融峰下見，草衣便是雪山身。","（見《宋高僧傳》卷三十）（按：《全唐詩》卷六八八收此詩，有缺文，今重錄。","）。"]', '["窠居過後更何人，傳得如来法印真。","昨日祝融峰下见，草衣便是雪山身。","（见《宋高僧傳》卷三十）（按：《全唐诗》卷六八八收此诗，有缺文，今重錄。","）。"]', '诗', 'shi', '', NULL, '南遷至衡嶽贈全玼詩（題擬） 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80fff2a4-14fd-45c7-b602-2cd2feba3007', '題廊壁', '題廊壁', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["肅肅秋風送暮鐘，江門束鹿傍蒼松。","野人不與朝家事，早晚焚香拜九重。","（《莆風清籟集》卷四八）。"]', '["肅肅秋风送暮鐘，江门束鹿傍蒼松。","野人不與朝家事，早晚焚香拜九重。","（《莆风清籟集》卷四八）。"]', '诗', 'shi', '', NULL, '題廊壁 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148783e4-697f-4157-a1fe-5351cc87f3ea', '示紙衣道者頌', '示紙衣道者頌', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["覺性圓明無相身，莫將知見妄疎親。","念異便於玄體昧，心差不與道爲（《正法眼藏》卷二作「相」）鄰。","情分萬法沈前境，識鑒多端喪本真。","如是（《僧寶傳》卷一作「若向」）句中全曉會，了然無事昔時人。"]', '["覺性圓明無相身，莫將知见妄疎親。","念異便於玄體昧，心差不與道爲（《正法眼藏》卷二作「相」）鄰。","情分万法沈前境，識鑒多端喪本真。","如是（《僧寶傳》卷一作「若向」）句中全晓會，了然無事昔时人。"]', '诗', 'shi', '', NULL, '示紙衣道者頌 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29edfd9-1147-460d-bee3-ddb72d9814b2', '五相偈', '五相偈', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '五相偈 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ff7da3-f861-4127-820c-6d4d240b5a4c', '五相偈 一', '五相偈 一', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["白衣須拜相，此事不爲奇。","積代簪纓者，休言落魄時。"]', '["白衣須拜相，此事不爲奇。","積代簪纓者，休言落魄时。"]', '诗', 'shi', '', NULL, '五相偈 一 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2597d68a-7d91-4b27-b246-bf8f76a3cbe1', '五相偈 二', '五相偈 二', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["子時當正位，明正在君臣。","未離兜率界，烏雞雪上行。"]', '["子时當正位，明正在君臣。","未離兜率界，烏雞雪上行。"]', '诗', 'shi', '', NULL, '五相偈 二 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a9ebe4-3b9f-4c61-bde3-3fe8a48affbd', '五相偈 三', '五相偈 三', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["焰裏寒冰結，楊華九月飛。","泥牛吼水面，木馬逐風嘶。"]', '["焰裏寒冰結，楊华九月飞。","泥牛吼水面，木马逐风嘶。"]', '诗', 'shi', '', NULL, '五相偈 三 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618e6622-ed20-4451-8710-a8075a1fbd16', '五相偈 四', '五相偈 四', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["王宮初降日，玉兔不能離。","未得無功旨，人天何太遲。"]', '["王宮初降日，玉兔不能離。","未得無功旨，人天何太遲。"]', '诗', 'shi', '', NULL, '五相偈 四 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e06047ed-43ef-422d-b981-cfc86de582b6', '五相偈 五', '五相偈 五', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["混（《五燈會元》作「渾」）然藏理事，眹兆卒難明。","威音王未曉，彌勒豈惺惺。"]', '["混（《五灯會元》作「渾」）然藏理事，眹兆卒难明。","威音王未晓，彌勒豈惺惺。"]', '诗', 'shi', '', NULL, '五相偈 五 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98671f5b-6e11-4c21-92d9-8001e8100aaf', '四禁偈', '四禁偈', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["莫行心處路，不掛本來衣。","何須正恁麽，切忌來生時。"]', '["莫行心处路，不掛本来衣。","何須正恁麽，切忌来生时。"]', '诗', 'shi', '', NULL, '四禁偈 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc1fad3-8903-46db-8d8f-756fee04876a', '示學人偈', '示学人偈', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["從緣薦得相應疾，就體消停得力遲（《宗鏡錄》卷四一作「就體消機道却遲」）。","瞥起本來無處所，吾師暫說不思議。"]', '["從緣薦得相應疾，就體消停得力遲（《宗镜錄》卷四一作「就體消機道却遲」）。","瞥起本来無处所，吾師暫说不思議。"]', '诗', 'shi', '', NULL, '示學人偈 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b97bbad-8b9c-4729-a72a-7a7a72a99f6d', '僧舉香巖語示頌', '僧舉香巖語示頌', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["枯木龍吟真（《林間錄》卷下作「方」）見道，髑髏無識（《祖庭事苑》卷二作「識盡」）眼初（《林間錄》作「方」）明。","喜識盡時消息（《景德傳燈錄》卷十七作「不」）盡，當（《僧寶傳》卷一作「常」）人那辨濁中清。"]', '["枯木龙吟真（《林间錄》卷下作「方」）见道，髑髏無識（《祖庭事苑》卷二作「識尽」）眼初（《林间錄》作「方」）明。","喜識尽时消息（《景德傳灯錄》卷十七作「不」）尽，當（《僧寶傳》卷一作「常」）人那辨濁中清。"]', '诗', 'shi', '', NULL, '僧舉香巖語示頌 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9993d422-55c4-4be6-b781-12ee4ddd52f2', '讀傅大士法身偈後作偈', '读傅大士法身偈後作偈', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["渠本不是我，（非我）我本不是渠。","（非渠）渠無我即死，（仰汝取活）我無渠即余。","（不別有）渠如我即佛，（要且不是佛）我如渠即驢。","（二俱不立）不食空王俸，（若遇御飯直須吐却）何假鴈傳書。","（不通信）我說横聲唱，（爲信唱）君看背上毛。","（不與爾相似）乍如謠《白雪》，（將謂是《白雪》）猶恐是巴歌。","（傳此句無注）（以上十首均見《大正新修大藏經》第四七冊《撫州曹山元證禪師語錄》）。"]', '["渠本不是我，（非我）我本不是渠。","（非渠）渠無我即死，（仰汝取活）我無渠即余。","（不別有）渠如我即佛，（要且不是佛）我如渠即驢。","（二俱不立）不食空王俸，（若遇御飯直須吐却）何假鴈傳书。","（不通信）我说横声唱，（爲信唱）君看背上毛。","（不與爾相似）乍如謠《白雪》，（將謂是《白雪》）猶恐是巴歌。","（傳此句無注）（以上十首均见《大正新修大藏經》第四七冊《撫州曹山元證禪師語錄》）。"]', '诗', 'shi', '', NULL, '讀傅大士法身偈後作偈 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c48c59a-7b75-4167-8fa3-a5342ee65218', '頌', '頌', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["今年田不熟，來年種有期。","愛他年少父，須得白頭兒。","（見《祖堂集》卷二十）。"]', '["今年田不熟，来年種有期。","愛他年少父，須得白头兒。","（见《祖堂集》卷二十）。"]', '诗', 'shi', '', NULL, '頌 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a4c2c0-7b7c-4017-a037-10b556f4742f', '偈', '偈', '23043b60-0a4b-4f8d-90c0-bef7529f6ad1', '唐', '["學者先須識自宗，莫將真際雜頑空。","妙明體盡知傷觸，力在逢緣不借中。","出語直教燒不着。","潛行須與古人同。","無身有事超歧路，無事無身落始終。","（《五燈會元》卷十三）。"]', '["学者先須識自宗，莫將真際杂頑空。","妙明體尽知傷觸，力在逢緣不借中。","出語直教燒不着。","潛行須與古人同。","無身有事超歧路，無事無身落始終。","（《五灯會元》卷十三）。"]', '诗', 'shi', '', NULL, '偈 本寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188771af-5e8a-4c6b-955f-43b578133d37', '送洪州禾山和尚偈（題擬）', '送洪州禾山和尚偈（題擬）', 'bf38aa7b-5db4-473d-a0a5-e73f0179cfd8', '唐', '["將寶類寶意不殊，瑠璃線貫瑠璃珠。","內外雙通無異逕，欝我家園桂一株。","（見《祖堂集》卷十二）。"]', '["將寶類寶意不殊，瑠璃線貫瑠璃珠。","內外雙通無異逕，欝我家园桂一株。","（见《祖堂集》卷十二）。"]', '诗', 'shi', '', NULL, '送洪州禾山和尚偈（題擬） 道虔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eb6e421-58b8-4123-b4f8-4b7885777880', '頌', '頌', 'bf38aa7b-5db4-473d-a0a5-e73f0179cfd8', '唐', '["當午日輪圓不照，却指三更暫示人。","莫將明暗消前輩，不是燈邊具足身。","（同前卷九）。"]', '["當午日輪圓不照，却指三更暫示人。","莫將明暗消前輩，不是灯邊具足身。","（同前卷九）。"]', '诗', 'shi', '', NULL, '頌 道虔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccb391d4-354c-4191-8a0c-85a0ca802eeb', '', '', 'f2a50d23-e49f-4740-86d1-08df37b0ac3c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 余鎬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d82af14-df37-47f2-ba6b-dbdf37ecf9d0', '哀林虔中', '哀林虔中', 'f2a50d23-e49f-4740-86d1-08df37b0ac3c', '唐', '["接翅十年同抗疏，投荒萬里獨登樓。","常山忽爲孤城死，睢水空存百戰謀。","函草漫從灰裏覓，嚶聲長向夢中求。","欲知後死今何事，已在莆中買釣舟。","（《閩詩錄甲集》卷一）。"]', '["接翅十年同抗疏，投荒万里独登楼。","常山忽爲孤城死，睢水空存百戰謀。","函草漫從灰裏覓，嚶声长向梦中求。","欲知後死今何事，已在莆中買釣舟。","（《閩诗錄甲集》卷一）。"]', '诗', 'shi', '', NULL, '哀林虔中 余鎬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287ddf4c-e776-4d77-98c9-77411627beb6', '秋晚雲溪隱者居', '秋晚云溪隐者居', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["野寺秋聲苦，靈溪晚翠荒。","人家紅樹老，天氣白雲深。","澤國塵埃少，山川歲月長。","明時一樽酒，誰作釣滄浪？","（影印本《詩淵》第五冊第三一六二頁）。"]', '["野寺秋声苦，靈溪晚翠荒。","人家紅樹老，天氣白云深。","澤国塵埃少，山川歲月长。","明时一樽酒，誰作釣滄浪？","（影印本《诗淵》第五冊第三一六二頁）。"]', '诗', 'shi', '', NULL, '秋晚雲溪隱者居 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48cb5b53-ea58-4494-ad92-507a2a7673d3', '寄題海陵離亭', '寄題海陵離亭', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["銀根菡萏連天落，玉穗蒹葭動地飛。","盪槳先生曾寄夢，憑軒公司合忘機。","江村白鳥和雲沒，澤國寒蟬帶雨微。","何似高秋釣臺上，一聲清嘯送僧歸。","（同前第三四八六頁）（按：《詩淵》第三冊第二一六八頁收《若耶溪》、第五冊第三一七七收《越州新樓》、第三四○五頁收《憶題惠山寺書堂》，皆署高蟾名，經查均應爲李紳詩。","前錄二詩，頗疑亦李紳所作。","今仍收高蟾名下，俟考詳。","）。"]', '["銀根菡萏連天落，玉穗蒹葭动地飞。","盪槳先生曾寄梦，憑軒公司合忘機。","江村白鸟和云沒，澤国寒蟬带雨微。","何似高秋釣台上，一声清嘯送僧归。","（同前第三四八六頁）（按：《诗淵》第三冊第二一六八頁收《若耶溪》、第五冊第三一七七收《越州新楼》、第三四○五頁收《憶題惠山寺书堂》，皆署高蟾名，經查均應爲李紳诗。","前錄二诗，頗疑亦李紳所作。","今仍收高蟾名下，俟考詳。","）。"]', '诗', 'shi', '', NULL, '寄題海陵離亭 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e377aa32-5322-434d-8d78-3d59c1e35c9a', '鄭明府池亭', '鄭明府池亭', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["月魄星精稱逸才，訟亭南面小亭開。","嘯猿洞裏移松入，棲鷺灣中選石來。","數處履痕侵綠甃，半街簾影護青苔。","靜留野客看雲坐，多把清吟送酒杯。","（《詩淵》第五冊第三一三六頁。","原署鄭昌士，爲良士之初名，見《十國春秋》卷九五）。"]', '["月魄星精稱逸才，訟亭南面小亭开。","嘯猿洞裏移松入，棲鷺灣中選石来。","數处履痕侵綠甃，半街簾影護青苔。","静留野客看云坐，多把清吟送酒杯。","（《诗淵》第五冊第三一三六頁。","原署鄭昌士，爲良士之初名，见《十国春秋》卷九五）。"]', '诗', 'shi', '', NULL, '鄭明府池亭 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d630f09-7b3d-4746-a019-fb1051c7403c', '送人罷尉歸山', '送人罷尉归山', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["數年山縣掌閑司，罷任還同到任時。","臨別更無邀客酒，還歸空有寄僧詩。","路傍嶽色行難盡，館宿泉聲夢最遲。","想達故齋春日晚，舊[栽]（裁）庭樹是花枝。","（同前第六冊第四三八三頁）。"]', '["數年山縣掌闲司，罷任還同到任时。","臨別更無邀客酒，還归空有寄僧诗。","路傍嶽色行难尽，館宿泉声梦最遲。","想達故斋春日晚，旧[栽]（裁）庭樹是花枝。","（同前第六冊第四三八三頁）。"]', '诗', 'shi', '', NULL, '送人罷尉歸山 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8386eb9d-fe60-493c-b3d7-872cfc48cf2d', '題鳴峯巖 一', '題鳴峯巖 一', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["卓錫棲雲老道翁，結茅甃塔萬山中。","石爐晝夜香騰霧，琪樹春秋翠插空。","菜長給孤園值雨，藤擺羅漢谷生風。","禪聞寂寞無人到，塵世喧囂總不同。"]', '["卓錫棲云老道翁，結茅甃塔万山中。","石爐晝夜香腾霧，琪樹春秋翠插空。","菜长給孤园值雨，藤擺羅漢谷生风。","禪闻寂寞無人到，塵世喧囂總不同。"]', '诗', 'shi', '', NULL, '題鳴峯巖 一 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac23fcd-eab8-42b2-a9f6-b51182bb91c1', '題鳴峯巖 二', '題鳴峯巖 二', '25fd2674-536c-4882-90f3-2399d34f940e', '唐', '["烟水蒼蒼鯉水南，千松萬籟障精藍。","銀釭剔起殘燈焰，石鼎烹來新茗甘。","罄響僧僮揚梵語，雲迷佛閣隱瞿曇。","道人去久知何處，明月年年照石龕。","（《莆風清籟集》卷五四）。"]', '["烟水蒼蒼鯉水南，千松万籟障精藍。","銀釭剔起殘灯焰，石鼎烹来新茗甘。","罄响僧僮揚梵語，云迷佛閣隐瞿曇。","道人去久知何处，明月年年照石龕。","（《莆风清籟集》卷五四）。"]', '诗', 'shi', '', NULL, '題鳴峯巖 二 鄭良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb53a4c7-5a8b-4e08-a66e-faa2103348c2', '', '', '26a63900-37be-43cd-901e-501abaaccc8a', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 洪諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9154b2a7-1abb-4d75-b175-185d7a6a7fa5', '偈', '偈', '26a63900-37be-43cd-901e-501abaaccc8a', '唐', '["東西不相顧，南北與誰留。","汝則言三四，我道其中一也無。","（見《祖堂集》卷十一。","《景德傳燈錄》卷十一錄此偈，後二句作「汝即言三四，我即一也無」）。","（《五燈會元》卷九作「汝言有三四，我道一也無」）。"]', '["东西不相顧，南北與誰留。","汝則言三四，我道其中一也無。","（见《祖堂集》卷十一。","《景德傳灯錄》卷十一錄此偈，後二句作「汝即言三四，我即一也無」）。","（《五灯會元》卷九作「汝言有三四，我道一也無」）。"]', '诗', 'shi', '', NULL, '偈 洪諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b947163a-9290-4e8d-a974-846a30f0e8bb', '頌', '頌', 'eab456b5-9755-4355-ae35-c9b6add79507', '唐', '["遍學窮切抱死屍，出身不得病難治。","任汝入海常獻寶，不如自治劍輪飛。","（見《祖堂集》卷十一）。"]', '["遍学窮切抱死屍，出身不得病难治。","任汝入海常獻寶，不如自治劍輪飞。","（见《祖堂集》卷十一）。"]', '诗', 'shi', '', NULL, '頌 本空 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83984ba0-9702-4871-996d-43cce1c96412', '詠紅葉題詩事（題擬）', '詠紅葉題诗事（題擬）', '39ab9ff0-9bf5-42c6-954f-dc5eb0a7d8dc', '唐', '["長安百萬戶，御水日東注。","水上有紅葉，子獨得佳句。","子復題脫葉，流入宮中去。","深宮千萬人，葉歸韓氏處。","出宮三千人，韓氏籍中數。","回首謝君恩，淚灑胭脂雨。","寓居貴人家，方與子相遇。","通媒六禮具，百歲爲夫婦。","兒女滿眼前，青紫盈門戶。","茲事自古無，可以傳千古。","（見宋劉斧《青瑣高議前集》卷五錄張實《流紅記》引）（按：紅葉題詩故事，唐時已有三說，《流紅記》述韓氏、于祐事爲第四說，宋人或斥爲衍唐人故事之小說。","張濬此詩，是否出於僞託，尚待考證。","）。"]', '["长安百万戶，御水日东注。","水上有紅葉，子独得佳句。","子复題脫葉，流入宮中去。","深宮千万人，葉归韓氏处。","出宮三千人，韓氏籍中數。","回首謝君恩，泪灑胭脂雨。","寓居貴人家，方與子相遇。","通媒六禮具，百歲爲夫婦。","兒女满眼前，青紫盈门戶。","茲事自古無，可以傳千古。","（见宋劉斧《青瑣高議前集》卷五錄張實《流紅記》引）（按：紅葉題诗故事，唐时已有三说，《流紅記》述韓氏、于祐事爲第四说，宋人或斥爲衍唐人故事之小说。","張濬此诗，是否出於僞託，尚待考證。","）。"]', '诗', 'shi', '', NULL, '詠紅葉題詩事（題擬） 張濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f787801-bcc7-4459-92a8-71ac4f439d5e', '句 一', '句 一', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["釋悶還拈架上書。","（《江湖小集》卷二二李龏《剪綃集》引）。"]', '["釋悶還拈架上书。","（《江湖小集》卷二二李龏《剪綃集》引）。"]', '诗', 'shi', '', NULL, '句 一 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6de45e-ada9-4f17-933d-14e50a549df6', '句 二', '句 二', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["老人終歲閉門坐。","（《梅花字字香後集》）。"]', '["老人終歲閉门坐。","（《梅花字字香後集》）。"]', '诗', 'shi', '', NULL, '句 二 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17547f70-e4e7-4f04-9f8e-ae8cc245c1ef', '頌 一', '頌 一', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["奪人不奪境，緣自帶譊（《五燈會元》、《人天眼目》作「誵」）訛。","擬欲求玄旨，思量反責麽。","驪珠光燦爛，蟾桂葉（《五燈會元》、《人天眼目》作「影」）婆[娑]（婆）（從《五燈會元》、《人天眼目》改）。","覿體（《五燈會元》、《人天眼目》作「面」）無差（《人天眼目》作「回」）互，還應滯網羅。"]', '["奪人不奪境，緣自带譊（《五灯會元》、《人天眼目》作「誵」）訛。","擬欲求玄旨，思量反責麽。","驪珠光燦爛，蟾桂葉（《五灯會元》、《人天眼目》作「影」）婆[娑]（婆）（從《五灯會元》、《人天眼目》改）。","覿體（《五灯會元》、《人天眼目》作「面」）無差（《人天眼目》作「回」）互，還應滯網羅。"]', '诗', 'shi', '', NULL, '頌 一 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf4797aa-3ce3-4d3c-b739-6291580aeb83', '頌 二', '頌 二', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["奪境不奪人，尋言何處真？問禪是禪妄，究理理非親。","日照寒光澹，山搖（《人天眼目》作「遙」）翠色新。","直饒玄會得，恬似（《五燈會元》、《人天眼目》作「也是」）眼中塵。"]', '["奪境不奪人，尋言何处真？问禪是禪妄，究理理非親。","日照寒光澹，山搖（《人天眼目》作「遙」）翠色新。","直饒玄會得，恬似（《五灯會元》、《人天眼目》作「也是」）眼中塵。"]', '诗', 'shi', '', NULL, '頌 二 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec5666e-6335-4182-8e51-1244e08a1b1a', '頌 三', '頌 三', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["人境兩俱奪，從來正令行。","不論佛與祖，那說聖凡情。","擬犯吹毛劍，還傷（《五燈會元》、《人天眼目》作「如」）值木（《人天眼目》作「目」）盲。","進前求妙會，特地打（《五燈會元》、《人天眼目》作「斬」）精靈。"]', '["人境兩俱奪，從来正令行。","不論佛與祖，那说聖凡情。","擬犯吹毛劍，還傷（《五灯會元》、《人天眼目》作「如」）值木（《人天眼目》作「目」）盲。","進前求妙會，特地打（《五灯會元》、《人天眼目》作「斬」）精靈。"]', '诗', 'shi', '', NULL, '頌 三 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3877ce51-751e-4f5a-88fd-a539e3b4b88a', '頌 四', '頌 四', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["人境俱不奪，思量意不偏。","主賓言不（《五燈會元》作「少」）異，問答理俱全。","踏破澄潭月，穿開碧落天。","不能明妙用，淪溺在無緣。","（《天聖廣燈錄》卷十三、《五燈會元》卷十一、《人天眼目》卷一）。"]', '["人境俱不奪，思量意不偏。","主賓言不（《五灯會元》作「少」）異，问答理俱全。","踏破澄潭月，穿开碧落天。","不能明妙用，淪溺在無緣。","（《天聖廣灯錄》卷十三、《五灯會元》卷十一、《人天眼目》卷一）。"]', '诗', 'shi', '', NULL, '頌 四 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8dfc01-f0e8-4d6c-9ff1-3cff3254b559', '初祖熊耳峰', '初祖熊耳峰', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["閑佩毗盧印，人天末位尊。","寶航橫鳳浦，金錫挂龍門。","去後梁王感，來光魏主恩。","葱山擕隻履，半偈動乾坤。","。"]', '["闲佩毗盧印，人天末位尊。","寶航橫鳳浦，金錫挂龙门。","去後梁王感，来光魏主恩。","葱山擕隻履，半偈动乾坤。","。"]', '诗', 'shi', '', NULL, '初祖熊耳峰 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8751be46-47a7-45c2-bdf5-9d46c7a8f28a', '二祖漳川鳳', '二祖漳川鳳', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["別嗣神州祖，聯燈又一迴。","密傳三祖印，還夢五侯街。","玄字乾坤太，慈天日月開。","逆流漳浦上，天感泣雲雷。"]', '["別嗣神州祖，聯灯又一迴。","密傳三祖印，還梦五侯街。","玄字乾坤太，慈天日月开。","逆流漳浦上，天感泣云雷。"]', '诗', 'shi', '', NULL, '二祖漳川鳳 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a571c869-c922-492b-92c0-a3eac6971372', '三祖山谷麟', '三祖山谷麟', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["北齊傳得印，獨步出人間。","祖地江河闊，隨天日月閑。","妙音流四海，瑞氣溢三山。","一句南來信，清風撼雪關。"]', '["北齊傳得印，独步出人间。","祖地江河闊，隨天日月闲。","妙音流四海，瑞氣溢三山。","一句南来信，清风撼雪关。"]', '诗', 'shi', '', NULL, '三祖山谷麟 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e065ca2c-d87b-4d01-93b1-bee9d25bc13c', '四祖雙峯松', '四祖雙峯松', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["翠合雞山樹，峩峩祖岫松。","凝霜分五葉，含雪振雙峯。","月迥金河內，珠添玉鏡中。","颼飀傳細離，天下播真宗。"]', '["翠合雞山樹，峩峩祖岫松。","凝霜分五葉，含雪振雙峯。","月迥金河內，珠添玉镜中。","颼飀傳細離，天下播真宗。"]', '诗', 'shi', '', NULL, '四祖雙峯松 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87febe97-5528-41ef-881f-e1e047be1242', '五祖東山月', '五祖东山月', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["東山分祖印，空際月成輪。","碧眼風光翠，黃梅樹色春。","九枝添瑞鶴，一葉拂祥麟。","別得金僊記，曹谿第五人。"]', '["东山分祖印，空際月成輪。","碧眼风光翠，黄梅樹色春。","九枝添瑞鹤，一葉拂祥麟。","別得金僊記，曹谿第五人。"]', '诗', 'shi', '', NULL, '五祖東山月 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c248dd6-1e67-448e-b4bc-e135cb8ae7bd', '六祖曹谿寶', '六祖曹谿寶', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["南得黃梅意，曹谿記法泉。","三衣兼祖印，一鉢盡師傳。","慈月光千海，玄河注百川。","神洲十二代，法眼繼相傳。"]', '["南得黄梅意，曹谿記法泉。","三衣兼祖印，一鉢尽師傳。","慈月光千海，玄河注百川。","神洲十二代，法眼繼相傳。"]', '诗', 'shi', '', NULL, '六祖曹谿寶 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ba0501-08bf-42c7-a4b2-e604eabd5787', '毗盧印', '毗盧印', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["天中慈月三峯迥，指外懸河萬派深。","仙舸獨遊華藏海，無邊川澤喜歸心。"]', '["天中慈月三峯迥，指外懸河万派深。","仙舸独游华藏海，無邊川澤喜归心。"]', '诗', 'shi', '', NULL, '毗盧印 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9aa7fa-07e1-4951-9891-63f6153371ab', '熊耳巖', '熊耳巖', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["熊耳宗師葬洛陽，龍城天子[泣]（位）千行。","迴擔隻履葱山上，驚殺梁王與魏王。"]', '["熊耳宗師葬洛陽，龙城天子[泣]（位）千行。","迴擔隻履葱山上，驚殺梁王與魏王。"]', '诗', 'shi', '', NULL, '熊耳巖 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e4c4c3-07e7-4e06-80b4-02a4126694b3', '馬祖麟', '马祖麟', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["麟眠法苑分千葉，馬踏曹谿迸萬泉。","古佛傳中親授記，月轉碾破海中天。"]', '["麟眠法苑分千葉，马踏曹谿迸万泉。","古佛傳中親授記，月轉碾破海中天。"]', '诗', 'shi', '', NULL, '馬祖麟 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0004fe3a-01e6-445c-b3ac-65e3159f09f2', '百丈松', '百丈松', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["百丈和霜嶺上松，蛇盤鶴性瘦如龍。","下堂索著稱名字，不會師心一萬重。"]', '["百丈和霜嶺上松，蛇盤鹤性瘦如龙。","下堂索著稱名字，不會師心一万重。"]', '诗', 'shi', '', NULL, '百丈松 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b89e6b-44c8-4bb3-8b31-f5d82648fe9a', '臨濟龍', '臨濟龙', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["龍控懸河海月秋，煙霞風雨一時收。","波濤急急人難會，截斷千江水不流。"]', '["龙控懸河海月秋，煙霞风雨一时收。","波濤急急人难會，截斷千江水不流。"]', '诗', 'shi', '', NULL, '臨濟龍 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fa0ce4-3e69-422a-800a-f7af67f1c9cf', '龍潭月', '龙潭月', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["祖派波瀾半偈玄，曹谿舟棹接風煙。","一轉海底龍潭月，碾破雞山雪嶺前。"]', '["祖派波瀾半偈玄，曹谿舟棹接风煙。","一轉海底龙潭月，碾破雞山雪嶺前。"]', '诗', 'shi', '', NULL, '龍潭月 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f94ff59-b815-437a-b079-0f20e86670a1', '雙林桂', '雙林桂', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["身受龍華三會主，搥開鳳閣九重城。","梁王築倒金剛佛，更[問]（門）如何不講經。"]', '["身受龙华三會主，搥开鳳閣九重城。","梁王築倒金剛佛，更[问]（门）如何不講經。"]', '诗', 'shi', '', NULL, '雙林桂 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f48e77-9dc3-4a73-bff1-aef7142149e7', '藥山刀', '藥山刀', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["藥岫龍泉照瞻清，乾坤宗匠盡流行。","格高一句難分出，驀就雲巖谷口明。","。"]', '["藥岫龙泉照瞻清，乾坤宗匠尽流行。","格高一句难分出，驀就云巖谷口明。","。"]', '诗', 'shi', '', NULL, '藥山刀 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24b832c-3a02-4a0c-ac58-96a2431885f6', '丹霞日', '丹霞日', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["一片丹霞見石頭，麒麟雙鳳況難傳。","鋒鋩欲說宗門印，哽得師心掩耳休。"]', '["一片丹霞见石头，麒麟雙鳳況难傳。","鋒鋩欲说宗门印，哽得師心掩耳休。"]', '诗', 'shi', '', NULL, '丹霞日 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c614b2-8716-4787-86e4-8c16ba4f7ec3', '鳥窠柏樹居', '鸟窠柏樹居', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["白鳳烟霞控鳥窠，驪龍珠耀祖山河。","當初捻起布毛意，體用毗盧些子多。"]', '["白鳳烟霞控鸟窠，驪龙珠耀祖山河。","當初捻起布毛意，體用毗盧些子多。"]', '诗', 'shi', '', NULL, '鳥窠柏樹居 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8951ac9b-3721-429b-9052-0dcb72b779eb', '石鞏弓', '石鞏弓', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["龍劍雕弓祖佛威，霜鋒雷電急難追。","當初金鏃胸前過，由未重玄多許爲。"]', '["龙劍雕弓祖佛威，霜鋒雷電急难追。","當初金鏃胸前過，由未重玄多許爲。"]', '诗', 'shi', '', NULL, '石鞏弓 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4706a9f-395c-43e4-b7b9-d440ab8e0ec0', '歸宗石', '归宗石', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["雪彩霜威馬祖風，虎降高格氣如龍。","誰人會得歸宗路？一鏃三關海內通。"]', '["雪彩霜威马祖风，虎降高格氣如龙。","誰人會得归宗路？一鏃三关海內通。"]', '诗', 'shi', '', NULL, '歸宗石 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2aceed-24f5-4594-8c32-e8ce7a240ba2', '大梅霜', '大梅霜', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["虎見烟蘿透洞門，心中古佛震乾坤。","龍泉截斷麒麟角，撼得毗盧海月昏。"]', '["虎见烟蘿透洞门，心中古佛震乾坤。","龙泉截斷麒麟角，撼得毗盧海月昏。"]', '诗', 'shi', '', NULL, '大梅霜 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5c68b5-1835-4368-bbf8-3dc13fd18530', '灌谿水', '灌谿水', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["一派曹源與灌谿，龍行風雨動雲霓。","後機箭筈波瀾急，撼得毗盧海岳低。"]', '["一派曹源與灌谿，龙行风雨动云霓。","後機箭筈波瀾急，撼得毗盧海岳低。"]', '诗', 'shi', '', NULL, '灌谿水 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b436feee-fed5-44db-a595-4d73d50a5af9', '天皇竹', '天皇竹', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["龍吟鳳彩震乾坤，熊耳雞山海內聞。","一片雪霜三島外，虎心半偈灑風雲。"]', '["龙吟鳳彩震乾坤，熊耳雞山海內闻。","一片雪霜三島外，虎心半偈灑风云。"]', '诗', 'shi', '', NULL, '天皇竹 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0387abf-eabd-429f-b537-c7f146889399', '牛頭雪', '牛头雪', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["六葉牛頭枡別栽，五天熊耳縱雲雷。","須知四祖垂機接，百鳥銜華更不來。","。"]', '["六葉牛头枡別栽，五天熊耳縱云雷。","須知四祖垂機接，百鸟銜华更不来。","。"]', '诗', 'shi', '', NULL, '牛頭雪 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3188e93-2ea5-4a94-9e3e-818bdd42226d', '五泄泉', '五泄泉', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["發意當初問石頭，江河心濆渺分流。","喚迴指出毗盧印，便得如山萬事休。"]', '["發意當初问石头，江河心濆渺分流。","喚迴指出毗盧印，便得如山万事休。"]', '诗', 'shi', '', NULL, '五泄泉 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28c874e-cd0c-405e-ae19-4479a7bb25e1', '魯祖巖', '魯祖巖', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["虎徑龍泉遶行巖，鳳棲霜倚鶴和杉。","誰人會得宗師意？","[扭]（紐）轉乾坤好不參。"]', '["虎徑龙泉遶行巖，鳳棲霜倚鹤和杉。","誰人會得宗師意？","[扭]（紐）轉乾坤好不參。"]', '诗', 'shi', '', NULL, '魯祖巖 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1266999-eec8-469f-9dd2-df1f39225491', '汾州玉', '汾州玉', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["龍宮鹿苑百川通，八藏三乘在掌中。","却是江西逢馬祖，迴頭踏轉大虛空。"]', '["龙宮鹿苑百川通，八藏三乘在掌中。","却是江西逢马祖，迴头踏轉大虛空。"]', '诗', 'shi', '', NULL, '汾州玉 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f3a833-96fa-4927-a85d-fddcdda634d7', '疎山松', '疎山松', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["疎嶺松蘿五葉雲，毗盧天外別爲秦。","驪龍踏轉虛空月，木馬重嘶雨露新。"]', '["疎嶺松蘿五葉云，毗盧天外別爲秦。","驪龙踏轉虛空月，木马重嘶雨露新。"]', '诗', 'shi', '', NULL, '疎山松 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('011e59ff-2842-4033-9356-970682693007', '關南鼓', '关南鼓', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["錫撼風霜虎豹愁，楚王城裏倒騎牛。","騰騰盡喝關南鼓，聲壓雲雷動九疇。"]', '["錫撼风霜虎豹愁，楚王城裏倒騎牛。","腾腾尽喝关南鼓，声壓云雷动九疇。"]', '诗', 'shi', '', NULL, '關南鼓 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc3f58b-4c1e-4460-83dc-2d54a5efa149', '韻山壁', '韻山壁', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["熊耳雞山五印玄，蛇盤鳳口九瓟泉。","紫霄峯上一輪月，照破曹谿半夜圓。"]', '["熊耳雞山五印玄，蛇盤鳳口九瓟泉。","紫霄峯上一輪月，照破曹谿半夜圓。"]', '诗', 'shi', '', NULL, '韻山壁 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0279b45a-ee59-479b-9107-c614360ba512', '南嶽讓禪師鳳', '南嶽讓禪師鳳', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["別沐曹谿水，棲衡嶽萬重。","有心傳五葉，無意據千峯。","洞鶴爭藏翼，巖雞息瘦容。","一聲乾象外，海內繼真風。","。"]', '["別沐曹谿水，棲衡嶽万重。","有心傳五葉，無意據千峯。","洞鹤爭藏翼，巖雞息瘦容。","一声乾象外，海內繼真风。","。"]', '诗', 'shi', '', NULL, '南嶽讓禪師鳳 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ce6c4a-05d2-42d3-ac04-7e1565cfa587', '吉州鯉', '吉州鯉', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["五天慈雨細，師得潤禪林。","碧眼千燈印，清源一派心。","有涯來敻遠，無底更深沉。","別嗣曹谿後。","衆人仰德音。"]', '["五天慈雨細，師得潤禪林。","碧眼千灯印，清源一派心。","有涯来敻远，無底更深沉。","別嗣曹谿後。","衆人仰德音。"]', '诗', 'shi', '', NULL, '吉州鯉 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4490de4-2b9d-4cd2-a97c-c5285a894441', '南泉竹', '南泉竹', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["根蔕欲何尋？孤奇迥衆林。","鳳來敲節目，龍去曉知音。","撼雪精神別，吟風體物深。","平常烟靄裏，動轉桭虛心。"]', '["根蔕欲何尋？孤奇迥衆林。","鳳来敲節目，龙去晓知音。","撼雪精神別，吟风體物深。","平常烟靄裏，动轉桭虛心。"]', '诗', 'shi', '', NULL, '南泉竹 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16eaf404-0473-4fde-9211-fb759728878e', '石頭松', '石头松', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["出石雄委迥，樛林況莫同。","翠含烟靄外，閏布雪霜中。","影撼千谿月，聲聯五葉風。","妙音傳藥嶠，天下定真宗。"]', '["出石雄委迥，樛林況莫同。","翠含烟靄外，閏布雪霜中。","影撼千谿月，声聯五葉风。","妙音傳藥嶠，天下定真宗。"]', '诗', 'shi', '', NULL, '石頭松 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb48434-caad-48ad-a10a-94c25c0e101f', '夾山雷', '夾山雷', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["澧水風濤急，參差海嶽摧。","浪中澄得月，天外振驚雷。","龍領珠難取，谿巖寶易栽。"]', '["澧水风濤急，參差海嶽摧。","浪中澄得月，天外振驚雷。","龙領珠难取，谿巖寶易栽。"]', '诗', 'shi', '', NULL, '夾山雷 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1f6ed9-c853-4374-8f87-b7747e636d27', '洞山泉', '洞山泉', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["深沉分派異，方外一輪孤。","海底清天鏡，潭中碧眼珠。","千重排雪岸，半偈徹冰壺。","遞印宗門後，人天作楷模。"]', '["深沉分派異，方外一輪孤。","海底清天镜，潭中碧眼珠。","千重排雪岸，半偈徹冰壺。","遞印宗门後，人天作楷模。"]', '诗', 'shi', '', NULL, '洞山泉 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a649c2-8d3e-461d-a449-911f03f77673', '趙州關', '趙州关', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["孤峻南泉派，師機已得閑。","三衣傳祖域，一句動人[寰]（衆）。","幽谷珠光異，藍田玉彩班。","未明根下蔕，難過趙州關。"]', '["孤峻南泉派，師機已得闲。","三衣傳祖域，一句动人[寰]（衆）。","幽谷珠光異，藍田玉彩班。","未明根下蔕，难過趙州关。"]', '诗', 'shi', '', NULL, '趙州關 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065b66fd-3580-4235-bb21-6e5e3a6c3fe2', '雲居月', '云居月', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["素容空界外，廓落迥無邊。","玉鏡同千域，金輪匝五天。","霜凝熊耳印，冰浩鷲峯玄。","不是龍居月，難光洞上泉。"]', '["素容空界外，廓落迥無邊。","玉镜同千域，金輪匝五天。","霜凝熊耳印，冰浩鷲峯玄。","不是龙居月，难光洞上泉。"]', '诗', 'shi', '', NULL, '雲居月 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884960be-945d-4fb7-8a62-17a13bd9ec9f', '都頌', '都頌', 'cdf03e64-f75f-481b-ae16-9360419cd15d', '唐', '["儂家住處實堪隈，吞炭藏身幾萬迴。","不觸波瀾招慶月，動人雲雨鼓山雷。","（以上三十八首皆見《天聖廣燈錄》卷十三，原總題作「師頌三十八首」）。"]', '["儂家住处實堪隈，吞炭藏身幾万迴。","不觸波瀾招慶月，动人云雨鼓山雷。","（以上三十八首皆见《天聖廣灯錄》卷十三，原總題作「師頌三十八首」）。"]', '诗', 'shi', '', NULL, '都頌 剋符道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7346a270-f582-4b97-a8f9-a4c9d8085c84', '頌', '頌', '199fe1ca-f12f-4805-94ba-d06aabb9b706', '唐', '["僧家無事最幽玄，近對青松遠對山。","詩句不曾題落葉，恐隨流水到人間。","（《祖庭事苑》卷三）。"]', '["僧家無事最幽玄，近对青松远对山。","诗句不曾題落葉，恐隨流水到人间。","（《祖庭事苑》卷三）。"]', '诗', 'shi', '', NULL, '頌 志閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a917fc-6ec2-49c9-9813-1ecb222f6ac1', '和王員外雪晴早朝', '和王員外雪晴早朝', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["紫微晴雪帶恩光，繞仗偏隨鴛鷺行。","長信月留寧避曉，宜春花滿不飛香。","獨看積素凝清禁，已覺輕寒讓太陽。","題柱盛名兼絕唱，風流誰繼漢田郎。","（見《錢考功集》卷八）（按：《萬首唐人絕句》卷六八收前四句作錢珝詩。","《韻語陽秋》卷二謂此詩及《同程七蚤入中書》「二詩皆珝所作無疑，蓋起未嘗入中書也。","」《全唐詩》卷二三九收此詩於錢起名下，今爲移正。","）。"]', '["紫微晴雪带恩光，繞仗偏隨鴛鷺行。","长信月留寧避晓，宜春花满不飞香。","独看積素凝清禁，已覺轻寒讓太陽。","題柱盛名兼絕唱，风流誰繼漢田郎。","（见《錢考功集》卷八）（按：《万首唐人絕句》卷六八收前四句作錢珝诗。","《韻語陽秋》卷二謂此诗及《同程七蚤入中书》「二诗皆珝所作無疑，蓋起未嘗入中书也。","」《全唐诗》卷二三九收此诗於錢起名下，今爲移正。","）。"]', '诗', 'shi', '', NULL, '和王員外雪晴早朝 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf0248b-2886-4305-bc27-c0cef359653d', '赴章陵酬李卿留別', '赴章陵酬李卿留別', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["一官叨下秩，九棘謝知音。","芳草文園路，春愁滿別心。","（見《萬首唐人絕句》卷八一、《錢考功集》卷十，均收作錢起詩。","《全唐詩》卷二三九收作錢起詩）。"]', '["一官叨下秩，九棘謝知音。","芳草文园路，春愁满別心。","（见《万首唐人絕句》卷八一、《錢考功集》卷十，均收作錢起诗。","《全唐诗》卷二三九收作錢起诗）。"]', '诗', 'shi', '', NULL, '赴章陵酬李卿留別 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b981cb-4957-41d0-939e-049b90c39ed8', '罷章陵令山居過中峯道者二首 一', '罷章陵令山居過中峯道者二首 一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["寧辭園令秩，不改淵明調。","解印無與言，見山始一笑。","幽人還絕境，誰道苦奔峭。","隨雲剩渡溪，出門更垂釣。","吾廬青霞裏，窗樹玄猿嘯。","微月清風來，方知散髮妙。"]', '["寧辞园令秩，不改淵明調。","解印無與言，见山始一笑。","幽人還絕境，誰道苦奔峭。","隨云剩渡溪，出门更垂釣。","吾廬青霞裏，窗樹玄猿嘯。","微月清风来，方知散髮妙。"]', '诗', 'shi', '', NULL, '罷章陵令山居過中峯道者二首 一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedf48e6-7cad-4e3f-94bc-0c2d61e670a3', '罷章陵令山居過中峯道者二首 二', '罷章陵令山居過中峯道者二首 二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["丘壑去如此，暮年始棲偃。","賴遇無心雲，不笑歸來晚。","鳴鳩拂紅枝，初服傍清畎。","昨日山僧來，猶嫌嘉遯淺。","託君紫陽家，路滅心更遠。","梯雲創其居，抱犢上絕巘。","杏田溪一曲，霞境峰幾轉。","路石挂飛泉，謝公應在眼。","願言攜手去，採藥長不返。","（見《錢考功集》卷三。","《全唐詩》卷二三六收作錢起詩。","吳企明云章陵爲唐文宗陵。","）。"]', '["丘壑去如此，暮年始棲偃。","賴遇無心云，不笑归来晚。","鳴鳩拂紅枝，初服傍清畎。","昨日山僧来，猶嫌嘉遯淺。","託君紫陽家，路滅心更远。","梯云創其居，抱犢上絕巘。","杏田溪一曲，霞境峰幾轉。","路石挂飞泉，謝公應在眼。","願言携手去，採藥长不返。","（见《錢考功集》卷三。","《全唐诗》卷二三六收作錢起诗。","吳企明云章陵爲唐文宗陵。","）。"]', '诗', 'shi', '', NULL, '罷章陵令山居過中峯道者二首 二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e1ad12-e726-4dba-8f78-0f2227b2fe39', '裴侍郎湘川迴以青竹筒相遺因而贈之', '裴侍郎湘川迴以青竹筒相遺因而贈之', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["楚竹青玉潤，從來湘水陰。","緘書取直節，君子知虛心。","入用隨憲簡，積文不受金。","體將丹鳳直，色映秋霜深。","寧肯假伶倫，謬爲龍鳳吟。","唯將翰院客，昔秘瑤華音。","長跪捧嘉貺，歲寒慚所欽。","（同前。","吳企明云裴侍郎爲裴瓚）。"]', '["楚竹青玉潤，從来湘水陰。","緘书取直節，君子知虛心。","入用隨憲簡，積文不受金。","體將丹鳳直，色映秋霜深。","寧肯假伶倫，謬爲龙鳳吟。","唯將翰院客，昔秘瑤华音。","长跪捧嘉貺，歲寒慚所欽。","（同前。","吳企明云裴侍郎爲裴瓚）。"]', '诗', 'shi', '', NULL, '裴侍郎湘川迴以青竹筒相遺因而贈之 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('112a4093-bb78-410e-989c-707c76be364e', '禁闈玩雪寄薛左丞', '禁闈玩雪寄薛左丞', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["玄雲低禁苑，飛雪滿神州。","虛白生臺榭，寒光入冕旒。","粉凝宮壁靜，乳結洞門幽。","細繞迴風轉，輕隨落羽浮。","怒濤堆砌石，新月孕簾鉤。","爲報詩人道，豐年頌聖猷。","（見《錢考功集》卷六。","《全唐詩》卷二三八收作錢起詩。","吳企明云薛左丞指薛廷珪）。"]', '["玄云低禁苑，飞雪满神州。","虛白生台榭，寒光入冕旒。","粉凝宮壁静，乳結洞门幽。","細繞迴风轉，轻隨落羽浮。","怒濤堆砌石，新月孕簾鉤。","爲報诗人道，豐年頌聖猷。","（见《錢考功集》卷六。","《全唐诗》卷二三八收作錢起诗。","吳企明云薛左丞指薛廷珪）。"]', '诗', 'shi', '', NULL, '禁闈玩雪寄薛左丞 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a4a5e7-88d4-4494-922c-ccabd3a98826', '中書遇雨', '中书遇雨', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["濟旱惟宸慮，爲霖即上台。","雲銜七曜起，雨拂九門來。","綸閣飛絲度，龍渠激霤迴。","色翻池上藻，香裛鼎前杯。","湘燕皆舒翼，沙鱗豈曝腮。","尺波應爲假，虞海載沿洄。","（同前）。"]', '["濟旱惟宸慮，爲霖即上台。","云銜七曜起，雨拂九门来。","綸閣飞絲度，龙渠激霤迴。","色翻池上藻，香裛鼎前杯。","湘燕皆舒翼，沙鱗豈曝腮。","尺波應爲假，虞海載沿洄。","（同前）。"]', '诗', 'shi', '', NULL, '中書遇雨 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d366eb3-064c-4eae-bc6b-28609ca7abc8', '中書省言懷因酬嵩陽張道士見寄', '中书省言懷因酬嵩陽張道士见寄', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["朝花尋暝林，對酒傷春心。","流年依素髮，不覺映華簪。","垂老遇中巳（集作「明代」，又作「知己」），酧恩看寸陰。","如何紫芝客（集作「多慙紫陽客」），相憶白雪深。","（見《文苑英華》卷二二八，署「錢起」。","《全唐詩》卷二三七收作錢起詩）（按：以上七首，《全唐詩》皆收作錢起詩。","今從《文學評論》第十三輯吳企明《錢起錢珝詩考辨》一文移正爲錢珝詩。","）（吳文於此數詩考證甚詳，可視作定論。","因文長，茲不備錄。","另吳文尚考出七首錢起詩爲錢珝作，惜所舉之證尚難成爲定論，今不取。","）。"]', '["朝花尋暝林，对酒傷春心。","流年依素髮，不覺映华簪。","垂老遇中巳（集作「明代」，又作「知己」），酧恩看寸陰。","如何紫芝客（集作「多慙紫陽客」），相憶白雪深。","（见《文苑英华》卷二二八，署「錢起」。","《全唐诗》卷二三七收作錢起诗）（按：以上七首，《全唐诗》皆收作錢起诗。","今從《文学評論》第十三輯吳企明《錢起錢珝诗考辨》一文移正爲錢珝诗。","）（吳文於此數诗考證甚詳，可視作定論。","因文长，茲不備錄。","另吳文尚考出七首錢起诗爲錢珝作，惜所舉之證尚难成爲定論，今不取。","）。"]', '诗', 'shi', '', NULL, '中書省言懷因酬嵩陽張道士見寄 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672a448a-a620-47d2-b5d1-329afc7b5aee', '感應詩五十六字', '感應诗五十六字', '54fa68ea-7c8f-4ca7-8a3b-a140b96a445d', '唐', '["聖女嘉祥推感應，葬儀傷慟九般情。","林中愁聽黃鶯囀，月下惟聞白鹿鳴。","慧日流光重抱戴，瑞雲頻繞（《山右石刻叢編》作「現」）五花成。","莫言此地無（《山右石刻叢編》作「栽」）松柏，刊石留將記姓名。","（《山西通志》卷九三《金石記》五錄張瑜撰《大唐廣平郡樂公之二女靈聖通化合葬先代父母有五瑞記》附。","此則承張忱石先生錄示。","又見胡聘之《山右石刻叢編》卷九）。"]', '["聖女嘉祥推感應，葬儀傷慟九般情。","林中愁听黄鶯囀，月下惟闻白鹿鳴。","慧日流光重抱戴，瑞云頻繞（《山右石刻叢編》作「現」）五花成。","莫言此地無（《山右石刻叢編》作「栽」）松柏，刊石留將記姓名。","（《山西通志》卷九三《金石記》五錄張瑜撰《大唐廣平郡乐公之二女靈聖通化合葬先代父母有五瑞記》附。","此則承張忱石先生錄示。","又见胡聘之《山右石刻叢編》卷九）。"]', '诗', 'shi', '', NULL, '感應詩五十六字 張瑜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2eeceed-6fdf-4ce1-9606-f87e9818d56c', '讀書臺', '读书台', 'a080ae46-5e7e-4872-9cae-14c49c2e92fe', '唐', '["坐上沿江碧玉流，讀書人住幾春秋。","塵埃青竹陰連棟，風雨黃茅冷蓋頭。","一榻螙魚今槁死，千年別鶴舊經遊。","吾方曉夜遙山夢，世事從今祇釣舟。","（見清曾燠編《江西詩徵》卷三）。"]', '["坐上沿江碧玉流，读书人住幾春秋。","塵埃青竹陰連棟，风雨黄茅冷蓋头。","一榻螙鱼今槁死，千年別鹤旧經游。","吾方晓夜遙山梦，世事從今祇釣舟。","（见清曾燠編《江西诗徵》卷三）。"]', '诗', 'shi', '', NULL, '讀書臺 歐陽董 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95311001-6fbf-4ff3-bb83-04485f0f507c', '題孟浩然墓', '題孟浩然墓', '4db1b283-739c-47bb-af2e-f339ae18568d', '唐', '["可憐垂世詩千首，換得荒墳數尺碑。","（見《輿地紀勝》卷八二《襄陽府》）。"]', '["可怜垂世诗千首，換得荒墳數尺碑。","（见《輿地紀勝》卷八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '題孟浩然墓 顏蕘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10693ce9-96ee-4aee-a95b-2094823d4f98', '習家池大堤（題擬）', '習家池大堤（題擬）', '4db1b283-739c-47bb-af2e-f339ae18568d', '唐', '["習家池畔思前事，游女江邊想弄珠。","檀溪春水長青蒲，溪上行人問的盧。","（同前）。"]', '["習家池畔思前事，游女江邊想弄珠。","檀溪春水长青蒲，溪上行人问的盧。","（同前）。"]', '诗', 'shi', '', NULL, '習家池大堤（題擬） 顏蕘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64eed06f-a453-4bda-9615-6c4238bad411', '習家池大堤', '習家池大堤', '4db1b283-739c-47bb-af2e-f339ae18568d', '唐', '["習郁穿池事勝游，山翁酣飲繼風流。","（同前）。"]', '["習郁穿池事勝游，山翁酣饮繼风流。","（同前）。"]', '诗', 'shi', '', NULL, '習家池大堤 顏蕘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6516c2bf-ebbc-4463-ab87-530b3bcd4311', '鑪養丹歌', '鑪養丹歌', '4e0f7ad5-6cb9-4533-984e-600805c92bb7', '唐', '["六十時中運丙丁，每用隨時辨五行。","陽氣進時順天轉，陰氣滅候逐星征。","常以加臨須正午，岡宿周來至藥成。","（《正統道藏》本《神仙鍊丹點鑄三元寶照法》）。"]', '["六十时中運丙丁，每用隨时辨五行。","陽氣進时順天轉，陰氣滅候逐星征。","常以加臨須正午，岡宿周来至藥成。","（《正統道藏》本《神仙鍊丹点鑄三元寶照法》）。"]', '诗', 'shi', '', NULL, '鑪養丹歌 歸耕子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa87f2b-fe46-4bed-af98-033e1a27d6ca', '[擬]送賀秘監會稽詩', '[擬]送賀秘監會稽诗', 'c41eccaf-a510-477f-92cc-a7361278f8dd', '唐', '["有客自言狂，經書仕聖唐。","業尊[傅]（傳）帝子，道妙寵君王。","厭俗懷仙觀，思遊憶故鄉。","公卿祖疏廣，親戚送劉綱。","海上波瀾急，江干煙路長。","蓬萊不可見，何處訪霓裳。","（見《會稽掇英總集》卷二）。"]', '["有客自言狂，經书仕聖唐。","業尊[傅]（傳）帝子，道妙寵君王。","厭俗懷仙观，思游憶故乡。","公卿祖疏廣，親戚送劉綱。","海上波瀾急，江干煙路长。","蓬萊不可见，何处訪霓裳。","（见《會稽掇英總集》卷二）。"]', '诗', 'shi', '', NULL, '[擬]送賀秘監會稽詩 李慎微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bfc70cd-d149-4ddf-85b9-3de1e5785c69', '句', '句', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["殘花應逐夜風吹。","（《江湖小集》卷二十李龏《梅花衲》、卷二二李龏《剪綃集》引）。"]', '["殘花應逐夜风吹。","（《江湖小集》卷二十李龏《梅花衲》、卷二二李龏《剪綃集》引）。"]', '诗', 'shi', '', NULL, '句 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f429cc08-08c4-4a1c-b761-ae86e927c202', '', '', '870f9753-6c94-4f80-a82a-f7f94da495c7', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 趙崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c18610-8321-49b0-a0da-a2d4c4ce5248', '贈崔垂休詩（題擬）', '贈崔垂休诗（題擬）', '870f9753-6c94-4f80-a82a-f7f94da495c7', '唐', '["慈恩塔下親（《說郛》本作「上新」）泥壁，滑膩光華玉不如。","何事博陵崔四十，金陵腿上逞歐書。","（見《北里志》）（〖1〗《北里志》：「王團兒……有女數人。","長曰小潤，字子美，少時頗籍籍者。","小天崔垂休變化年溺惑之，所費甚廣。","嘗題記於小潤脾上，爲山所見〖原注：名就今字袞求近白小求宰臨晉〗，贈詩曰〖略〗。","」「爲山所見」四字及原注，《中國古典文學參考資料小叢書》本《北里志》校記及岑仲勉先生《唐人行第錄》「崔四十胤」條皆以爲有脫誤訛舛，甚是。","今檢同書有「小天趙爲山」云云，知此詩爲趙崇贈崔胤之作。","《說郛》本《北里志》上引四字作「爲同年李義山所見」。","李商隱已卒於大中間，與崔胤不同時，其誤顯然。","至原注所云，終難索解，姑存疑。","〖《全唐詩》卷八七二收作無名氏之作，今移正重收〗）。"]', '["慈恩塔下親（《说郛》本作「上新」）泥壁，滑膩光华玉不如。","何事博陵崔四十，金陵腿上逞歐书。","（见《北里志》）（〖1〗《北里志》：「王團兒……有女數人。","长曰小潤，字子美，少时頗籍籍者。","小天崔垂休变化年溺惑之，所費甚廣。","嘗題記於小潤脾上，爲山所见〖原注：名就今字袞求近白小求宰臨晉〗，贈诗曰〖略〗。","」「爲山所见」四字及原注，《中国古典文学參考資料小叢书》本《北里志》校記及岑仲勉先生《唐人行第錄》「崔四十胤」條皆以爲有脫誤訛舛，甚是。","今檢同书有「小天趙爲山」云云，知此诗爲趙崇贈崔胤之作。","《说郛》本《北里志》上引四字作「爲同年李義山所见」。","李商隐已卒於大中间，與崔胤不同时，其誤显然。","至原注所云，終难索解，姑存疑。","〖《全唐诗》卷八七二收作無名氏之作，今移正重收〗）。"]', '诗', 'shi', '', NULL, '贈崔垂休詩（題擬） 趙崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a866a20a-30cd-40ce-8234-6cc1b4f10aec', '閑居', '闲居', 'c454bad7-ebc4-474a-9194-07112ec735a8', '唐', '["小橋風月年年事，爭奈潘郎老去何。","（見《南部新書》卷戊）（按：《全唐詩》卷七九五收二句，缺題，缺一字，今重錄。","）。"]', '["小橋风月年年事，爭奈潘郎老去何。","（见《南部新书》卷戊）（按：《全唐诗》卷七九五收二句，缺題，缺一字，今重錄。","）。"]', '诗', 'shi', '', NULL, '閑居 陳嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e34e069-0a71-4726-bc46-0995fba2f788', '三明大師贈徹大德', '三明大師贈徹大德', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["存詩勾引未能休，閑即因吟到御溝。","故園別來杉檜老，舊山禪處水雲秋。","寒聲漸細鐘搖寺，夜色無窮月滿樓。","攀羨此情高且逸，平生辛苦未能醻。"]', '["存诗勾引未能休，闲即因吟到御溝。","故园別来杉檜老，旧山禪处水云秋。","寒声漸細鐘搖寺，夜色無窮月满楼。","攀羨此情高且逸，平生辛苦未能醻。"]', '诗', 'shi', '', NULL, '三明大師贈徹大德 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f20ae4b-d613-44f7-995e-15f51ff099af', '初出長安', '初出长安', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["聖主每嬌奢，朝庭事可嗟。","不取前殿諫，唯愛《後[庭]（停）花》。","爲進中書策，飜餘逐浪沙。"]', '["聖主每嬌奢，朝庭事可嗟。","不取前殿諫，唯愛《後[庭]（停）花》。","爲進中书策，飜餘逐浪沙。"]', '诗', 'shi', '', NULL, '初出長安 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b279ee-db4f-4792-bf95-1b45c61258df', '初出長安', '初出长安', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一乍出皇都，時登日月餘。","遙看山（何）近遠，店舍路崎嶇。","想料天子女，翻華（疑）草外夫。","然雖朋流下，榮辱□□□。","（〖1〗以上三首均見伯四九八五卷。","）。"]', '["一乍出皇都，时登日月餘。","遙看山（何）近远，店舍路崎嶇。","想料天子女，翻华（疑）草外夫。","然雖朋流下，榮辱□□□。","（〖1〗以上三首均见伯四九八五卷。","）。"]', '诗', 'shi', '', NULL, '初出長安 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec3c61bc-2e6b-485b-bc93-90e7ae2b8833', '過夷門獻詩', '過夷门獻诗', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["四海九州空第一，不同諸鎮府封王。","（《舊五代史》卷二四、《登科記考》卷二四引《唐新纂》。","此則承湯華泉同志見告）（〖1〗《唐新纂》：「荀鶴舉進士及第，東歸過夷門，獻梁太祖詩句云〖詩略〗。","」）。"]', '["四海九州空第一，不同諸鎮府封王。","（《旧五代史》卷二四、《登科記考》卷二四引《唐新纂》。","此則承湯华泉同志见告）（〖1〗《唐新纂》：「荀鹤舉進士及第，东归過夷门，獻梁太祖诗句云〖诗略〗。","」）。"]', '诗', 'shi', '', NULL, '過夷門獻詩 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b3a0acd-b173-4534-81f3-2aedc2d825f7', '維揚冬末寄幕中二從事', '維揚冬末寄幕中二從事', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["聞道長溪尉，相留一館閒。","已投三寸管，尚隔幾重山。","爲旅春風外，懷人夜雨間。","年來疏覽鏡，怕見減朱顏。","（《四庫全書》本《唐風集》卷一）（按：《全唐詩》卷六九一收此詩，第三句全缺，今重錄。","）。"]', '["闻道长溪尉，相留一館閒。","已投三寸管，尚隔幾重山。","爲旅春风外，懷人夜雨间。","年来疏覽镜，怕见減朱顏。","（《四庫全书》本《唐风集》卷一）（按：《全唐诗》卷六九一收此诗，第三句全缺，今重錄。","）。"]', '诗', 'shi', '', NULL, '維揚冬末寄幕中二從事 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6003a01-247c-42da-8c92-800fc5d56277', '旅舍', '旅舍', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["風射破窗燈易滅，月穿疎屋夢難成。","（《千載佳句》卷上《天象部·風月》）。"]', '["风射破窗灯易滅，月穿疎屋梦难成。","（《千載佳句》卷上《天象部·风月》）。"]', '诗', 'shi', '', NULL, '旅舍 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab72011-0f9a-4903-a7ed-f78db6afb398', '題周繇先輩石門山莊', '題周繇先輩石门山莊', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["花亭野客眠雲醉，藥圃家童蹈月鋤。","（同前卷下《隱逸部·山居》）。"]', '["花亭野客眠云醉，藥圃家童蹈月鋤。","（同前卷下《隐逸部·山居》）。"]', '诗', 'shi', '', NULL, '題周繇先輩石門山莊 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7300ca7a-0a4a-4ac2-891c-f528806a2412', '泛瀟湘', '泛瀟湘', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["猿到夜深啼，嶽麓鴈知春。","（見《南嶽總勝集》卷上）。"]', '["猿到夜深啼，嶽麓鴈知春。","（见《南嶽總勝集》卷上）。"]', '诗', 'shi', '', NULL, '泛瀟湘 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41574536-9bbc-4522-90d2-8e02b76f4b96', '送廣利大師歸江東', '送廣利大師归江东', 'f06f2ec3-98ae-41be-8f84-6e603a61df12', '唐', '["楚山楓老楚江清，笠挂高帆浪注罌。","真性本無前後際，葉舟誰問去來程。","忘機每與鷗爲伴，息念應憐月共明。","想見家山諸弟子，盛誇新賜大師名。","（見宋岳珂纂《寶真齋法書贊》卷六）（按：岳珂云此詩真跡一卷，嘉定甲申九月贖之邵邸，楷書，詩幷序尾紀共八行。","詩末署：「中書侍郎平章事崔遠，乾寧四年季夏二十九日書。","」珂另有贊語，評其書法，茲不錄。","〖1〗《宣和書譜》卷四著錄崔遠《送{巩/言}光詩》。","）。"]', '["楚山楓老楚江清，笠挂高帆浪注罌。","真性本無前後際，葉舟誰问去来程。","忘機每與鷗爲伴，息念應怜月共明。","想见家山諸弟子，盛誇新賜大師名。","（见宋岳珂纂《寶真斋法书贊》卷六）（按：岳珂云此诗真跡一卷，嘉定甲申九月贖之邵邸，楷书，诗幷序尾紀共八行。","诗末署：「中书侍郎平章事崔远，乾寧四年季夏二十九日书。","」珂另有贊語，評其书法，茲不錄。","〖1〗《宣和书譜》卷四著錄崔远《送{巩/言}光诗》。","）。"]', '诗', 'shi', '', NULL, '送廣利大師歸江東 崔遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10837d73-96b9-4100-a3ba-922bab01d838', '游南雁蕩', '游南雁蕩', 'cf163799-4ba0-4b5b-947a-72a42b8220c4', '唐', '["山呈圖畫水鳴絃，石室丹臺別有天。","官況屢來忘是客，凡襟洗去欲成仙。","祇因紫綬覊塵海，須把黃花種玉田。","藥徑雲關堪駐跡，釣磯風月不須錢。","（見周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》。"]', '["山呈圖畫水鳴絃，石室丹台別有天。","官況屢来忘是客，凡襟洗去欲成仙。","祇因紫綬覊塵海，須把黄花種玉田。","藥徑云关堪駐跡，釣磯风月不須錢。","（见周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》。"]', '诗', 'shi', '', NULL, '游南雁蕩 朱著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab6e616-8cd8-4d81-b325-2bae96a7b6ab', '延福院（句）', '延福院（句）', 'cf163799-4ba0-4b5b-947a-72a42b8220c4', '唐', '["洞口花開新佛寺，嶺頭苔鎖古仙壇。","（見明人姜準《歧海瑣譚》卷五引南宋曹叔遠《永嘉譜》）（按：朱著逸詩及小傳，皆承張靖龍同志錄示。","）。"]', '["洞口花开新佛寺，嶺头苔鎖古仙壇。","（见明人姜準《歧海瑣譚》卷五引南宋曹叔远《永嘉譜》）（按：朱著逸诗及小傳，皆承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '延福院（句） 朱著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4870a0-7637-4af5-9365-d0c2d2e409b7', '游南雁蕩', '游南雁蕩', '3b1310c8-f378-4b33-8271-47e13f8660aa', '唐', '["碧桃花暖洞門開，遙向春山舉一杯。","灑墨幾人鐫月牖，乘風兩度到蓬萊。","綠陰窗戶長疑雨，白石林泉半雜苔。","王事賢勞閒未得，趣歸猿鶴莫相猜。","（見周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》）（按：吳璋逸詩及小傳，皆承張靖龍同志錄示。","）。"]', '["碧桃花暖洞门开，遙向春山舉一杯。","灑墨幾人鐫月牖，乘风兩度到蓬萊。","綠陰窗戶长疑雨，白石林泉半杂苔。","王事賢勞閒未得，趣归猿鹤莫相猜。","（见周喟《南雁蕩山志》卷七引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》）（按：吳璋逸诗及小傳，皆承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '游南雁蕩 吳璋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f64442-58e5-44f5-9b36-334c3f81d9a3', '因覽《寶林傳》', '因覽《寶林傳》', '605ed8b8-391e-4ef3-b79d-5e33fd85cd72', '唐', '["祖月禪風集《寶林》，二千餘載道堪尋。","雖分西國與東國，不隔人心到佛心。","迦葉最初傳去盛，慧能末後得來深。","覽期頓悟超凡衆，嗟彼常迷古與今。"]', '["祖月禪风集《寶林》，二千餘載道堪尋。","雖分西国與东国，不隔人心到佛心。","迦葉最初傳去盛，慧能末後得来深。","覽期頓悟超凡衆，嗟彼常迷古與今。"]', '诗', 'shi', '', NULL, '因覽《寶林傳》 僧潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb94d2d-e34a-42a6-b755-b3b9d0512112', '贈道者', '贈道者', '605ed8b8-391e-4ef3-b79d-5e33fd85cd72', '唐', '["一語真空出世間，可憐迷者蟻循環。","此生勝坐三禪樂，好句常吟萬事閑。","秋月圓來看盡夜，野雲散去落何山？","到頭自了方爲了，休執他經扣祖關。"]', '["一語真空出世间，可怜迷者蟻循环。","此生勝坐三禪乐，好句常吟万事闲。","秋月圓来看尽夜，野云散去落何山？","到头自了方爲了，休執他經扣祖关。"]', '诗', 'shi', '', NULL, '贈道者 僧潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e1cccf-b980-427d-b496-b78dfcaa3dbf', '贈禪客', '贈禪客', '605ed8b8-391e-4ef3-b79d-5e33fd85cd72', '唐', '["了妄歸真萬慮空，河沙凡聖體通同。","迷來盡似蛾投焰，悟去皆如鶴出籠。","片月影分千澗水，孤松聲任四時風。","直須密契心心地，休苦勞生睡夢中。","（見影宋本《景德傳燈錄》卷二九）（按：《寶林傳》爲貞元十七年釋智炬作。","僧潤時代在智炬以後。","）。"]', '["了妄归真万慮空，河沙凡聖體通同。","迷来尽似蛾投焰，悟去皆如鹤出籠。","片月影分千澗水，孤松声任四时风。","直須密契心心地，休苦勞生睡梦中。","（见影宋本《景德傳灯錄》卷二九）（按：《寶林傳》爲貞元十七年釋智炬作。","僧潤时代在智炬以後。","）。"]', '诗', 'shi', '', NULL, '贈禪客 僧潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd24a490-56ad-40b0-8fd3-11fb3737e051', '岑公洞', '岑公洞', '5816c948-54e8-4d18-bd1c-d04177a2b6b7', '唐', '["南溪有仙澗，咫尺非人間。","龍向葛陂去，鶴從遼海還。","泠泠松風下，日暮空蒼山。","（見《輿地紀勝》卷一七七《萬州》）（按：詩末有注云：「刺史馬冉《岑公洞》詩。","既曰馬冉仁才，故又謂馬仁才。","按《思州圖經》，有招慰使冉安昌，則周時有人姓冉，不可謂姓馬也。","」《全唐詩》卷七二七收此詩僅四句，今重錄。","）。"]', '["南溪有仙澗，咫尺非人间。","龙向葛陂去，鹤從遼海還。","泠泠松风下，日暮空蒼山。","（见《輿地紀勝》卷一七七《万州》）（按：诗末有注云：「刺史马冉《岑公洞》诗。","既曰马冉仁才，故又謂马仁才。","按《思州圖經》，有招慰使冉安昌，則周时有人姓冉，不可謂姓马也。","」《全唐诗》卷七二七收此诗僅四句，今重錄。","）。"]', '诗', 'shi', '', NULL, '岑公洞 馬冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29625612-b97c-4d74-8426-b2dee0110b68', '偈', '偈', '60520f16-72ac-437e-bb0e-8054cb553c17', '唐', '["一片凝然光燦爛，擬意追尋卒難見。","炳（一作「瞥」）然擲（一作「撞」）着豁人情，大事分明皆總（一作「揔成」）辦。","是（一作「實」）快活，無繫絆，萬兩黃金終不換。","任地千聖出頭來，從（一作「揔」）是向渠影中現。","（見《景德傳燈錄》卷二十。","注「一作」者，爲《五燈會元》卷十三之異文）。"]', '["一片凝然光燦爛，擬意追尋卒难见。","炳（一作「瞥」）然擲（一作「撞」）着豁人情，大事分明皆總（一作「揔成」）辦。","是（一作「實」）快活，無繫絆，万兩黄金終不換。","任地千聖出头来，從（一作「揔」）是向渠影中現。","（见《景德傳灯錄》卷二十。","注「一作」者，爲《五灯會元》卷十三之異文）。"]', '诗', 'shi', '', NULL, '偈 處真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a58646-4f82-4b72-998b-04febd355685', '', '', 'dbe5f1fc-e42f-4a50-a8b2-8286415465a8', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9a2b92-8df6-4949-9efe-bd2a577a90a6', '題王蘇蘇牕（題擬）', '題王蘇蘇牕（題擬）', 'dbe5f1fc-e42f-4a50-a8b2-8286415465a8', '唐', '["青暮花株遶戶飛，王孫尋勝引塵衣。","洞中仙子多情態，留住劉郎不放歸。","（見《北里志》）。"]', '["青暮花株遶戶飞，王孫尋勝引塵衣。","洞中仙子多情態，留住劉郎不放归。","（见《北里志》）。"]', '诗', 'shi', '', NULL, '題王蘇蘇牕（題擬） 李標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043dceda-aee2-4436-898b-a6d531bcf2c1', '端午（題擬）', '端午（題擬）', 'f9fd6299-65a4-4fa9-b78b-137dd995acb1', '唐', '["辟兵已佩銀符小，續命仍榮綵縷長。","（見《錦繡萬花谷後集》卷四《端午》）。"]', '["辟兵已佩銀符小，續命仍榮綵縷长。","（见《錦繡万花谷後集》卷四《端午》）。"]', '诗', 'shi', '', NULL, '端午（題擬） 文秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f86eda6-1c67-43d6-8b84-d97f680e9208', '松江亭（題擬）', '松江亭（題擬）', 'a2c7761f-ee57-4e36-9c5c-e3936bafccf7', '唐', '["昔年張翰此歸休，鱸膾蓴羹八月秋。","萬頃煙波閒極目，一帆風便不迴頭。","洞庭有路通仙室，笠澤無人直下鉤。","自恨宦名身未了，拂衣東去阿誰留？","（見《百城煙水》卷四）。"]', '["昔年張翰此归休，鱸膾蓴羹八月秋。","万頃煙波閒極目，一帆风便不迴头。","洞庭有路通仙室，笠澤無人直下鉤。","自恨宦名身未了，拂衣东去阿誰留？","（见《百城煙水》卷四）。"]', '诗', 'shi', '', NULL, '松江亭（題擬） 王碩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d282656e-8ac3-4207-a515-13da35d0dda5', '君山詩', '君山诗', 'a2c7761f-ee57-4e36-9c5c-e3936bafccf7', '唐', '["不饒衡嶽秀，長占洞庭心。","（見《輿地紀勝》卷六九《岳州》）。"]', '["不饒衡嶽秀，长占洞庭心。","（见《輿地紀勝》卷六九《岳州》）。"]', '诗', 'shi', '', NULL, '君山詩 王碩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd5eac1-e22a-4cf8-b0ff-0778d0076b1e', '畬山謠', '畬山謠', '4d45ce2e-2ab3-4759-9271-17ac9b4f4b3f', '唐', '["畬山兒，畬山兒（《沅湘》無此三字），無所知，年年鑿（《五燈會元》作「斫」）斷青山嵋。","就中最好衡山（《五燈會元》、《沅湘》作「嶽」）色，杉松利斧摧貞枝。","靈禽野鶴無因依，白雲迴避青煙飛。","猿猱路絕巖厓（《沅湘》作「岸」）出，芝朮（《沅湘》作「樹」）失根茅草肥，年年斫罷仍再鉏（《沅湘》作「復鋤」），千秋終是難復初。","又（《南嶽總勝集》作「由」）道今年種不多，來年更斫（《南嶽總勝集》作「明年濶斫」）當陽坡。","國家壽嶽尚如此，不知此理如之何。","（見《古今禪藻集》卷三，校以《五燈會元》卷六、《沅湘耆舊集》卷十、《南嶽總勝集》卷中，後者僅錄末四句。","又明刻本《景德傳燈錄》注收此詩）。"]', '["畬山兒，畬山兒（《沅湘》無此三字），無所知，年年鑿（《五灯會元》作「斫」）斷青山嵋。","就中最好衡山（《五灯會元》、《沅湘》作「嶽」）色，杉松利斧摧貞枝。","靈禽野鹤無因依，白云迴避青煙飞。","猿猱路絕巖厓（《沅湘》作「岸」）出，芝朮（《沅湘》作「樹」）失根茅草肥，年年斫罷仍再鉏（《沅湘》作「复鋤」），千秋終是难复初。","又（《南嶽總勝集》作「由」）道今年種不多，来年更斫（《南嶽總勝集》作「明年濶斫」）當陽坡。","国家壽嶽尚如此，不知此理如之何。","（见《古今禪藻集》卷三，校以《五灯會元》卷六、《沅湘耆旧集》卷十、《南嶽總勝集》卷中，後者僅錄末四句。","又明刻本《景德傳灯錄》注收此诗）。"]', '诗', 'shi', '', NULL, '畬山謠 玄泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997e6d25-dbae-4ee7-886a-983ec89748f8', '臨化偈 一', '臨化偈 一', '4d45ce2e-2ab3-4759-9271-17ac9b4f4b3f', '唐', '["今年六十五，四大將離主。","其道自玄玄，箇中無佛祖。"]', '["今年六十五，四大將離主。","其道自玄玄，箇中無佛祖。"]', '诗', 'shi', '', NULL, '臨化偈 一 玄泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d65f0e-6844-472a-bf07-f5292c459ca2', '臨化偈 二', '臨化偈 二', '4d45ce2e-2ab3-4759-9271-17ac9b4f4b3f', '唐', '["不同[剃]（涕）（從《五燈會元》改）頭，不用澡浴。","一堆猛火，千足萬足。","（見《祖堂集》卷九、《五燈會元》卷六）。"]', '["不同[剃]（涕）（從《五灯會元》改）头，不用澡浴。","一堆猛火，千足万足。","（见《祖堂集》卷九、《五灯會元》卷六）。"]', '诗', 'shi', '', NULL, '臨化偈 二 玄泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c44402-1d9e-4e7e-bd20-948d96801cd5', '', '', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d7ca22-e60e-4841-9ebd-a68ca5aa21df', '歲盡日二首（之二）', '歲尽日二首（之二）', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["桂花窮北陸，荆豔下東鄰。","殘粧欲送曉，薄衣已迎春。","舉袖爭流雪，分歌競繞塵。","不應將共醉，年去遠催人。","（見上海圖書館藏明抄本《古今歲時雜詠》卷四一）。"]', '["桂花窮北陸，荆豔下东鄰。","殘粧欲送晓，薄衣已迎春。","舉袖爭流雪，分歌競繞塵。","不應將共醉，年去远催人。","（见上海圖书館藏明抄本《古今歲时杂詠》卷四一）。"]', '诗', 'shi', '', NULL, '歲盡日二首（之二） 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdcfb9d-95c9-4774-870b-947f4ee459e6', '南至日', '南至日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["年年山壓壓來頻，莫強孤危競要津。","吉卦偶成開病眼，暖簷還葺寄羸身。","求仙自躁非無藥，報國當材別有人。","鬢髮堪傷白已遍，鏡中更待白眉新。","（同前書卷三九）（按：《全唐詩》卷八八五收此詩首句缺二字，今重錄。","）。"]', '["年年山壓壓来頻，莫強孤危競要津。","吉卦偶成开病眼，暖簷還葺寄羸身。","求仙自躁非無藥，報国當材別有人。","鬢髮堪傷白已遍，镜中更待白眉新。","（同前书卷三九）（按：《全唐诗》卷八八五收此诗首句缺二字，今重錄。","）。"]', '诗', 'shi', '', NULL, '南至日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd180a9-b528-450b-9bda-ce78db6f5e1b', '台州早春', '台州早春', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["微雨夜來歇，江南春色回。","已驚時不住，還恐老相催。","人好千場醉，花無百日開。","豈堪滄海畔，爲客十年來。","（見《四庫珍本初集》本《天台前集》卷下）（按：《全唐詩續補遺》卷十六據《輿地紀勝》收此詩末二句。","《全唐詩》卷一四八收作劉長卿詩，題作《早春》，但詩中海畔爲客十年之意，與劉生平不合。","任翻在台州生活時間較長，應爲其所作。","）。"]', '["微雨夜来歇，江南春色回。","已驚时不住，還恐老相催。","人好千場醉，花無百日开。","豈堪滄海畔，爲客十年来。","（见《四庫珍本初集》本《天台前集》卷下）（按：《全唐诗續補遺》卷十六據《輿地紀勝》收此诗末二句。","《全唐诗》卷一四八收作劉长卿诗，題作《早春》，但诗中海畔爲客十年之意，與劉生平不合。","任翻在台州生活时间較长，應爲其所作。","）。"]', '诗', 'shi', '', NULL, '台州早春 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b65049d-c0f2-4dcf-9a9d-939fc6c4bb53', '頌', '頌', 'dde203cf-8011-4aa0-912b-92a12c15bf61', '唐', '["好心相待人少悉，開門來去何了期。","不知達取同風事，我自修行我自知。","（《祖堂集》卷十二）。"]', '["好心相待人少悉，开门来去何了期。","不知達取同风事，我自修行我自知。","（《祖堂集》卷十二）。"]', '诗', 'shi', '', NULL, '頌 匡慧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4ac235-6a88-4d13-bd39-9bcaa3213d4e', '獻江西鍾令公', '獻江西鍾令公', '277c0081-2665-451b-a3f7-79a4d6fc40ef', '唐', '["負笈蓬飛別楚丘，旌旄影裡謁文侯。","即隨社燕來朱戶，忽聽鳴蟬泣素秋。","歲月已嗟迷進取，煙霄只望怨依投。","那堪思切溪山路，家苦簟瓢淚欲流。","（錄自民國廿九年刊龍賡言纂《萬載縣志·詩徵》）（按：題下原注：「以下採《嘉定志》補。","」《嘉定志》當指宋林護新嘉定十三年纂《宜春志》十卷集八卷。","原書久佚，《永樂大典》收入，清人尚有採擷，今不傳。","詳《中國古方志考》。","）。"]', '["負笈蓬飞別楚丘，旌旄影裡謁文侯。","即隨社燕来朱戶，忽听鳴蟬泣素秋。","歲月已嗟迷進取，煙霄只望怨依投。","那堪思切溪山路，家苦簟瓢泪欲流。","（錄自民国廿九年刊龙賡言纂《万載縣志·诗徵》）（按：題下原注：「以下採《嘉定志》補。","」《嘉定志》當指宋林護新嘉定十三年纂《宜春志》十卷集八卷。","原书久佚，《永乐大典》收入，清人尚有採擷，今不傳。","詳《中国古方志考》。","）。"]', '诗', 'shi', '', NULL, '獻江西鍾令公 劉望 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68896323-b2d9-4001-9fd5-261551495dda', '問政山', '问政山', '4e3f3e88-6677-4174-9ed6-c8624f3085f7', '唐', '["千尋練帶新安水，萬仞花屏問政山。","自少雲霞居物外，不多塵土到人間。","壺懸仙島吞舟（一作「丹」）罷，椀浸星宮沉（一作「咒」）水閑。","寶籙篋（一作「匣」）垂金絛（一作「縷」）帶，絳囊絳鎻玉連環。","靜張棋勢（一作「局」）鋪還打，默考仙經補又刪。","床並葛鞋寒兔伏，窗橫檉几老龍跧。","溪童乞火朝敲竹，山鬼聽琴夜撼閂。","草暗碧潭思句曲，松昏紫氣度[函]（深）（據《苕》改）關。","龜成[錢]（淺）（據《苕》改），甲毛猶綠，鶴化幽（一作「黳」）翎頂更殷（一作「丹」）。","阮洞神仙分藥去，蔡家兄弟寄書還。","黃精苗倒眠青鹿，紅杏枝低掛白鷴。","容易煑茶（一作「銀」）供客用，辛勤栽果與猿攀。","常尋靈穴通三島（一作「楚」），擬過流沙化百蠻。","新隱漸開（一作「聞」）侵月窟，舊林（一作「鄰」）猶悅（一作「說」）枕沙灣。","手疏俗禮慵非傲，肘護（一作「後」）靈方臂（一作「秘」）不慳。","海上使頻青鳥黠，篋中藏久白驢頑。","笻枝健杖（一作「拄」）菖蒲節，筍櫛高簪玳瑁斑。","花氣薰心香馥馥，澗聲聆耳泠（一作「響」）潺潺。","高墳自掩浮生骨，短晷難窮（一作「凋」）不死顏。","早晚重逢蕭塢客，願隨芝蓋出塵寰。","（見《增修詩話總龜》卷十五。","注一作者爲《苕溪漁隱叢詩後集》卷三十八之異文）（按：《苕溪漁隱叢話》錄本詩各句次第，與《詩話總龜》有較大不同。","茲錄其各聯韻脚以存其次第：「山」、「間」、「閑」、「關」、「丹」、「還」、「斑」、「灣」、「鷴」、「頑」、「慳」、「環」、「蠻」、「攀」、「刪」、「跧」、「閂」、「潺」、「顏」、「寰」。","又按：《增修詩話總龜》云：「歙州問政山聶道士所居，嘗有人陟險攀蘿至絕壁，於巖下嵌空處見題詩一首，雖苔蘚昏蝕，而文尚可辨，題云黃台詞，不知台何人也。","〖下錄詩，略。","〗台，國初時任屯田員外郎。","世有全篇。","」《苕溪漁隱叢話》亦以台爲「國初」人。","二本差異甚大，當一錄自石刻，一即「世有全篇」之什。","厲鶚《宋詩紀事》卷二收入本詩。","然詳繹本詩及有關記載，此詩應爲唐末任鍾傳從事之黃台所作爲是。","主要證據有：一、宋初之黃台，除《總龜》所云外，無他事迹可考。","二、問政山在歙州城外十許里，其地唐末適爲鍾傳所奄有。","黃台爲傳從事，具備作詩刻石之條件。","三、宋初避太祖諱，「殷」字亦諱，如殷全義即更名湯悅，而石刻詩中尚有「殷」字，世傳之本始易爲「丹」字，知非）（宋初人作。","四、胡仔、厲鶚均謂此詩系詠問政先生聶師道之作。","師道事詳《苕溪漁隱叢話》引山谷詩、《方輿勝覽》、《十國春秋》，爲唐末至楊吳初年人，與黃台適同時。","而問政山名或謂始於師道。","則非。","胡仔及閔嗣麟《黃山志定本》卷六均謂山名始于德晦。","德晦爲邵孫，約大和會昌間人。","）。"]', '["千尋練带新安水，万仞花屏问政山。","自少云霞居物外，不多塵土到人间。","壺懸仙島吞舟（一作「丹」）罷，椀浸星宮沉（一作「咒」）水闲。","寶籙篋（一作「匣」）垂金絛（一作「縷」）带，絳囊絳鎻玉連环。","静張棋勢（一作「局」）鋪還打，默考仙經補又刪。","床並葛鞋寒兔伏，窗橫檉几老龙跧。","溪童乞火朝敲竹，山鬼听琴夜撼閂。","草暗碧潭思句曲，松昏紫氣度[函]（深）（據《苕》改）关。","龟成[錢]（淺）（據《苕》改），甲毛猶綠，鹤化幽（一作「黳」）翎頂更殷（一作「丹」）。","阮洞神仙分藥去，蔡家兄弟寄书還。","黄精苗倒眠青鹿，紅杏枝低掛白鷴。","容易煑茶（一作「銀」）供客用，辛勤栽果與猿攀。","常尋靈穴通三島（一作「楚」），擬過流沙化百蠻。","新隐漸开（一作「闻」）侵月窟，旧林（一作「鄰」）猶悅（一作「说」）枕沙灣。","手疏俗禮慵非傲，肘護（一作「後」）靈方臂（一作「秘」）不慳。","海上使頻青鸟黠，篋中藏久白驢頑。","笻枝健杖（一作「拄」）菖蒲節，筍櫛高簪玳瑁斑。","花氣薰心香馥馥，澗声聆耳泠（一作「响」）潺潺。","高墳自掩浮生骨，短晷难窮（一作「凋」）不死顏。","早晚重逢蕭塢客，願隨芝蓋出塵寰。","（见《增修诗話總龟》卷十五。","注一作者爲《苕溪漁隐叢诗後集》卷三十八之異文）（按：《苕溪漁隐叢話》錄本诗各句次第，與《诗話總龟》有較大不同。","茲錄其各聯韻脚以存其次第：「山」、「间」、「闲」、「关」、「丹」、「還」、「斑」、「灣」、「鷴」、「頑」、「慳」、「环」、「蠻」、「攀」、「刪」、「跧」、「閂」、「潺」、「顏」、「寰」。","又按：《增修诗話總龟》云：「歙州问政山聶道士所居，嘗有人陟險攀蘿至絕壁，於巖下嵌空处见題诗一首，雖苔蘚昏蝕，而文尚可辨，題云黄台词，不知台何人也。","〖下錄诗，略。","〗台，国初时任屯田員外郎。","世有全篇。","」《苕溪漁隐叢話》亦以台爲「国初」人。","二本差異甚大，當一錄自石刻，一即「世有全篇」之什。","厲鶚《宋诗紀事》卷二收入本诗。","然詳繹本诗及有关記載，此诗應爲唐末任鍾傳從事之黄台所作爲是。","主要證據有：一、宋初之黄台，除《總龟》所云外，無他事迹可考。","二、问政山在歙州城外十許里，其地唐末適爲鍾傳所奄有。","黄台爲傳從事，具備作诗刻石之條件。","三、宋初避太祖諱，「殷」字亦諱，如殷全義即更名湯悅，而石刻诗中尚有「殷」字，世傳之本始易爲「丹」字，知非）（宋初人作。","四、胡仔、厲鶚均謂此诗系詠问政先生聶師道之作。","師道事詳《苕溪漁隐叢話》引山谷诗、《方輿勝覽》、《十国春秋》，爲唐末至楊吳初年人，與黄台適同时。","而问政山名或謂始於師道。","則非。","胡仔及閔嗣麟《黄山志定本》卷六均謂山名始于德晦。","德晦爲邵孫，約大和會昌间人。","）。"]', '诗', 'shi', '', NULL, '問政山 黃台 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2f57710-c7e2-496f-b8c8-94560a3dda87', '貞女石（相傳秦時有數女遊，卒遇風雨，一女化爲石。）', '貞女石（相傳秦时有數女游，卒遇风雨，一女化爲石。）', '43bca173-bd00-4ff8-86f5-73208fd530a3', '唐', '["當時非望夫，亦不採蘼蕪，自化爲貞質，因茲入畫圖。","風恬潭鏡朗，雲散石房孤。","寄語郴江婦，初心相似無。","（見清黃子高輯《粤詩蒐逸》卷一，注出《連州志》）。"]', '["當时非望夫，亦不採蘼蕪，自化爲貞質，因茲入畫圖。","风恬潭镜朗，云散石房孤。","寄語郴江婦，初心相似無。","（见清黄子高輯《粤诗蒐逸》卷一，注出《連州志》）。"]', '诗', 'shi', '', NULL, '貞女石（相傳秦時有數女遊，卒遇風雨，一女化爲石。） 張鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b470ee86-ae30-46bf-b809-512eb4ff6cbe', '題黎少府宅紅蕉花', '題黎少府宅紅蕉花', '6cf7046e-8ad6-4495-b98b-fa50c65c05a0', '唐', '["不爭桃李豔陽天，真對羣芳想更妍。","秋卷火旗閑度日，晝凝紅燭靜無煙。","肯於萍實誇顏色，要與芙蓉較後先。","須信晚成翻有遇，赤心偏得主人憐。","（見同治十一年刊錫榮纂《萍鄉縣志》卷六）（按：《萍鄉縣志》同卷有唐廩《夏日書黎少府山齋》，因知咸與唐廩爲同時人。","唐爲乾甯元年進士。","今人張彥生《善本碑帖錄》第三卷記曲阜博物館藏《唐兗公頌碑》碑側刻大和九年張咸題名，與此詩作者恐非一人。","）。"]', '["不爭桃李豔陽天，真对羣芳想更妍。","秋卷火旗闲度日，晝凝紅燭静無煙。","肯於萍實誇顏色，要與芙蓉較後先。","須信晚成翻有遇，赤心偏得主人怜。","（见同治十一年刊錫榮纂《萍乡縣志》卷六）（按：《萍乡縣志》同卷有唐廩《夏日书黎少府山斋》，因知咸與唐廩爲同时人。","唐爲乾甯元年進士。","今人張彥生《善本碑帖錄》第三卷記曲阜博物館藏《唐兗公頌碑》碑側刻大和九年張咸題名，與此诗作者恐非一人。","）。"]', '诗', 'shi', '', NULL, '題黎少府宅紅蕉花 張咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3f272f-97f7-4875-9049-bbe7d7f506a8', '九疑山', '九疑山', 'cdec67ae-9862-4672-ac34-afbcbdf7b595', '唐', '["天放煙晴繞四圍，九峯高處彩雲飛。","仙壇丹竈靈猶在，鶴駕青霄去不歸。","晉末幾遷風景別，塵中空換子孫非。","松花落盡無消息，夜半疏鐘徹翠微。","（康熙《萍鄉縣志》卷五、同治《萍鄉縣志》卷六）（按：《全唐詩》卷六六七收鄭啓《鄧表山》詩，首二句幾全異，後六句大致相同。","）。"]', '["天放煙晴繞四圍，九峯高处彩云飞。","仙壇丹竈靈猶在，鹤駕青霄去不归。","晉末幾遷风景別，塵中空換子孫非。","松花落尽無消息，夜半疏鐘徹翠微。","（康熙《萍乡縣志》卷五、同治《萍乡縣志》卷六）（按：《全唐诗》卷六六七收鄭啓《鄧表山》诗，首二句幾全異，後六句大致相同。","）。"]', '诗', 'shi', '', NULL, '九疑山 鄭啓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e2b6cd-2f67-416e-8784-43b052408a74', '柳花（題擬）', '柳花（題擬）', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["本是無情花，南飛又北飛。","（見《全芳備祖前集》卷十八）。"]', '["本是無情花，南飞又北飞。","（见《全芳備祖前集》卷十八）。"]', '诗', 'shi', '', NULL, '柳花（題擬） 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929146f1-6660-45eb-ae51-e769d23e3345', '春日早朝', '春日早朝', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["三嚴（一作「年」）望仗正徘徊，曙色盈盈正（一作「金」）殿開。","青瑣侍香扶日出，紫霞護闕擁山來。","班聯鵷鷺仙官舞，影動龍蛇淑氣催。","禁祕天顏常咫尺，小臣（一作「欣忭」）願進萬年杯。"]', '["三嚴（一作「年」）望仗正徘徊，曙色盈盈正（一作「金」）殿开。","青瑣侍香扶日出，紫霞護闕擁山来。","班聯鵷鷺仙官舞，影动龙蛇淑氣催。","禁祕天顏常咫尺，小臣（一作「欣忭」）願進万年杯。"]', '诗', 'shi', '', NULL, '春日早朝 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('219aef43-49d5-49f4-9899-e3e3c5cf7b11', '長信宮', '长信宮', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["一從同輦辭君寵，已分齊紈賦妾詩。","別院花紅休悵望（一作「恨」），亦曾開在阿嬌時。","（以上二首均見嘉慶元年刊戚鶴泉編《三台詩錄》卷一、光緒二十年刊王棻纂《光緒仙居志》附《仙居集》卷十九。","注一作者，爲張靖龍同志所錄示之異文。","）。"]', '["一從同輦辞君寵，已分齊紈賦妾诗。","別院花紅休悵望（一作「恨」），亦曾开在阿嬌时。","（以上二首均见嘉慶元年刊戚鹤泉編《三台诗錄》卷一、光緒二十年刊王棻纂《光緒仙居志》附《仙居集》卷十九。","注一作者，爲張靖龙同志所錄示之異文。","）。"]', '诗', 'shi', '', NULL, '長信宮 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7d1a66-7d8b-4a12-9f03-0d2e4db1463f', '宮詞二首 一', '宮词二首 一', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["楊柳宮邊日已斜，歌聲猶按《後庭花》。","不知春思當誰似，青黛娥眉奪麗華。"]', '["楊柳宮邊日已斜，歌声猶按《後庭花》。","不知春思當誰似，青黛娥眉奪丽华。"]', '诗', 'shi', '', NULL, '宮詞二首 一 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d71193f-10f1-422c-8e2e-d35470b98619', '宮詞二首 二', '宮词二首 二', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["雙雙紫燕語呢喃，怪引春宮夢不甘。","聞道君王多惜玉，肯教自碎碧鸞簪。","（詳附按。","此二首承張靖龍同志錄示。","）（按：張靖龍同志錄孫郃四詩見示，並附按語云：「以上詩見清王魏勝《安洲語錄》卷一。","清戚學標《三台詩錄》云：『郃有《早朝詩》，冠冕矞皇，王岑遺范。","頸聯〖應爲頷聯〗云：「青瑣傳香扶日出，紫雲護闕擁山來。","」其雲日字與春早互映尤佳。","』張壽鏞《張拾遺外紀》中云：『董竹史先生慶酉輯《四明詩幹》三卷，錄拾遺詩《古意二首》，《哭玄英方干先生詩》一首，末載《三台詩錄》語。","然則拾遺詩幸存於《唐文粹》而戚氏得錄之，獨恨其少耳。","』詳見張壽鏞輯《孫拾遺文纂》一卷《補遺外紀》一卷，《四明叢書》第二集第一冊。","」）。"]', '["雙雙紫燕語呢喃，怪引春宮梦不甘。","闻道君王多惜玉，肯教自碎碧鸾簪。","（詳附按。","此二首承張靖龙同志錄示。","）（按：張靖龙同志錄孫郃四诗见示，並附按語云：「以上诗见清王魏勝《安洲語錄》卷一。","清戚学標《三台诗錄》云：『郃有《早朝诗》，冠冕矞皇，王岑遺范。","頸聯〖應爲頷聯〗云：「青瑣傳香扶日出，紫云護闕擁山来。","」其云日字與春早互映尤佳。","』張壽鏞《張拾遺外紀》中云：『董竹史先生慶酉輯《四明诗幹》三卷，錄拾遺诗《古意二首》，《哭玄英方干先生诗》一首，末載《三台诗錄》語。","然則拾遺诗幸存於《唐文粹》而戚氏得錄之，独恨其少耳。","』詳见張壽鏞輯《孫拾遺文纂》一卷《補遺外紀》一卷，《四明叢书》第二集第一冊。","」）。"]', '诗', 'shi', '', NULL, '宮詞二首 二 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9aa810-afe2-481f-abe7-4485e273c9b0', '', '', 'a4e92dbb-ac4d-478f-ab82-0c59b1093ed5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 黃璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac980a8-b6ca-46ab-ab98-483b026baa4b', '題玉泉', '題玉泉', 'a4e92dbb-ac4d-478f-ab82-0c59b1093ed5', '唐', '["水性能方圓，泉色常珪壁。","雲山靜有輝。","瓊液來無跡。","泉上修禪人，曹溪分一滴。","鑑止更澄源，紛紛萬緣息。","（見《嘉定赤城志》卷二十三）。"]', '["水性能方圓，泉色常珪壁。","云山静有輝。","瓊液来無跡。","泉上修禪人，曹溪分一滴。","鑑止更澄源，紛紛万緣息。","（见《嘉定赤城志》卷二十三）。"]', '诗', 'shi', '', NULL, '題玉泉 黃璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ce327e-4c8c-4fbb-886e-52862b3ae281', '偈', '偈', '372a86d0-7657-4571-81f1-de21b4d63a07', '唐', '["龍光山頂寶月輪，照耀乾坤爍暗雲。","尊者不移元一質，千江影現萬家春。","（見《景德傳燈錄》卷二十、《五燈會元》卷十三。","前者但稱龍光和尚，今從後書。","）。"]', '["龙光山頂寶月輪，照耀乾坤爍暗云。","尊者不移元一質，千江影現万家春。","（见《景德傳灯錄》卷二十、《五灯會元》卷十三。","前者但稱龙光和尚，今從後书。","）。"]', '诗', 'shi', '', NULL, '偈 諲禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c03ec3-2171-40d4-89d5-9849cbb5a2c0', '題狄梁公廟', '題狄梁公廟', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["惟公仗高節，爲國立儲皇。","（見《詩學指南》本《詩中旨格》。","《吟窗雜錄》本作者名缺「貞」字。","）。"]', '["惟公仗高節，爲国立儲皇。","（见《诗学指南》本《诗中旨格》。","《吟窗杂錄》本作者名缺「貞」字。","）。"]', '诗', 'shi', '', NULL, '題狄梁公廟 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c3fd2d-3c7f-4c3f-91b2-de06af25899f', '', '', '39d7382c-82c6-4f8e-863d-f15684c4b51e', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 吳畦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43856886-e1d1-4f61-93b1-32b0e72ee05e', '登鴈蕩明王峰詩', '登鴈蕩明王峰诗', '39d7382c-82c6-4f8e-863d-f15684c4b51e', '唐', '["明王嶻嶪與天齊，勢壓諸峰不可梯。","霽雨孤鐘雲外渡，叫霜羣鴈月中棲。","仰觀碧落星辰近，俯視紅塵世界低。","七尺靈光雙彩展，石門金鼎謾留題。","（見同治丙寅刊齊召南修《溫州府志》卷二十八）（〖1〗同治《溫州府志》卷二十《名臣》錄《萬曆志》云：「吳畦，字正祥，家安國之盧村。","登進士第。","乾符中，爲河南節度使，督修黃河有功。","黃巢亂，奉勅破走之。","中和二年召入朝，同平章事。","文德元年，拜諫議大夫，進太子太保，封光祿大夫，勳柱國。","論事忤上意，貶潤州刺史。","會錢鏐爲鎮海節度使，不安其職，遂引退，家居而卒。","」出將入相如此，而史家闕如，甚爲可疑，今不取。","張靖龍云：「見周喟《南雁蕩山志》卷七《詩外編》引明人鄭思恭《崇禎南雁蕩山志》，又見《乾隆平陽縣志》卷二。","明王峯在白雲山〖屬南雁蕩山〗。","」）。"]', '["明王嶻嶪與天齊，勢壓諸峰不可梯。","霽雨孤鐘云外渡，叫霜羣鴈月中棲。","仰观碧落星辰近，俯視紅塵世界低。","七尺靈光雙彩展，石门金鼎謾留題。","（见同治丙寅刊齊召南修《溫州府志》卷二十八）（〖1〗同治《溫州府志》卷二十《名臣》錄《万曆志》云：「吳畦，字正祥，家安国之盧村。","登進士第。","乾符中，爲河南節度使，督修黄河有功。","黄巢亂，奉勅破走之。","中和二年召入朝，同平章事。","文德元年，拜諫議大夫，進太子太保，封光祿大夫，勳柱国。","論事忤上意，貶潤州刺史。","會錢鏐爲鎮海節度使，不安其職，遂引退，家居而卒。","」出將入相如此，而史家闕如，甚爲可疑，今不取。","張靖龙云：「见周喟《南雁蕩山志》卷七《诗外編》引明人鄭思恭《崇禎南雁蕩山志》，又见《乾隆平陽縣志》卷二。","明王峯在白云山〖屬南雁蕩山〗。","」）。"]', '诗', 'shi', '', NULL, '登鴈蕩明王峰詩 吳畦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a1dd17-c660-4a24-a590-7edd4f2647d9', '過荆山', '過荆山', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["無人分玉石，有路即荆榛。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["無人分玉石，有路即荆榛。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '過荆山 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ca0de6-f84a-46d0-959b-6745c0a706a6', '野望', '野望', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["柳色舞春水，花陰香客衣。","（同前）。"]', '["柳色舞春水，花陰香客衣。","（同前）。"]', '诗', 'shi', '', NULL, '野望 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5915a23e-f894-4ccd-b473-606247370ad7', '句', '句', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["魚弄晴波影上簾。","（見宋陳善《捫蝨新話》上集卷一）。"]', '["鱼弄晴波影上簾。","（见宋陳善《捫蝨新話》上集卷一）。"]', '诗', 'shi', '', NULL, '句 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50e1641-b908-4a6c-9138-f9b80c3ac52b', '富春二首（之二）', '富春二首（之二）', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["兩岸山花中有溪，山花紅白偏高低。","靈源忽若乘槎到，仙洞還同採藥迷。","二月辛夷猶未落，五更鴉舅最先啼。","茶煙漁火遙看處，一片人家在水西。","（見《唐音戊籤》八十一〖《統籤》卷七三四〗）。"]', '["兩岸山花中有溪，山花紅白偏高低。","靈源忽若乘槎到，仙洞還同採藥迷。","二月辛夷猶未落，五更鴉舅最先啼。","茶煙漁火遙看处，一片人家在水西。","（见《唐音戊籤》八十一〖《統籤》卷七三四〗）。"]', '诗', 'shi', '', NULL, '富春二首（之二） 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9856c758-9bae-4731-801a-eed15e3b16c8', '自遣', '自遣', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["幾年曾見舊江村，樹有交柯犢有孫。","深感下峰顏色好，晚雲纔散又當門。","（見《竹莊詩話》卷十五引郭思《瑤谿集》、《能改齋漫錄》卷八錄後二句）。"]', '["幾年曾见旧江村，樹有交柯犢有孫。","深感下峰顏色好，晚云纔散又當门。","（见《竹莊诗話》卷十五引郭思《瑤谿集》、《能改斋漫錄》卷八錄後二句）。"]', '诗', 'shi', '', NULL, '自遣 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17c930d-3517-4db9-8d7d-63e5b3c15c32', '杏花', '杏花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["春意竟相妬，杏花應最嬌。","紅輕欲愁殺，粉薄似啼消。","願作年華夢，翩翩遶此條。","（《全芳備祖前集》卷十《杏花》）。"]', '["春意竟相妬，杏花應最嬌。","紅轻欲愁殺，粉薄似啼消。","願作年华梦，翩翩遶此條。","（《全芳備祖前集》卷十《杏花》）。"]', '诗', 'shi', '', NULL, '杏花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('027308ea-aea0-447c-b1e5-30d971472026', '悼孟昭圖（題擬）', '悼孟昭圖（題擬）', '8e07b7c0-faa3-4e0d-be86-adbc26adbb00', '唐', '["一何罪死一何名，獨向湘江弔屈平。","從此蜀川春夜月，杜鵑啼作兩般聲。","（周校本《詩話總龜》卷四五引盧瓌《抒情》）（按：盧瓌《抒情》云：「僖宗幸蜀，拾遺孟昭門上疏切直，蹈于非罪。","時狄常侍歸蜀，以詩悼之曰〖詩略〗。","」《全唐詩》卷六○○據《南部新書》卷己、《唐詩紀事》卷六八等書所引，收歸裴澈名下。","《抒情詩》成書較早，詩句差異較大，故兩存之。","狄常侍，疑即狄歸昌。","昭門，顯爲昭圖之誤。","《全唐詩》作「孟昌圖」，亦未諦。","）。"]', '["一何罪死一何名，独向湘江弔屈平。","從此蜀川春夜月，杜鵑啼作兩般声。","（周校本《诗話總龟》卷四五引盧瓌《抒情》）（按：盧瓌《抒情》云：「僖宗幸蜀，拾遺孟昭门上疏切直，蹈于非罪。","时狄常侍归蜀，以诗悼之曰〖诗略〗。","」《全唐诗》卷六○○據《南部新书》卷己、《唐诗紀事》卷六八等书所引，收归裴澈名下。","《抒情诗》成书較早，诗句差異較大，故兩存之。","狄常侍，疑即狄归昌。","昭门，显爲昭圖之誤。","《全唐诗》作「孟昌圖」，亦未諦。","）。"]', '诗', 'shi', '', NULL, '悼孟昭圖（題擬） 狄常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0431e34-d65c-4f04-a194-0b8e6d3b2ccb', '雪', '雪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["客來迷舊徑，虎過識新蹤。","浦近渾無鶴，林疏只有松。","（《分門纂類唐宋時賢千家詩選》卷十三）。"]', '["客来迷旧徑，虎過識新蹤。","浦近渾無鹤，林疏只有松。","（《分门纂類唐宋时賢千家诗選》卷十三）。"]', '诗', 'shi', '', NULL, '雪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a890f87-2368-4923-bac2-c4198966f516', '贈齊己（題擬）', '贈齊己（題擬）', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["敲門誰訪□，□客即□師。","應是逢新雪，高吟得好詩。","格清無俗字，思苦有蒼髭。","諷味但忘倦，拋琴復捨碁。","（見《四部叢刊》本《白蓮集》卷首孫光憲《白蓮集序》引。","此首承趙昌平同志錄志。","）（〖1〗《白蓮集序》：「鄭谷郎中與師□□□□□□〖下引詩，略〗其爲詩家流之之稱許也如此。","」）。"]', '["敲门誰訪□，□客即□師。","應是逢新雪，高吟得好诗。","格清無俗字，思苦有蒼髭。","諷味但忘倦，拋琴复捨碁。","（见《四部叢刊》本《白蓮集》卷首孫光憲《白蓮集序》引。","此首承趙昌平同志錄志。","）（〖1〗《白蓮集序》：「鄭谷郎中與師□□□□□□〖下引诗，略〗其爲诗家流之之稱許也如此。","」）。"]', '诗', 'shi', '', NULL, '贈齊己（題擬） 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0dcdc8-16d9-4aa3-a6a6-333961fa42b1', '荷花（題擬）', '荷花（題擬）', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["佛愛我亦愛，清香蝶不偷。","一般奇特處，不上婦人頭。","（見《全芳備祖前集》卷十一）。"]', '["佛愛我亦愛，清香蝶不偷。","一般奇特处，不上婦人头。","（见《全芳備祖前集》卷十一）。"]', '诗', 'shi', '', NULL, '荷花（題擬） 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e60921-41c7-4802-8230-cc189e216ead', '筆峰', '笔峰', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["似筆挺然秀，山川亦好文。","宕渠花裏發，秦壠竹間分。","石臼生春水，香龕積暮雲。","道經難久住，日後憶離羣。","（見民國十七年刊曾瀛藻纂《大竹縣志》卷十四）。"]', '["似笔挺然秀，山川亦好文。","宕渠花裏發，秦壠竹间分。","石臼生春水，香龕積暮云。","道經难久住，日後憶離羣。","（见民国十七年刊曾瀛藻纂《大竹縣志》卷十四）。"]', '诗', 'shi', '', NULL, '筆峰 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33608b7-3ca2-4093-8a72-bd51c3f5a4ab', '春日即事', '春日即事', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["典衣估酒得，伴客看閒花。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["典衣估酒得，伴客看閒花。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '春日即事 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d84dca-e3b3-4cb9-b53e-8f5e9eda551f', '秋扇', '秋扇', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["汗流浹背曾施力，氣爽中宵便負心。","（同前）。"]', '["汗流浹背曾施力，氣爽中宵便負心。","（同前）。"]', '诗', 'shi', '', NULL, '秋扇 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62152f05-6664-4b67-8868-6e5bcaf6504f', '贈王貞白', '贈王貞白', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["殿前新進士，闕下校書郎。","（《唐才子傳》卷九。","此則承陶先生見告）。"]', '["殿前新進士，闕下校书郎。","（《唐才子傳》卷九。","此則承陶先生见告）。"]', '诗', 'shi', '', NULL, '贈王貞白 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67b49e4-f27d-4a20-8f51-d814424eaa2d', '秋夜雨中', '秋夜雨中', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["秋風唯苦吟，舉世少知音。","窗前三更雨，燈前萬里心。","（金東勳云見《東文選》卷十九）。"]', '["秋风唯苦吟，舉世少知音。","窗前三更雨，灯前万里心。","（金东勳云见《东文選》卷十九）。"]', '诗', 'shi', '', NULL, '秋夜雨中 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d15c52-03c6-4fd6-9d9e-92a818944286', '登潤州慈和寺上房', '登潤州慈和寺上房', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["登臨蹔隔路歧塵，吟想興亡恨益新。","畫角聲中朝暮浪，青山影裏古今人。","霜摧玉樹花無主，風暖金陵草自春。","賴有謝家餘景在，常叫詞客爽精神。"]', '["登臨蹔隔路歧塵，吟想兴亡恨益新。","畫角声中朝暮浪，青山影裏古今人。","霜摧玉樹花無主，风暖金陵草自春。","賴有謝家餘景在，常叫词客爽精神。"]', '诗', 'shi', '', NULL, '登潤州慈和寺上房 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad35ed7f-050f-462a-8f44-e885604c21da', '送吳進士巒歸江南', '送吳進士巒归江南', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["自識君來幾度別，此回相別恨重重。","干戈到處方多事，詩酒何時得再逢。","遠樹參差江畔路，寒雲零落馬前峰。","行行遇景傳新作，莫學嵇康盡放慵。"]', '["自識君来幾度別，此回相別恨重重。","干戈到处方多事，诗酒何时得再逢。","远樹參差江畔路，寒云零落马前峰。","行行遇景傳新作，莫学嵇康尽放慵。"]', '诗', 'shi', '', NULL, '送吳進士巒歸江南 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9735c8df-8694-420a-aaa8-15aa383799cd', '秋日再經盱眙縣寄李長官', '秋日再經盱眙縣寄李长官', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["孤蓬再此接恩輝，吟對秋風悵有違。","門柳己凋新歲葉，旅人猶着去年衣。","路迷霄漢愁中老，家隔煙波夢裏歸。","自歎身如春社燕，畫樑高處又來飛。"]', '["孤蓬再此接恩輝，吟对秋风悵有違。","门柳己凋新歲葉，旅人猶着去年衣。","路迷霄漢愁中老，家隔煙波梦裏归。","自歎身如春社燕，畫樑高处又来飞。"]', '诗', 'shi', '', NULL, '秋日再經盱眙縣寄李長官 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae7610dd-8d76-465a-8910-8829541ed760', '暮春即事和顧雲友使', '暮春即事和顧云友使', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["東風遍閱百般香，意緒偏饒柳帶長。","蘇武書回深塞盡，莊周夢逐落花忙。","好憑殘景朝朝醉，難把離心寸寸量。","正是浴沂時節日，舊遊魂斷白雲鄉。","（以上五首錄自《社會科學戰線》一九八四年第四期刊何鳴雁《新羅詩人崔致遠》一文）。"]', '["东风遍閱百般香，意緒偏饒柳带长。","蘇武书回深塞尽，莊周梦逐落花忙。","好憑殘景朝朝醉，难把離心寸寸量。","正是浴沂时節日，旧游魂斷白云乡。","（以上五首錄自《社會科学戰線》一九八四年第四期刊何鳴雁《新羅诗人崔致远》一文）。"]', '诗', 'shi', '', NULL, '暮春即事和顧雲友使 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5962b101-ae0e-4d47-aab2-a39c6403c264', '山陽與鄉友話別', '山陽與乡友話別', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["相逢暫樂楚山春，又欲分離淚滿巾。","莫怪臨風偏悵望，異鄉難遇故鄉人。","（《東文選》卷十九）。"]', '["相逢暫乐楚山春，又欲分離泪满巾。","莫怪臨风偏悵望，異乡难遇故乡人。","（《东文選》卷十九）。"]', '诗', 'shi', '', NULL, '山陽與鄉友話別 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42429ee9-5f37-4f34-a673-982678dfcad7', '古意', '古意', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["狐能化美女，狸亦作書生。","誰知異物類，幻惑同人形。","變化尚非艱，操心良獨難。","欲辨真與僞，願磨心鏡看。","（同前卷四）。"]', '["狐能化美女，狸亦作书生。","誰知異物類，幻惑同人形。","变化尚非艱，操心良独难。","欲辨真與僞，願磨心镜看。","（同前卷四）。"]', '诗', 'shi', '', NULL, '古意 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38155bc4-868f-44ff-b9f0-ab116d861f14', '江南女', '江南女', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["江南蕩風俗，養女嬌且憐。","性冶耻針線，妝成調管弦。","所學非雅音，多被春心牽。","自謂芳華色，長占艷陽年。","却笑鄰家女，終朝弄機杼。","機杼縱勞身，羅衣不到汝。","（同前）。"]', '["江南蕩风俗，養女嬌且怜。","性冶耻針線，妝成調管弦。","所学非雅音，多被春心牽。","自謂芳华色，长占艷陽年。","却笑鄰家女，終朝弄機杼。","機杼縱勞身，羅衣不到汝。","（同前）。"]', '诗', 'shi', '', NULL, '江南女 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02fe492-cef9-43ff-a99e-36edbe385843', '寓興', '寓兴', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["願言扃利門，不使損遺體。","爭奈探珠者，輕生入海底。","心榮塵易染，心垢正難洗。","澹泊與誰論，世路嗜甘醴。","（同前）。"]', '["願言扃利门，不使損遺體。","爭奈探珠者，轻生入海底。","心榮塵易染，心垢正难洗。","澹泊與誰論，世路嗜甘醴。","（同前）。"]', '诗', 'shi', '', NULL, '寓興 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a338d9-290d-4161-9eb2-2be1af506c03', '蜀葵花', '蜀葵花', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["寂寞荒田側，繁花壓柔枝。","香輕梅雨歇，影帶麥風欹。","車馬誰見賞，蜂蝶徒相窺。","自慚生地賤，堪恨人棄遺。","（同前。","以上五首皆錄自《中央民族學院學報》一九八五年第一期刊金東勳《晚唐著名詩人崔致遠》一文）。"]', '["寂寞荒田側，繁花壓柔枝。","香轻梅雨歇，影带麦风欹。","车马誰见賞，蜂蝶徒相窺。","自慚生地賤，堪恨人棄遺。","（同前。","以上五首皆錄自《中央民族学院学報》一九八五年第一期刊金东勳《晚唐著名诗人崔致远》一文）。"]', '诗', 'shi', '', NULL, '蜀葵花 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66902634-b5dc-4888-a4d0-019d93afd78f', '夢中作', '梦中作', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["糞墻師有誡，經笥我無慙。","亂世成何事，唯添七不堪。","（《大正藏》本《唐大薦福寺故寺主翻經大德法藏和尚傳》）（按：此詩爲崔致遠天復四年春夢中遇宰予、邊孝先二賢，前二句爲二賢句，後二句爲崔續成之。","按：崔致遠歸國後詩，今獲見十一首，附錄於次，以便參考。","）。"]', '["糞墻師有誡，經笥我無慙。","亂世成何事，唯添七不堪。","（《大正藏》本《唐大薦福寺故寺主翻經大德法藏和尚傳》）（按：此诗爲崔致远天复四年春梦中遇宰予、邊孝先二賢，前二句爲二賢句，後二句爲崔續成之。","按：崔致远归国後诗，今獲见十一首，附錄於次，以便參考。","）。"]', '诗', 'shi', '', NULL, '夢中作 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04406278-b18b-4a06-835c-42fa5fecbcd1', '題伽倻山讀書堂瀑布', '題伽倻山读书堂瀑布', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["狂噴壘石吼重巒，人語難分咫尺間。","常恐是非聲到耳，故教流水盡籠山。","（何鳴雁文引。","又見《新增東國輿地勝覽》卷三十）。"]', '["狂噴壘石吼重巒，人語难分咫尺间。","常恐是非声到耳，故教流水尽籠山。","（何鳴雁文引。","又见《新增东国輿地勝覽》卷三十）。"]', '诗', 'shi', '', NULL, '題伽倻山讀書堂瀑布 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c080567-c543-4f0f-a1b1-c783a397d881', '鄉樂雜詠五首 金丸', '乡乐杂詠五首 金丸', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["迴身掉臂弄金丸，月轉星浮滿眼看。","縱有宜僚那勝此，定知鯨海息波瀾。"]', '["迴身掉臂弄金丸，月轉星浮满眼看。","縱有宜僚那勝此，定知鯨海息波瀾。"]', '诗', 'shi', '', NULL, '鄉樂雜詠五首 金丸 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e44cb95-1cf7-4687-bcab-705f24a2b2ed', '鄉樂雜詠五首 月顛', '乡乐杂詠五首 月顛', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["肩高項縮髮崔嵬，攘臂羣儒鬬酒盃。","聽得歌聲人盡笑，夜頭旗幟曉頭催。"]', '["肩高項縮髮崔嵬，攘臂羣儒鬬酒盃。","听得歌声人尽笑，夜头旗幟晓头催。"]', '诗', 'shi', '', NULL, '鄉樂雜詠五首 月顛 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533487dd-4d88-4d15-899b-32f5bcd8cfb7', '鄉樂雜詠五首 大面', '乡乐杂詠五首 大面', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["黃金面色是其人，手抱珠鞭役鬼神。","疾步徐趍呈雅舞，宛如丹鳳舞堯春。"]', '["黄金面色是其人，手抱珠鞭役鬼神。","疾步徐趍呈雅舞，宛如丹鳳舞堯春。"]', '诗', 'shi', '', NULL, '鄉樂雜詠五首 大面 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804becb2-16d1-431c-b205-7980c2445c94', '鄉樂雜詠五首 束毒', '乡乐杂詠五首 束毒', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["蓬頭藍面異人間，押隊來庭學舞鸞。","打鼓冬冬風瑟瑟，南奔北躍也無端。"]', '["蓬头藍面異人间，押隊来庭学舞鸾。","打鼓冬冬风瑟瑟，南奔北躍也無端。"]', '诗', 'shi', '', NULL, '鄉樂雜詠五首 束毒 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810d0298-1abf-42e2-85e0-801dfe762534', '鄉樂雜詠五首 狻猊', '乡乐杂詠五首 狻猊', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["遠涉流沙萬里來，毛衣破盡着塵埃。","搖頭擺尾馴仁德，雄氣寧同百獸才。","（《三國史記》卷三二）。"]', '["远涉流沙万里来，毛衣破尽着塵埃。","搖头擺尾馴仁德，雄氣寧同百獸才。","（《三国史記》卷三二）。"]', '诗', 'shi', '', NULL, '鄉樂雜詠五首 狻猊 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78e13878-40f4-4110-8589-1000402027fc', '寄顥源上人', '寄顥源上人', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["終日低頭弄筆端，從人杜口話心難。","遠離塵世雖堪喜，爭奈風情未肯闌。","影鬬晴霞紅葉徑，聲連夜雨白雲湍。","吟魂對景無羇絆，四海深機憶道安。","（《新增東國輿地勝覽》卷三十）。"]', '["終日低头弄笔端，從人杜口話心难。","远離塵世雖堪喜，爭奈风情未肯闌。","影鬬晴霞紅葉徑，声連夜雨白云湍。","吟魂对景無羇絆，四海深機憶道安。","（《新增东国輿地勝覽》卷三十）。"]', '诗', 'shi', '', NULL, '寄顥源上人 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('931fced3-e35c-4b6a-ae80-f9cea62f01f1', '贈金川寺主', '贈金川寺主', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["白雲溪畔創仁寺，三十年來此住持。","笑指門前一條路，纔離山下有千歧。","（《東文選》卷十九）。"]', '["白云溪畔創仁寺，三十年来此住持。","笑指门前一條路，纔離山下有千歧。","（《东文選》卷十九）。"]', '诗', 'shi', '', NULL, '贈金川寺主 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd33da5-b179-4f6a-9e89-d7134989f533', '入山詩', '入山诗', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["僧乎莫道青山好，山好何事更出山。","試看他日吾蹤跡，一入青山更不還。","（見《漢詩選集》。","以上二首錄自金東勳文。","）。"]', '["僧乎莫道青山好，山好何事更出山。","試看他日吾蹤跡，一入青山更不還。","（见《漢诗選集》。","以上二首錄自金东勳文。","）。"]', '诗', 'shi', '', NULL, '入山詩 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b03652-9ffb-4173-b629-cc994c9558e1', '智異山花開洞', '智異山花开洞', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["東國花開洞，壺中別有天。","仙人推玉枕，身世倏千年。","（見趙書印編《韓國文苑》卷七，注出《擇里志》題注云：「宣廟時有僧得之巖石間云。","」）。"]', '["东国花开洞，壺中別有天。","仙人推玉枕，身世倏千年。","（见趙书印編《韓国文苑》卷七，注出《擇里志》題注云：「宣廟时有僧得之巖石间云。","」）。"]', '诗', 'shi', '', NULL, '智異山花開洞 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c666833-fbc0-4cec-95f2-5663400c5d86', '臨鏡臺', '臨镜台', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["烟巒簇簇水溶溶，鏡裏人家對碧峰。","何處孤帆飽風去，瞥然飛鳥杳無踪。","（錄自韋旭升《朝鮮文學史》）（按：據金東勳說，崔詩除《全唐詩逸》及《桂苑筆耕集》〖已收《全唐詩補逸》〗所收外，《三國史記》存五首，《東文選》收三十首，另見於石刻、方志者尚有十餘首，共存百首左右。","今所得僅二十餘首，尚缺二十首左右。","據前引各文所述，未見者有《饒州鄱陽亭》、《夜贈樂官》、《芋江驛灣》、《贈智光上人》等。","又按：《朝鮮文學史》錄崔匡裕《長安春日有感》云：「麻衣難拂路歧塵，鬢改顏衰曉鏡新。","上國好花愁裏艷，故園芳樹夢中春。","扁舟煙月思浮海，羸馬關河倦問津。","只爲未酬螢雪志，綠楊鶯語太傷神。","」又謂其另有《郊居呈知己》、《憶南李處士》等詩，崔承祐有《送曹松入羅浮》、朴仁範有《九成宮懷古》、《涇州龍朔寺》、《江行呈張秀才》詩。","諸詩皆新羅人在唐時所作，因未注出處，世次不明，又僅錄一首，姑附識於此。","）。"]', '["烟巒簇簇水溶溶，镜裏人家对碧峰。","何处孤帆飽风去，瞥然飞鸟杳無踪。","（錄自韋旭升《朝鲜文学史》）（按：據金东勳说，崔诗除《全唐诗逸》及《桂苑笔耕集》〖已收《全唐诗補逸》〗所收外，《三国史記》存五首，《东文選》收三十首，另见於石刻、方志者尚有十餘首，共存百首左右。","今所得僅二十餘首，尚缺二十首左右。","據前引各文所述，未见者有《饒州鄱陽亭》、《夜贈乐官》、《芋江驛灣》、《贈智光上人》等。","又按：《朝鲜文学史》錄崔匡裕《长安春日有感》云：「麻衣难拂路歧塵，鬢改顏衰晓镜新。","上国好花愁裏艷，故园芳樹梦中春。","扁舟煙月思浮海，羸马关河倦问津。","只爲未酬螢雪志，綠楊鶯語太傷神。","」又謂其另有《郊居呈知己》、《憶南李处士》等诗，崔承祐有《送曹松入羅浮》、朴仁範有《九成宮懷古》、《涇州龙朔寺》、《江行呈張秀才》诗。","諸诗皆新羅人在唐时所作，因未注出处，世次不明，又僅錄一首，姑附識於此。","）。"]', '诗', 'shi', '', NULL, '臨鏡臺 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('214c74a9-c04a-4830-b7a3-6eb38f9c3437', '下第商山對緋桃', '下第商山对緋桃', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["半夜東風力，霞光一片新。","細看初着雨，繁豔欲燒人。","得意開當日，無言空過春。","東堂失意客，歸去倍傷神。","（影印本《詩淵》第四冊第二五二一頁）。"]', '["半夜东风力，霞光一片新。","細看初着雨，繁豔欲燒人。","得意开當日，無言空過春。","东堂失意客，归去倍傷神。","（影印本《诗淵》第四冊第二五二一頁）。"]', '诗', 'shi', '', NULL, '下第商山對緋桃 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d69090f-0fc9-4714-9a71-522b9e64e199', '旅館', '旅館', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["對坐庭梧下，風凉月色新。","遠砧來迥夜，孤館未眠人。","何計成他事，唯憂老此身。","不知霄漢路，誰與脫凡鱗？","（同前第五冊第三三六八頁）。"]', '["对坐庭梧下，风凉月色新。","远砧来迥夜，孤館未眠人。","何計成他事，唯憂老此身。","不知霄漢路，誰與脫凡鱗？","（同前第五冊第三三六八頁）。"]', '诗', 'shi', '', NULL, '旅館 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd84015-0bf8-442a-9d48-cdf32de1e6e9', '送人歸新羅', '送人归新羅', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["巨浸隔鄉關，離城日已殘。","日將程共遠，風與浪爭難。","岸盡霞光落，天光海色寒。","扶桑歸到後，萬里夢長安。","（同前第六冊第四三八二頁）。"]', '["巨浸隔乡关，離城日已殘。","日將程共远，风與浪爭难。","岸尽霞光落，天光海色寒。","扶桑归到後，万里梦长安。","（同前第六冊第四三八二頁）。"]', '诗', 'shi', '', NULL, '送人歸新羅 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2dd59a7-443e-4db0-8c6f-9a732e904495', '送人游交趾', '送人游交趾', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["掛席天涯去，想君萬里心。","人間無別業，海外訪知音。","浪歇龍涎聚，沙虛象跡深。","往來應隔闊，須自惜光陰。","（同前第四四四九頁）。"]', '["掛席天涯去，想君万里心。","人间無別業，海外訪知音。","浪歇龙涎聚，沙虛象跡深。","往来應隔闊，須自惜光陰。","（同前第四四四九頁）。"]', '诗', 'shi', '', NULL, '送人游交趾 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b8517b9-f00c-4092-ba4b-c665ffd63395', '句', '句', '6b71f76b-b86e-4914-ba4f-e60f6962f4d9', '唐', '["天漢尚不正，河源爭得清。","（見曾慥《類說》卷十二《紀異記》引）（〖1〗《紀異記》：「王輿有詩名，嘗有一聯云：『天漢尚不正，河源爭得清。","』崔胤相國聞之，大不悅。","竟流落而死。","」按：南唐時有王輿，事烈祖，似與此詩作者無涉。","）。"]', '["天漢尚不正，河源爭得清。","（见曾慥《類说》卷十二《紀異記》引）（〖1〗《紀異記》：「王輿有诗名，嘗有一聯云：『天漢尚不正，河源爭得清。","』崔胤相国闻之，大不悅。","竟流落而死。","」按：南唐时有王輿，事烈祖，似與此诗作者無涉。","）。"]', '诗', 'shi', '', NULL, '句 王輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af97d4a-b03d-470d-8a94-f0544ac5e5a2', '蟋蟀詩', '蟋蟀诗', 'eb2b70a6-f85f-43ef-81c4-23bbd4269af3', '唐', '["無風來竹院，有月在沙（《詩學指南》本作「莎」）亭。","（見《吟窗雜錄》卷十四《詩中旨格》）。"]', '["無风来竹院，有月在沙（《诗学指南》本作「莎」）亭。","（见《吟窗杂錄》卷十四《诗中旨格》）。"]', '诗', 'shi', '', NULL, '蟋蟀詩 尚顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5161dbd-3852-4db6-b11a-dccd7f7627d9', '句', '句', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["舟歸范蠡五湖上，國破西施一笑中。","（見《吟窗雜錄》卷十三《進士王氏詩要格律》。","）。"]', '["舟归范蠡五湖上，国破西施一笑中。","（见《吟窗杂錄》卷十三《進士王氏诗要格律》。","）。"]', '诗', 'shi', '', NULL, '句 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094c8577-b51e-4ed6-a9fd-14bbeb6b2492', '五言長句', '五言长句', '7d037308-eeeb-40f8-b324-260bceb0018c', '唐', '["此境極岧嶤，登臨近斗杓。","天元諸聖會，地勢萬峰朝。","西揖崑丘峻，東連蓬海遙。","泉甘生玉頂，壇穩壓金腰。","泰華三峰立，黃河一帶漂。","五更觀海日，半夜聽簫韶。","落月低龍嶺，寒煙鎖虹橋。","雪鷄聲喔喔，風竹韻蕭蕭。","雲屋香煙起，芝燈瑞彩銷。","麻籠騰秀氣，藥櫃顯靈苗。","丹井猶清淺，神鐘又寂寥。","八岡齊岌岌，雙鶴對飄飄。","瀑水銀垂線，霞城綺建標。","池清深見底，柏聳翠凌霄。","道館新居壯，真公舊事遼。","幾瞻青嶂上，時有白雲飄。","石室虛難問，臺松老不凋。","巖花鋪錦繡，溪溜漱瓊瑤。","洞壑非塵趣，林巒隔世囂。","軒皇開綵仗，王母閴鸞軺。","旦暮陰陽變，炎涼節候調。","暝猿啼復歇，晴靄合還消。","歌詠聊能紀，工夫豈易描？","妙齡希郄桂，晚歲樂顏瓢。","有志追伊霍，無才佐舜堯。","披圖常景仰，酒翰益傾翹。","聲色情俱泯，希夷興已超。","何當歸卜隱，高蹈訪松喬。"]', '["此境極岧嶤，登臨近斗杓。","天元諸聖會，地勢万峰朝。","西揖崑丘峻，东連蓬海遙。","泉甘生玉頂，壇穩壓金腰。","泰华三峰立，黄河一带漂。","五更观海日，半夜听簫韶。","落月低龙嶺，寒煙鎖虹橋。","雪鷄声喔喔，风竹韻蕭蕭。","云屋香煙起，芝灯瑞彩銷。","麻籠腾秀氣，藥櫃显靈苗。","丹井猶清淺，神鐘又寂寥。","八岡齊岌岌，雙鹤对飄飄。","瀑水銀垂線，霞城綺建標。","池清深见底，柏聳翠凌霄。","道館新居壯，真公旧事遼。","幾瞻青嶂上，时有白云飄。","石室虛难问，台松老不凋。","巖花鋪錦繡，溪溜漱瓊瑤。","洞壑非塵趣，林巒隔世囂。","軒皇开綵仗，王母閴鸾軺。","旦暮陰陽变，炎涼節候調。","暝猿啼复歇，晴靄合還消。","歌詠聊能紀，工夫豈易描？","妙齡希郄桂，晚歲乐顏瓢。","有志追伊霍，無才佐舜堯。","披圖常景仰，酒翰益傾翹。","声色情俱泯，希夷兴已超。","何當归卜隐，高蹈訪松喬。"]', '诗', 'shi', '', NULL, '五言長句 林仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6f0e9ad-4ad7-4376-9d4c-5fa0e0b0865c', '七言三首 一', '七言三首 一', '7d037308-eeeb-40f8-b324-260bceb0018c', '唐', '["萬壑松蘿拂紫煙，丹臺秘邃集神仙。","乾坤結秀真靈嶽，日月飛根照洞天。","塵世暗移知幾代，蟠桃初熟未經年。","時人莫測幽微事，五色雲封種王田。"]', '["万壑松蘿拂紫煙，丹台秘邃集神仙。","乾坤結秀真靈嶽，日月飞根照洞天。","塵世暗移知幾代，蟠桃初熟未經年。","时人莫測幽微事，五色云封種王田。"]', '诗', 'shi', '', NULL, '七言三首 一 林仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df438850-e841-42e6-be92-da7c1ada4bb9', '七言三首 二', '七言三首 二', '7d037308-eeeb-40f8-b324-260bceb0018c', '唐', '["清虛小有洞中天，銀座金腰玉頂堅。","芝草秀從龍漢劫，丹砂結自赤明年。","洗參井紀燕蘿子，聚虎平川白水仙。","寄語避秦溝裏客，茅齋先蓋兩三椽。"]', '["清虛小有洞中天，銀座金腰玉頂堅。","芝草秀從龙漢劫，丹砂結自赤明年。","洗參井紀燕蘿子，聚虎平川白水仙。","寄語避秦溝裏客，茅斋先蓋兩三椽。"]', '诗', 'shi', '', NULL, '七言三首 二 林仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2c46e5c-7020-444a-b9a5-cd5e9390ec57', '七言三首 三', '七言三首 三', '7d037308-eeeb-40f8-b324-260bceb0018c', '唐', '["白石磷磷上接天，青松鬱鬱下臨川。","草生福地皆爲藥，人在名山總是仙。","待客遠尋巖下蕨，烹茶滿酌洞中泉。","前生恐是白雲子，今世還來臥翠顛。","（以上四首皆見《正統道藏》本杜光庭《天壇王屋山聖迹記》）。"]', '["白石磷磷上接天，青松鬱鬱下臨川。","草生福地皆爲藥，人在名山總是仙。","待客远尋巖下蕨，烹茶满酌洞中泉。","前生恐是白云子，今世還来臥翠顛。","（以上四首皆见《正統道藏》本杜光庭《天壇王屋山聖迹記》）。"]', '诗', 'shi', '', NULL, '七言三首 三 林仙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f9a4168-0a03-4115-9241-3064c61b2ddb', '七言三十韻', '七言三十韻', '19ec2758-0cb3-41a1-859c-695df661afa3', '唐', '["擺脫塵纓淡無欲，閑閱圖經尋嶽瀆。","林泉何處愜予心，收拾琴書將卜築。","崎嶇不敢千里辭，東自太行入王屋。","先探藏花塢裏春，蟠桃畢竟何時熟？","燕羅故宅陽臺宮，九龍戲珠畫幈簇。","丹井沉沉浸月明，丫髻仙童抱參斸。","昂頭貪看華蓋峰，驀然悮入紫微谷。","上方樓閣與雲閑，金碧交光射林麓。","避秦溝有避秦人，夜半聞歌《採芝曲》。","策杖窮躋瘦龍嶺，嶮似劍關西向蜀。","捫參歷井上沖真，千仞斷崖橫獨木。","自辰及酉脚力窮，恰到紫金堂下宿。","再拜新嘗太一泉，頓覺洒然消病骨。","恍兮惚兮九霄間，萬頃嵐光醒醉目。","恭叩仙壇禱真境，壇與天通隔塵俗。","銀座金腰玉頂寒，帝遣仙官分部屬。","小有中藏萬里地，都壓洞天三十六。","日精月華左右奇，黛色倚空如削玉。","東觀大海日輪紅，西望窮邊壇影綠。","煉丹爐下土猶香，抱出神丹知幾斛。","處山使者持太阿，保護聖軀誰敢黷？","王母洞深非可測，雷霆屢震蛟龍窟。","遙指三官校勘臺，樵人幾度聞絲竹。","抱朴巖前採藥童，手撚金芝身薜服。","北斗平連北斗星，自是天關通地軸。","麻籠藥櫃翠相接，瑞草靈苗香馥郁。","或聞仙犬吠仙燈，或覩仙人跨仙鹿。","奇蹤異跡難盡言，更欲題詩毛穎禿。","短歌聊寄名利人，誰肯同來伴幽獨？","一聲長嘯坐孤石，紫雲悠悠送黃鵠。","箇中疑是麻姑仙，冷笑世間光景促。","（同前）。"]', '["擺脫塵纓淡無欲，闲閱圖經尋嶽瀆。","林泉何处愜予心，收拾琴书將卜築。","崎嶇不敢千里辞，东自太行入王屋。","先探藏花塢裏春，蟠桃畢竟何时熟？","燕羅故宅陽台宮，九龙戲珠畫幈簇。","丹井沉沉浸月明，丫髻仙童抱參斸。","昂头貪看华蓋峰，驀然悮入紫微谷。","上方楼閣與云闲，金碧交光射林麓。","避秦溝有避秦人，夜半闻歌《採芝曲》。","策杖窮躋瘦龙嶺，嶮似劍关西向蜀。","捫參歷井上沖真，千仞斷崖橫独木。","自辰及酉脚力窮，恰到紫金堂下宿。","再拜新嘗太一泉，頓覺洒然消病骨。","恍兮惚兮九霄间，万頃嵐光醒醉目。","恭叩仙壇禱真境，壇與天通隔塵俗。","銀座金腰玉頂寒，帝遣仙官分部屬。","小有中藏万里地，都壓洞天三十六。","日精月华左右奇，黛色倚空如削玉。","东观大海日輪紅，西望窮邊壇影綠。","煉丹爐下土猶香，抱出神丹知幾斛。","处山使者持太阿，保護聖軀誰敢黷？","王母洞深非可測，雷霆屢震蛟龙窟。","遙指三官校勘台，樵人幾度闻絲竹。","抱朴巖前採藥童，手撚金芝身薜服。","北斗平連北斗星，自是天关通地軸。","麻籠藥櫃翠相接，瑞草靈苗香馥郁。","或闻仙犬吠仙灯，或覩仙人跨仙鹿。","奇蹤異跡难尽言，更欲題诗毛穎禿。","短歌聊寄名利人，誰肯同来伴幽独？","一声长嘯坐孤石，紫云悠悠送黄鵠。","箇中疑是麻姑仙，冷笑世间光景促。","（同前）。"]', '诗', 'shi', '', NULL, '七言三十韻 通真道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c64c56a-3682-4088-9254-e213f22ea8f0', '白雀歌（幷進表）', '白雀歌（幷進表）', '58ca46df-fe4a-4d62-bd37-f7c58d93cf79', '唐', '["白雀飛來過白亭，鼓翅翻身入帝城。","深向後宮呈寶瑞，玉樓高處送嘉聲。","白衣白鞟白紗巾，白馬銀鞍珮白纓。","自古不聞書不戰，一劍能却百萬兵。","王母本住在崑崙，爲貢白環來入秦。","漢武遙指東方朔，朕感白霞天上人。","紫亭南嶺白狼遊，爲效禎祥屬此州，昔日周王呈九尾，爭似如今耀斗牛。","白旗白紱白旄頭，白玉雕鞍白瑞鳩，築壇待拜天郊後，自有金星助冕旒。","白巖聖迹俯王都，玉女乘虛定五湖。","白廣山巔雲繚繞，人歌聖德滿長衢。","金鞍山上白犛牛，擺撼霜毛始舉頭。","遶泉百匝騰空去，保王社稷定徽猷。","白山隄下白澄津，一道長河夾岸春。","白雪梨花連萬朶，王向東樓擁白雲。","東苑西園池白蘋（王校作「蓰」），白渠流水好陽春。","六宮盡是名家子，白羅綽約玉顏新。","平河北澤白龍宮，賀拔爲王此處逢。","昨來再起興雲雨，爲贊君王瑞一同。","嵯峨萬丈聳金山，白雲凝霜古聖壇。","金鞍長掛湫南樹，神通日夜助王歡。","山出西南獨秀高，白霞爲蓋繞周遭。","山腹有泉深萬丈，白龍時復震波濤。","白樓素屏白銀鈎，砌玉龍墀對五侯。","雉尾扇移香案出，似月如霜複殿幽。","白牙歸子白鎧鑪，倚障虬蟠銜白珠。","白衣童子携白紱，宮官執持（以上在伯二五九四號卷子）銀涶盂。","應須築殿白金欄，上稟金方頂蓋圓，白玉壘階爲蹬道，工輪化出大羅天。","白衣殿下白頭臣，廣運籌謀奉一人。","白帝化高千古後，猶傳盛德比松筠。","白衣居士寫金經，誓弼人王不出庭。","八大金剛持寶杵，長當護念我王城。","白壇白社白蓮花，大聖携持薦一家。","太子福延千萬葉，王妃長降五香車。","樓成白璧鑽珠珍，五部龍軒倚桷新。","葛拱白平紅鏤頂，白龍行雨灑埃塵。","白旌神纛樹龍墀，白象銜珠盡合儀。","春光駕幸東城苑，雅樂前臨日月旗。","百官在國惣酋豪，白刃交馳未告勞。","爲感我王洪澤厚，盡能平虜展戎韜。","白裾皂履出衆羣，國舅溫恭自束身。","羅公挺拔摧兇敵，按劍先登渾舍人。","白雪山巖澣海清，六戎交臂必須平。","我王自有如神將，沙南委付宋中丞。","白屋藏金鎮國豐，進達偏能報虜戎。","樓蘭獻捷千人喜，敕賜紅袍與上功。","文通守節白如銀，出入王宮潔一身。","每向三危修令得，唯祈寶壽薦明君。","𡩕（王校作「填」）詞陳白未能休，筆勢相催白汗流。","願見金山明聖主，延齡滄海萬千秋。"]', '["白雀飞来過白亭，鼓翅翻身入帝城。","深向後宮呈寶瑞，玉楼高处送嘉声。","白衣白鞟白紗巾，白马銀鞍珮白纓。","自古不闻书不戰，一劍能却百万兵。","王母本住在崑崙，爲貢白环来入秦。","漢武遙指东方朔，朕感白霞天上人。","紫亭南嶺白狼游，爲效禎祥屬此州，昔日周王呈九尾，爭似如今耀斗牛。","白旗白紱白旄头，白玉雕鞍白瑞鳩，築壇待拜天郊後，自有金星助冕旒。","白巖聖迹俯王都，玉女乘虛定五湖。","白廣山巔云繚繞，人歌聖德满长衢。","金鞍山上白犛牛，擺撼霜毛始舉头。","遶泉百匝腾空去，保王社稷定徽猷。","白山隄下白澄津，一道长河夾岸春。","白雪梨花連万朶，王向东楼擁白云。","东苑西园池白蘋（王校作「蓰」），白渠流水好陽春。","六宮尽是名家子，白羅綽約玉顏新。","平河北澤白龙宮，賀拔爲王此处逢。","昨来再起兴云雨，爲贊君王瑞一同。","嵯峨万丈聳金山，白云凝霜古聖壇。","金鞍长掛湫南樹，神通日夜助王歡。","山出西南独秀高，白霞爲蓋繞周遭。","山腹有泉深万丈，白龙时复震波濤。","白楼素屏白銀鈎，砌玉龙墀对五侯。","雉尾扇移香案出，似月如霜複殿幽。","白牙归子白鎧鑪，倚障虬蟠銜白珠。","白衣童子携白紱，宮官執持（以上在伯二五九四號卷子）銀涶盂。","應須築殿白金欄，上稟金方頂蓋圓，白玉壘階爲蹬道，工輪化出大羅天。","白衣殿下白头臣，廣運籌謀奉一人。","白帝化高千古後，猶傳盛德比松筠。","白衣居士寫金經，誓弼人王不出庭。","八大金剛持寶杵，长當護念我王城。","白壇白社白蓮花，大聖携持薦一家。","太子福延千万葉，王妃长降五香车。","楼成白璧鑽珠珍，五部龙軒倚桷新。","葛拱白平紅鏤頂，白龙行雨灑埃塵。","白旌神纛樹龙墀，白象銜珠尽合儀。","春光駕幸东城苑，雅乐前臨日月旗。","百官在国惣酋豪，白刃交驰未告勞。","爲感我王洪澤厚，尽能平虜展戎韜。","白裾皂履出衆羣，国舅溫恭自束身。","羅公挺拔摧兇敵，按劍先登渾舍人。","白雪山巖澣海清，六戎交臂必須平。","我王自有如神將，沙南委付宋中丞。","白屋藏金鎮国豐，進達偏能報虜戎。","楼蘭獻捷千人喜，敕賜紅袍與上功。","文通守節白如銀，出入王宮潔一身。","每向三危修令得，唯祈寶壽薦明君。","𡩕（王校作「填」）词陳白未能休，笔勢相催白汗流。","願见金山明聖主，延齡滄海万千秋。"]', '诗', 'shi', '', NULL, '白雀歌（幷進表） 張永進 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f9447c-48bf-4e40-a0b8-5a01968c9688', '頌曰', '頌曰', '58ca46df-fe4a-4d62-bd37-f7c58d93cf79', '唐', '["白銀槍懸太白旗，白虎三旌三戟枝。","五方色中白爲上，不是我王爭得知。","樓成白璧聳儀形，蜀地求才讚聖明。","自從湯帝昇遐後，白雀無因宿帝廷。","今來降瑞報成康，果見河西再冊[王]（玉）。","韓白滿朝謀似雨，國門長鎮成燉煌。","（以上二首均見伯二五九四、伯二八六四卷，參王重民《金山國墜簡零拾》，收入《敦煌遺書論文集》）。"]', '["白銀槍懸太白旗，白虎三旌三戟枝。","五方色中白爲上，不是我王爭得知。","楼成白璧聳儀形，蜀地求才讚聖明。","自從湯帝昇遐後，白雀無因宿帝廷。","今来降瑞報成康，果见河西再冊[王]（玉）。","韓白满朝謀似雨，国门长鎮成燉煌。","（以上二首均见伯二五九四、伯二八六四卷，參王重民《金山国墜簡零拾》，收入《敦煌遺书論文集》）。"]', '诗', 'shi', '', NULL, '頌曰 張永進 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024c8fe2-6196-4be7-8de3-ced338a34b6e', '龍泉神劍歌', '龙泉神劍歌', 'def60cbc-5b5a-458b-9010-da41149bfb04', '唐', '["龍泉寶劍出豐城，彩氣衝天上接辰。","不獨漢朝今亦有，金鞍山下是長津。","天符下降到龍沙，便有明君膺紫霞，天子猶來是天補，橫截河西是一家。","堂堂美貌實天顏，□德昂藏鎮玉關。","國號金山白衣帝，應須早築拜天壇。","日月雙旌耀虎旗，御樓寶砌建丹墀。","出警從茲排法駕，每行青道要先和。","我帝金懷海量□（疑爲「寬」字），目似流星鼻筆端。","相好與堯同一體，應知天分數千般。","一從登極未逾年，德比陶唐初受禪。","百靈効祉賀鴻壽，足踏坤維手握乾。","明明聖日出當時，上膺星辰下有期。","神劍新磨須使用，定疆廣宇未爲遲。","東取河蘭廣武城，西取天山澣海軍。","北掃燕然□嶺鎮，南盡戎羗邏莎平。","三軍壯，甲馬興，萬里橫行河湟清。","結親只爲圖長國，永霸龍沙截海鯨。","我帝威雄人未知，叱吒風雲自有時。","祁連山下留名迹，破却甘州必□遲。","金風初動虜兵來，點齪干戈會將臺。","戰馬鐵衣舖雁翅，金河東岸陣雲開。","慕良將，揀人材，出天入地選良枚（王錄作「牧」，近是，惟不協韻）。","先鋒委付渾鷂子，須向將軍劍下摧。","左右衝□搏虜塵，疋馬單槍陰舍人，前衝虜連渾穿透，一段英雄遠近聞。","前日城東出戰場，馬步相兼一萬強。","我皇親換黃金甲，周遭盡布陰沈槍。","着胄匈奴活捉得，退去□竪劍下亡。","千渠三堡鐵衣明，左繞無窮授四城。","宜秋下邑摧兇醜，當鋒入陣宋中丞。","內臣更有張舍人，小小年內則伏勤。","自從戰伐先登陣，不懼危亡□□身。","今年迴鶻數侵疆，直到便橋刊戰場。","當鋒直入陰仁貴，不使戈鋋解用槍。","堪賞給，早商量，寵拜金吾超上將。","急要名聲貫帝鄉，軍都日日更英雄。","□由東行大漠中，短兵自有張西豹，遮收遏後與羅公。","蕃漢精兵一萬強，打却甘州坐五涼。","東取黃河第三曲，南取雄威及朔方。","通同一個金山國，子孫分付坐敦煌。","□番從此永歸投，撲滅狼星壯斗牛。","北庭今載和□□，兼護澣海與西州，改年號，掛龍衣，築壇拜却南郊後，始號沙州作京畿。","嗣祖考，繼宗枝，七廟不封何饗拜。","祖父丕功故尚書，冊□□□□尊姻。","北堂永須傳金印，天子猶來重二親。","臣獻□歌流萬古，金山繚繞起秦雪。","今朝以日羅公至，搦起紅旗似躍塵。","今年收復甘州後，百寮舞蹈賀明君。","（見伯三六三三卷。","據今人李正宇錄本，以王重民《金山國墜簡零拾》所引參校）。"]', '["龙泉寶劍出豐城，彩氣衝天上接辰。","不独漢朝今亦有，金鞍山下是长津。","天符下降到龙沙，便有明君膺紫霞，天子猶来是天補，橫截河西是一家。","堂堂美貌實天顏，□德昂藏鎮玉关。","国號金山白衣帝，應須早築拜天壇。","日月雙旌耀虎旗，御楼寶砌建丹墀。","出警從茲排法駕，每行青道要先和。","我帝金懷海量□（疑爲「寬」字），目似流星鼻笔端。","相好與堯同一體，應知天分數千般。","一從登極未逾年，德比陶唐初受禪。","百靈効祉賀鴻壽，足踏坤維手握乾。","明明聖日出當时，上膺星辰下有期。","神劍新磨須使用，定疆廣宇未爲遲。","东取河蘭廣武城，西取天山澣海軍。","北掃燕然□嶺鎮，南尽戎羗邏莎平。","三軍壯，甲马兴，万里橫行河湟清。","結親只爲圖长国，永霸龙沙截海鯨。","我帝威雄人未知，叱吒风云自有时。","祁連山下留名迹，破却甘州必□遲。","金风初动虜兵来，点齪干戈會將台。","戰马鐵衣舖雁翅，金河东岸陣云开。","慕良將，揀人材，出天入地選良枚（王錄作「牧」，近是，惟不協韻）。","先鋒委付渾鷂子，須向將軍劍下摧。","左右衝□搏虜塵，疋马單槍陰舍人，前衝虜連渾穿透，一段英雄远近闻。","前日城东出戰場，马步相兼一万強。","我皇親換黄金甲，周遭尽布陰沈槍。","着胄匈奴活捉得，退去□竪劍下亡。","千渠三堡鐵衣明，左繞無窮授四城。","宜秋下邑摧兇醜，當鋒入陣宋中丞。","內臣更有張舍人，小小年內則伏勤。","自從戰伐先登陣，不懼危亡□□身。","今年迴鶻數侵疆，直到便橋刊戰場。","當鋒直入陰仁貴，不使戈鋋解用槍。","堪賞給，早商量，寵拜金吾超上將。","急要名声貫帝乡，軍都日日更英雄。","□由东行大漠中，短兵自有張西豹，遮收遏後與羅公。","蕃漢精兵一万強，打却甘州坐五涼。","东取黄河第三曲，南取雄威及朔方。","通同一個金山国，子孫分付坐敦煌。","□番從此永归投，撲滅狼星壯斗牛。","北庭今載和□□，兼護澣海與西州，改年號，掛龙衣，築壇拜却南郊後，始號沙州作京畿。","嗣祖考，繼宗枝，七廟不封何饗拜。","祖父丕功故尚书，冊□□□□尊姻。","北堂永須傳金印，天子猶来重二親。","臣獻□歌流万古，金山繚繞起秦雪。","今朝以日羅公至，搦起紅旗似躍塵。","今年收复甘州後，百寮舞蹈賀明君。","（见伯三六三三卷。","據今人李正宇錄本，以王重民《金山国墜簡零拾》所引參校）。"]', '诗', 'shi', '', NULL, '龍泉神劍歌 張文徹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa2c91b-8b9b-4e8e-8d46-bb2b017c5426', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 一', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵之道，切忌起無名。","不止（京本作「正」）少功虛效力，逡巡反（川本作「及」）禍復（京本作「復禍」）危傾。","容易勿言兵。"]', '["兵之道，切忌起無名。","不止（京本作「正」）少功虛效力，逡巡反（川本作「及」）禍复（京本作「复禍」）危傾。","容易勿言兵。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad0248d-c5f9-44aa-8922-0ecb3d500f06', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍（京本作「兵」）帥，不可比[鹽]（醎）（據川本、辛本、京本改）梅。","相政乖虧猶可救，朝綱雖失亦能回，兵敗國傾危。"]', '["統軍（京本作「兵」）帥，不可比[鹽]（醎）（據川本、辛本、京本改）梅。","相政乖虧猶可救，朝綱雖失亦能回，兵敗国傾危。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947bf0cc-02d1-46cf-a615-255323753607', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 三', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["當權將，其責重如山。","社稷存亡全在爾，安危君父一時間。","須要立功還（川本、辛本作「爵祿帝王頒」）。"]', '["當權將，其責重如山。","社稷存亡全在爾，安危君父一时间。","須要立功還（川本、辛本作「爵祿帝王頒」）。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc0c903-dd96-49ef-8d16-a83b32e82d21', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 四', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["銓大將（京本作「帥」），須要素知（京本作「司」）[兵]（名）（據辛本、川本、京本改。","）非是等閒虛譽職，莫將軍印（京本作「兵柄」）任（辛本、川本作「委」、京本作「付」）狂生，輕擁甲兵行。"]', '["銓大將（京本作「帥」），須要素知（京本作「司」）[兵]（名）（據辛本、川本、京本改。","）非是等閒虛譽職，莫將軍印（京本作「兵柄」）任（辛本、川本作「委」、京本作「付」）狂生，轻擁甲兵行。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c83909-db58-4074-b233-8a105495a181', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 五', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸屬幕，必（京本作「須」）是選賢（辛本、川本作「堪」、京本作「沉」）良。","勿取（京本作「使」）門高（京本作「風」）當勢位，無私親舊與鄉邦（京本作「同鄉」）。","曲順（京本作「邪曲」）定爲殃。"]', '["諸屬幕，必（京本作「須」）是選賢（辛本、川本作「堪」、京本作「沉」）良。","勿取（京本作「使」）门高（京本作「风」）當勢位，無私親旧與乡邦（京本作「同乡」）。","曲順（京本作「邪曲」）定爲殃。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16f367c-c970-40d0-900c-fd7c2df2c47c', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 六', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["攻敵策，謀乃勝之原（京本作「源」）。","勿使（辛本、川本、京本作「祗」）迎兵（京本作「軍」）交血刃，休憑角（京本作「勇」）力靠兵官，勇是禍之端。","（經曰：善戰者不怒，善勝者不爭。","非智者不能行，非賢者不能用也。","）。"]', '["攻敵策，謀乃勝之原（京本作「源」）。","勿使（辛本、川本、京本作「祗」）迎兵（京本作「軍」）交血刃，休憑角（京本作「勇」）力靠兵官，勇是禍之端。","（經曰：善戰者不怒，善勝者不爭。","非智者不能行，非賢者不能用也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a84f4f74-669f-47cf-9362-9136d5fde4d6', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 七', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍帥，智慮有明謀。","善識天文能勇敢，更兼威德賞勤勞。","士卒自英豪。"]', '["統軍帥，智慮有明謀。","善識天文能勇敢，更兼威德賞勤勞。","士卒自英豪。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a61cd72-2a1e-4b09-a515-4ef3b5188056', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 八', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["爲將帥，筮卜識機緣。","更用一人高術士，精通占候要知言，凶吉預聞先。"]', '["爲將帥，筮卜識機緣。","更用一人高術士，精通占候要知言，凶吉預闻先。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b8aa14f-b88f-4ec4-9205-35b93370b061', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 九', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["覘彼勢，虛實要先評。","兵有正奇將勝敗（京本作「關將敏」），有（京本作「勢」）無強弱在軍精（辛本作「情」），料敵不須驚。"]', '["覘彼勢，虛實要先評。","兵有正奇將勝敗（京本作「关將敏」），有（京本作「勢」）無強弱在軍精（辛本作「情」），料敵不須驚。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252d50a5-51e5-4da6-b19d-356760fc3de0', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["量彼敵，將勇戒驕盈。","整暇正須期死戰，凱旋猶懼有驕（辛本、京本作「生」）兵，養氣勿輕迎（辛本作「臨」）。"]', '["量彼敵，將勇戒驕盈。","整暇正須期死戰，凱旋猶懼有驕（辛本、京本作「生」）兵，養氣勿轻迎（辛本作「臨」）。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d16bbfb2-23cd-4e1a-964e-de5afaa954aa', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十一', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["戰危事，上將戒貪行（辛本作「兵」）。","閫（京本作「國」）計豈應（辛本作「能」，京本作「令」）求（京本作「圖」）小利，師行自古有常經，紀律要精明。"]', '["戰危事，上將戒貪行（辛本作「兵」）。","閫（京本作「国」）計豈應（辛本作「能」，京本作「令」）求（京本作「圖」）小利，師行自古有常經，紀律要精明。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe14394a-5b8a-4d30-bf04-0931b33a7d92', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十二', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["參彼將，德（京本作「得」）性好攻心。","仔細究情（辛本作「精」）隨彼好，中行離[反]（問）（據辛本、京本改）詭相親，設利誘前擒。","（覆兵敗將，攻其便，究其情，伐其機。","）。"]', '["參彼將，德（京本作「得」）性好攻心。","仔細究情（辛本作「精」）隨彼好，中行離[反]（问）（據辛本、京本改）詭相親，設利誘前擒。","（覆兵敗將，攻其便，究其情，伐其機。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175bb395-30f2-427c-ad23-f97a0b11d38e', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十三', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍將（辛本、川本作「兵帥」），剛暴自殘兵。","有勇有勞無賞罰，却將傲慢事行刑，彼將定欺淩。"]', '["統軍將（辛本、川本作「兵帥」），剛暴自殘兵。","有勇有勞無賞罰，却將傲慢事行刑，彼將定欺淩。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1a577b-0774-4725-a95e-57bfefc6b02b', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十四', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["審向道（京本作「彼將」），測（京本作「斥」，辛本作「情」）候要分明。","莫爲時多蒙（辛本作「朦」）躁進（京本作「莫與兵徒萌躁進」），勿從剛暴速兼程，慮（京本作「虞」）彼伏潛兵。"]', '["審向道（京本作「彼將」），測（京本作「斥」，辛本作「情」）候要分明。","莫爲时多蒙（辛本作「朦」）躁進（京本作「莫與兵徒萌躁進」），勿從剛暴速兼程，慮（京本作「虞」）彼伏潛兵。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be2326d-924d-456f-bde8-22140b6443f3', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十五', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["途頓止，調節要（京本作「力」）均停。","力若有餘兵有（京本作「軍自」）鋭，縱逢強賊（京本作「卒逢賊馬」）亦堪征，不致有惶驚。"]', '["途頓止，調節要（京本作「力」）均停。","力若有餘兵有（京本作「軍自」）鋭，縱逢強賊（京本作「卒逢賊马」）亦堪征，不致有惶驚。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('512fcfba-4101-4d08-8450-d712c8480f12', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十六', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["量強弱，彼我孰優長？","敵若勢雄兵將廣（辛本作「兵將廣大」），吾軍衰弱亦（京本作「何弱力」）難當，主帥要參詳（京本作「奇計可施張」）。","。"]', '["量強弱，彼我孰優长？","敵若勢雄兵將廣（辛本作「兵將廣大」），吾軍衰弱亦（京本作「何弱力」）难當，主帥要參詳（京本作「奇計可施張」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c7ddb0-fa3a-48d7-bbe0-6dfbfbbbac15', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十七', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將權柄，識務辨（京本作「職務長」）春秋。","須是先施仁與惠，後行刑戮（京本作「獄」）擇其尤（辛本作「由」），威令（辛本、京本作「愛」）自然收。"]', '["將權柄，識務辨（京本作「職務长」）春秋。","須是先施仁與惠，後行刑戮（京本作「獄」）擇其尤（辛本作「由」），威令（辛本、京本作「愛」）自然收。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4d503d-87ab-407a-9283-306b00102fd8', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十八', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["賞與罰，須是要均平。","不可狥（辛本作「循」）私行喜怒，稍（京本作「私」）偏親舊失軍情，如此（辛本、京本作「否則」）禍灾生。"]', '["賞與罰，須是要均平。","不可狥（辛本作「循」）私行喜怒，稍（京本作「私」）偏親旧失軍情，如此（辛本、京本作「否則」）禍灾生。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1a8376-8f7f-40d9-b3a6-54872e7df8c6', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十九', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["水與陸，兩勢作艟{舟朋}。","陸有勢形水（京本作「湖」）亦有，舟車捷力（京本作「利」）不相爭，專在將能明。"]', '["水與陸，兩勢作艟{舟朋}。","陸有勢形水（京本作「湖」）亦有，舟车捷力（京本作「利」）不相爭，專在將能明。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f8831b-6d09-4571-9da6-5a43c3d95311', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍帥，不可妄行刑。","莫以軍威行殺戮，人生一失永無生，誤損命天嗔。"]', '["統軍帥，不可妄行刑。","莫以軍威行殺戮，人生一失永無生，誤損命天嗔。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6239f50e-35cd-443f-826f-197de56ae0ba', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十一', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍帥，職爵受皇恩。"]', '["統軍帥，職爵受皇恩。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12bc7190-fc8a-4ea9-976a-d797672f5ddc', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十二', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["如信佞，叛背事皆訛。","自古兩邦難並立（辛本、川本作「立廟」），當朝忠孝賜恩多，世代盡包羅。"]', '["如信佞，叛背事皆訛。","自古兩邦难並立（辛本、川本作「立廟」），當朝忠孝賜恩多，世代尽包羅。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09dc2a2d-6c23-40d6-bb1e-8466f71bc8f3', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十三', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狂（京本作「征」）寇走（辛本、川本、京本作「定」），乘馬復還京（京本作「軍」）。","結局奏（京本作「有」）功須均（京本作「當」）賞，莫將親識（京本作「舊」）冒功陞，[反]（及）（據辛本、川本、京本改）掩勇無名。"]', '["狂（京本作「征」）寇走（辛本、川本、京本作「定」），乘马复還京（京本作「軍」）。","結局奏（京本作「有」）功須均（京本作「當」）賞，莫將親識（京本作「旧」）冒功陞，[反]（及）（據辛本、川本、京本改）掩勇無名。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433354b8-0df8-4730-a23b-6baf5e13dc76', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十四', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鋒（辛本、川本作「蜂」、京本作「封」）城壘，謹守保邊隅。","莫恃雄強侵彼境，復從奸佞起兵夫。","虛國死無辜。"]', '["鋒（辛本、川本作「蜂」、京本作「封」）城壘，謹守保邊隅。","莫恃雄強侵彼境，复從奸佞起兵夫。","虛国死無辜。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83161a1e-2c8e-4097-92db-03cafbc948ed', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十五', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太平世，積食（京本作「粟」）養雄兵。","不可輒忘征戰意（京本作「備」），常時論武（京本作「常須講習」）使兵（辛本、川本作「令」）精，防寇犯（京本作「彼寇」）邊庭。"]', '["太平世，積食（京本作「粟」）養雄兵。","不可輒忘征戰意（京本作「備」），常时論武（京本作「常須講習」）使兵（辛本、川本作「令」）精，防寇犯（京本作「彼寇」）邊庭。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9cc812-ccbe-49b0-88ed-3faca70785e0', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十六', '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["吾勢鋭，人馬總精雄。","財寶（京本作「貨」）滿盈軍用足（辛本、川本、京本作「足用」），更詳天象審蒼穹，灾禍免（辛本、川本、京本作「那」）軍中。","（經曰：「用兵者，非信義不立，非陰陽不順，非奇正不列，非詭譎不戰，謀藏於心，事見於迹，心與迹同者敗，心與迹異者勝。","」）。"]', '["吾勢鋭，人马總精雄。","財寶（京本作「貨」）满盈軍用足（辛本、川本、京本作「足用」），更詳天象審蒼穹，灾禍免（辛本、川本、京本作「那」）軍中。","（經曰：「用兵者，非信義不立，非陰陽不順，非奇正不列，非詭譎不戰，謀藏於心，事见於迹，心與迹同者敗，心與迹異者勝。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 委任第一（京本作「占委任第一」二十六首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ea17c3-4d62-468b-a7fd-d68f69b28072', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 一', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["興兵道，風角最爲先。","若是逆風（辛本、川本作「迎風」）權且住，後來風助合蒼天，大戰我當先。"]', '["兴兵道，风角最爲先。","若是逆风（辛本、川本作「迎风」）權且住，後来风助合蒼天，大戰我當先。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b93e10-ab60-45d4-8f78-c71643fbceac', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["春屬木，風自震方來。","纔起微微聲不大，終無禍福不須猜。","疑慮却成災。"]', '["春屬木，风自震方来。","纔起微微声不大，終無禍福不須猜。","疑慮却成災。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e743a43f-eeb3-4231-89e8-eadf52fe4573', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["離與兌，壬癸子（辛本、川本、京本作「自」）三方。","飄作如春依逐分，不須多慮與張惶，有寇整兵當。"]', '["離與兌，壬癸子（辛本、川本、京本作「自」）三方。","飄作如春依逐分，不須多慮與張惶，有寇整兵當。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705a0532-f11e-40e1-a2ab-63cdc7a09aff', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 四', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["四季內，或（京本作「忽」）有猛風聲。","倒（京本作「捲」）瓦揚沙急（京本作「幾」）似箭，隨來方所擺（京本作「擁」）精兵，急備彼軍情（辛本、川本作「人」，京本作「急急備軍人」）。"]', '["四季內，或（京本作「忽」）有猛风声。","倒（京本作「捲」）瓦揚沙急（京本作「幾」）似箭，隨来方所擺（京本作「擁」）精兵，急備彼軍情（辛本、川本作「人」，京本作「急急備軍人」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c084ff1-6615-4e65-94fe-84964c7b724c', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 五', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛風過，如箭便（京本作「更」）無踪，名曰{風昔}{風革}當速備，風聲纔斷賊來攻，日後（京本作「日入」）愈爲凶。"]', '["猛风過，如箭便（京本作「更」）無踪，名曰{风昔}{风革}當速備，风声纔斷賊来攻，日後（京本作「日入」）愈爲凶。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148af7e1-9136-44dd-9cb2-fad4aaab9a44', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 六', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，[黯黯]（點點）（據辛本、京改）久陰沉。","不雨又無光色現，下人謀上恨情深，細意要搜尋。"]', '["兵行次，[黯黯]（点点）（據辛本、京改）久陰沉。","不雨又無光色現，下人謀上恨情深，細意要搜尋。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394bf6cb-4137-4efb-b1c4-a471d904cca3', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 七', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍出（京本作「離」）國，風自背邊生（京本作「興」）。","大則大贏爲大勝（京本作「吉兆」），小風小勝總堪征，天意助吾行。"]', '["軍出（京本作「離」）国，风自背邊生（京本作「兴」）。","大則大贏爲大勝（京本作「吉兆」），小风小勝總堪征，天意助吾行。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b01abf8-0b78-4ca3-8514-1fd9ac3eb077', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 八', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍（京本作「兵」）大舉，方出帝王城。","逆面風來軍恐懼，合將人馬結營停，守過待時更（京本作「行」）。"]', '["軍（京本作「兵」）大舉，方出帝王城。","逆面风来軍恐懼，合將人马結營停，守過待时更（京本作「行」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a9de63-b8af-49c0-bd32-15f7773865de', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 九', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行次，風猛逆狂吹。","出陣若逢如此兆，不如抽退得全歸，免損將兵（辛本、川本作「軍」）危。"]', '["軍行次，风猛逆狂吹。","出陣若逢如此兆，不如抽退得全归，免損將兵（辛本、川本作「軍」）危。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0baa42a-7c56-4566-81ad-be574e0bc9df', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["吾撃彼，參審（京本作「審彼」）主人方。","莫問四時並氣候，風來後助便（辛本、川本作「得」）無妨（京本作「休論刑殺旺衰鄉」），逆面主灾殃（辛本、川本作「迎面莫征狂」，京本作「風要細推詳」）。"]', '["吾撃彼，參審（京本作「審彼」）主人方。","莫问四时並氣候，风来後助便（辛本、川本作「得」）無妨（京本作「休論刑殺旺衰乡」），逆面主灾殃（辛本、川本作「迎面莫征狂」，京本作「风要細推詳」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cba493d-d41b-4667-a2f6-9e21512b6bce', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十一', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["敵居所，風起自他方。","便有精兵宜固守，若言舉動禍之殃，實語莫猜量。"]', '["敵居所，风起自他方。","便有精兵宜固守，若言舉动禍之殃，實語莫猜量。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282d5e5c-9ffc-4ea3-a933-1c9bdc15f1ef', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十二', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["假令（京本作「今」）法，且論在三冬。","彼國守乾吾欲討，風生（辛本、川本、京本作「顛」）西北不堪征（京本作「攻」），以此較餘宮。","。"]', '["假令（京本作「今」）法，且論在三冬。","彼国守乾吾欲討，风生（辛本、川本、京本作「顛」）西北不堪征（京本作「攻」），以此較餘宮。","。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb26041a-a763-4b34-886e-2dd24ffc58db', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十三', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雖是應（京本作「風雖應」），還則（京本作「即」）應他方。","也是彼贏吾負家，候（京本作「當」）其風止或攻傍（京本作「成殃」），不可不參詳（京本作「量」）。"]', '["雖是應（京本作「风雖應」），還則（京本作「即」）應他方。","也是彼贏吾負家，候（京本作「當」）其风止或攻傍（京本作「成殃」），不可不參詳（京本作「量」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ac6f39-d3bc-406e-9e9c-29dbaae8970b', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十四', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["假令法，彼國在離間。","我擁軍前（辛本、川本作「前軍」、京本作「全軍」）時正夏，南征（辛本、川本、京本作「侵」）北敵（京本作「狄」）苦冬寒。","隨象撃傾（京本作「急摧」）殘。"]', '["假令法，彼国在離间。","我擁軍前（辛本、川本作「前軍」、京本作「全軍」）时正夏，南征（辛本、川本、京本作「侵」）北敵（京本作「狄」）苦冬寒。","隨象撃傾（京本作「急摧」）殘。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8482d78-ccd2-4eeb-9515-2d97d139e7e7', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十五', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["八方法，推（辛本、川本、京本作「准」）此定成功。","好事（京本作「是」）急乘他事（辛本、川本、京本作「氣」）逆，勿拘朝暮速吞攻（京本作「功」），莫放彼從容。"]', '["八方法，推（辛本、川本、京本作「准」）此定成功。","好事（京本作「是」）急乘他事（辛本、川本、京本作「氣」）逆，勿拘朝暮速吞攻（京本作「功」），莫放彼從容。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb279cc-b613-49ff-9053-24d0d5a4b4b2', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十六', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["己亥角，辰[戌]（成）（從辛本、京本改）便爲商。","丑未寅甲皆（京本作「俱」）屬[徴]（子）（據辛本、京本改），宮音子午正相當，卯酉羽爲方（京本作「旁」）。"]', '["己亥角，辰[戌]（成）（從辛本、京本改）便爲商。","丑未寅甲皆（京本作「俱」）屬[徴]（子）（據辛本、京本改），宮音子午正相當，卯酉羽爲方（京本作「旁」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35601d1b-ea94-45dd-9a87-5147c2401d23', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十七', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占風法，申（京本作「甲」）子是貪狼。","丑戌謂之公正位，奸邪辰位自然當。","細審（辛本、川本、京本作「審細」）看來方。"]', '["占风法，申（京本作「甲」）子是貪狼。","丑戌謂之公正位，奸邪辰位自然當。","細審（辛本、川本、京本作「審細」）看来方。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eccc9dfb-99e5-41e7-b17b-c3726795aef2', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十八', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["亥卯位（辛本、川本作「未」），陰賊內（京本作「在」）中藏。","己酉（辛本、川本、京本作「巳酉」）謂之寬大日（京本作「位」），亷貞寅午位（辛本、川本作「未」）其方，知（京本作「加」）意細推詳。"]', '["亥卯位（辛本、川本作「未」），陰賊內（京本作「在」）中藏。","己酉（辛本、川本、京本作「巳酉」）謂之寬大日（京本作「位」），亷貞寅午位（辛本、川本作「未」）其方，知（京本作「加」）意細推詳。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ed8661-a7cc-40c3-b2fe-86e82445fb68', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十九', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占飄起，客認納音風。","徴羽宮商幷角姓，盡爲主客（辛本、川本、京本作「位」）辨方蹤，勝負在其中。"]', '["占飄起，客認納音风。","徴羽宮商幷角姓，尽爲主客（辛本、川本、京本作「位」）辨方蹤，勝負在其中。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73acb629-d2c2-4d33-98c0-fe862c18344b', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["納音土，欲得角來風。","土是客軍水（京本作「本」）是主，風從己亥發來衝，客敗主收功。"]', '["納音土，欲得角来风。","土是客軍水（京本作「本」）是主，风從己亥發来衝，客敗主收功。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5970d88-b54f-4335-96c9-f8f1be37534f', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十一', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["納音土，風向羽來吹。","（卯酉位也）。","水被土淩能尅伏，定知主敗客來追，莫要展旌旗。"]', '["納音土，风向羽来吹。","（卯酉位也）。","水被土淩能尅伏，定知主敗客来追，莫要展旌旗。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3247281-5e3a-44d4-8c44-680f7011d22b', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十二', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，忽有旋風來（京本作「卯酉羽風吹」）。","吹折鎗旗幷倒屋，奸謀惡黨幷來推（辛本、川本、京本作「欲來摧」），暗有賊兵欺（京本作「來」。","又防火。","京本注：「風從內起謀在裏，風從外入賊在內。","」）。"]', '["軍營內，忽有旋风来（京本作「卯酉羽风吹」）。","吹折鎗旗幷倒屋，奸謀惡黨幷来推（辛本、川本、京本作「欲来摧」），暗有賊兵欺（京本作「来」。","又防火。","京本注：「风從內起謀在裏，风從外入賊在內。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3320e040-fa7b-4fa3-be0b-b360e29c264a', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十三', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["風來處，如式（辛本作「遇」）作泥人。","葦箭挑弓披髮向，望空搭箭射來蹤。","禳厭禍消鎔。"]', '["风来处，如式（辛本作「遇」）作泥人。","葦箭挑弓披髮向，望空搭箭射来蹤。","禳厭禍消鎔。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aadd8c95-d639-4ccc-8af1-4d8a17121bb1', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十四', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["泥人子，手執木桃弓。","披髮仰頭風上指，張弓搭箭射來蹤，禳厭禍消鎔。","（禳惡風法。","）（按：此首僅見京本，似爲前一首之別本。","）。"]', '["泥人子，手執木桃弓。","披髮仰头风上指，張弓搭箭射来蹤，禳厭禍消鎔。","（禳惡风法。","）（按：此首僅见京本，似爲前一首之別本。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十四 易靜 shi');
